    def fast_entropy_batch(states, K):
        N = states.shape[0]
        cnt = np.bincount(states, minlength=K).astype(np.float64)
        p = cnt / max(N, 1)
        p = p[p > 0]
        return float(-(p * np.log(p)).sum())

    def fast_mi_batch(s1, s2, K):
        N = s1.shape[0]
        joint = s1 * K + s2
        c1 = np.bincount(s1, minlength=K) / max(N, 1)
        c2 = np.bincount(s2, minlength=K) / max(N, 1)
        cj = np.bincount(joint, minlength=K * K).reshape(K, K) / max(N, 1)
        mask = cj > 0
        denom = np.outer(c1, c2)[mask] + 1e-12
        return max(float((cj[mask] * np.log(cj[mask] / denom)).sum()), 0.0)

    def compute_pmi_matrix(s1, s2, K):
        N = s1.shape[0]
        joint = s1 * K + s2
        c1 = (np.bincount(s1, minlength=K) / max(N, 1)) + 1e-9
        c2 = (np.bincount(s2, minlength=K) / max(N, 1)) + 1e-9
        cj = (np.bincount(joint, minlength=K * K).reshape(K, K) / max(N, 1)) + 1e-9
        return np.log(cj / np.outer(c1, c2))


