def _build_fp8_e4m3_lut():
    u8 = np.arange(256, dtype=np.uint8)
    s = (u8 >> 7) & 1
    e = (u8 >> 3) & 0xF
    m = u8 & 0x7
    val = np.empty(256, dtype=np.float32)
    normal = e > 0
    val[normal] = np.ldexp(1.0 + m[normal].astype(np.float32) * 0.125, e[normal].astype(np.int32) - 7)
    sub = ~normal
    val[sub] = np.ldexp(m[sub].astype(np.float32) * 0.125, -6)
    val[s == 1] *= -1.0
    val[(e == 15) & (m == 7)] = 0.0
    return val


_FP8_E4M3_LUT = _build_fp8_e4m3_lut()


def _fast_binary_mi(prev_mask, spiked, N):
    """Exact O(|spiked|) 2x2 mutual information between bool mask and spike indices."""
    if N <= 0:
        return 0.0
    n1 = int(np.count_nonzero(prev_mask))
    n2 = len(spiked)
    n11 = int(np.count_nonzero(prev_mask[spiked])) if n2 > 0 else 0
    n01 = n2 - n11
    n10 = n1 - n11
    n00 = N - n1 - n01
    inv_n = 1.0 / N
    p1_1 = n1 * inv_n
    p1_0 = 1.0 - p1_1
    p2_1 = n2 * inv_n
    p2_0 = 1.0 - p2_1
    mi = 0.0
    for nij, pa, pb in ((n00, p1_0, p2_0), (n01, p1_0, p2_1), (n10, p1_1, p2_0), (n11, p1_1, p2_1)):
        if nij > 0:
            pij = nij * inv_n
            mi += pij * math.log(pij / (pa * pb + 1e-12))
    return max(mi, 0.0)


# =====================================================================
# 1. Out-of-Core Streamers (Safetensors + GGUF, Zero PyTorch Needed)
# =====================================================================
class SafetensorsStreamReader:
    """Streams chunks of rows from massive .safetensors files
    (F32/F16/BF16/I8/F8_E4M3/F8_E5M2) without loading full tensors into RAM."""

    DTYPE_INFO = {
        "F32": (np.float32, 4),
        "F16": (np.float16, 2),
        "BF16": (np.uint16, 2),
        "I8": (np.int8, 1),
        "F8_E4M3": (np.uint8, 1),
        "F8_E5M2": (np.uint8, 1),
    }

    def __init__(self, model_dir):
        self.model_dir = model_dir
        self.index = {}
        self.headers = {}
        self.data_offsets = {}

        idx_path = os.path.join(model_dir, "model.safetensors.index.json")
        single_path = os.path.join(model_dir, "model.safetensors")

        if os.path.exists(idx_path):
            with open(idx_path, "r", encoding="utf-8") as fh:
                weight_map = json.load(fh)["weight_map"]
            for tname, fname in weight_map.items():
                self.index[tname] = os.path.join(model_dir, fname)
        elif os.path.exists(single_path):
            self._load_header(single_path)
            for tname in self.headers[single_path]:
                if tname != "__metadata__":
                    self.index[tname] = single_path
        else:
            for fname in sorted(os.listdir(model_dir)):
                if fname.endswith(".safetensors"):
                    fpath = os.path.join(model_dir, fname)
                    self._load_header(fpath)
                    for tname in self.headers[fpath]:
                        if tname != "__metadata__":
                            self.index[tname] = fpath

    def _load_header(self, fpath):
        if fpath in self.headers:
            return
        with open(fpath, "rb") as fh:
            header_len = struct.unpack("<Q", fh.read(8))[0]
            header = json.loads(fh.read(header_len).decode("utf-8"))
        self.headers[fpath] = header
        self.data_offsets[fpath] = 8 + header_len

    def list_tensors(self, prefix=None):
        if prefix is None:
            return list(self.index.keys())
        return [k for k in self.index if k.startswith(prefix)]

    def tensor_info(self, name):
        fpath = self.index.get(name)
        if fpath is None:
            return None
        self._load_header(fpath)
        return self.headers[fpath].get(name)

    def find_first(self, candidates):
        for name in candidates:
            if self.tensor_info(name) is not None:
                return name
        for name in candidates:
            alt = name.replace("transformer.", "")
            if alt != name and self.tensor_info(alt) is not None:
                return alt
        return None

    def read_1d(self, name):
        if name is None or self.tensor_info(name) is None:
            return None
        for _, chunk in self.iter_row_chunks(name, chunk_rows=65536):
            return chunk.ravel()
        return None

    def _decode_raw(self, raw_bytes, dtype_str, n_rows, n_cols):
        np_dt, _ = self.DTYPE_INFO[dtype_str]
        arr = np.frombuffer(raw_bytes, dtype=np_dt).reshape(n_rows, n_cols)
        if dtype_str == "BF16":
            return (arr.astype(np.uint32) << 16).view(np.float32)
        if dtype_str == "F8_E4M3":
            return _FP8_E4M3_LUT[arr]
        if dtype_str == "F8_E5M2":
            return (arr.astype(np.uint16) << 8).view(np.float16).astype(np.float32)
        return arr.astype(np.float32)

    def iter_row_chunks(self, name, chunk_rows=512, row_range=None):
        """Yields (row_start, float32_chunk) directly from disk."""
        fpath = self.index[name]
        self._load_header(fpath)
        meta = self.headers[fpath][name]
        dtype_str = meta["dtype"]
        shape = meta["shape"]
        start_byte, _ = meta["data_offsets"]
        base_off = self.data_offsets[fpath] + start_byte

        if dtype_str not in self.DTYPE_INFO:
            raise ValueError(f"Unsupported safetensors dtype {dtype_str} for {name}")
        _, itemsize = self.DTYPE_INFO[dtype_str]

        if len(shape) == 1:
            n_rows, n_cols = 1, shape[0]
        else:
            n_rows, n_cols = shape[0], int(np.prod(shape[1:]))

        scale_inv = None
        scale_scalar = None
        if dtype_str in ("F8_E4M3", "F8_E5M2"):
            si_name = f"{name}_scale_inv"
            if self.tensor_info(si_name) is not None:
                si_meta = self.tensor_info(si_name)
                si_rows = si_meta["shape"][0] if len(si_meta["shape"]) >= 2 else 1
                si_cols = si_meta["shape"][-1] if len(si_meta["shape"]) >= 1 else 1
                chunks = [c for _, c in self.iter_row_chunks(si_name, chunk_rows=max(si_rows, 1))]
                if chunks:
                    scale_inv = np.vstack(chunks).reshape(si_rows, si_cols)
            else:
                sc_name = f"{name}_scale"
                if self.tensor_info(sc_name) is not None:
                    scale_scalar = self.read_1d(sc_name)

        r_lo, r_hi = (0, n_rows) if row_range is None else (max(0, row_range[0]), min(n_rows, row_range[1]))
        row_bytes = n_cols * itemsize
        with open(fpath, "rb") as fh:
            for r0 in range(r_lo, r_hi, chunk_rows):
                r1 = min(r_hi, r0 + chunk_rows)
                fh.seek(base_off + r0 * row_bytes)
                raw = fh.read((r1 - r0) * row_bytes)
                dec = self._decode_raw(raw, dtype_str, r1 - r0, n_cols)
                if scale_inv is not None and len(shape) == 2:
                    bh = max(1, (n_rows + scale_inv.shape[0] - 1) // scale_inv.shape[0])
                    bw = max(1, (n_cols + scale_inv.shape[1] - 1) // scale_inv.shape[1])
                    r_idx = np.arange(r0, r1, dtype=np.int64) // bh
                    c_idx = np.arange(n_cols, dtype=np.int64) // bw
                    dec = dec * scale_inv[r_idx[:, None], c_idx[None, :]]
                elif scale_scalar is not None:
                    if scale_scalar.size == 1:
                        dec = dec * np.float32(scale_scalar.ravel()[0])
                    elif scale_scalar.size == n_rows:
                        dec = dec * scale_scalar[r0:r1, None]
                yield r0 - r_lo, dec


