_IQ_GRID_CACHE = {}


def _iq_grid(name):
    """Build (1, 1, rows, k) float32 lookup grid for an IQ type (mirrors gguf-py init_grid)."""
    g = _IQ_GRID_CACHE.get(name)
    if g is None:
        hex_s, gmap, shape = _IQ_GRID_DEFS[name]
        raw = np.frombuffer(hex_s.encode("ascii"), dtype=np.uint8).reshape((-1, 2))
        raw = (np.where(raw > 0x40, raw + 9, raw) & 0x0F) << np.array([4, 0], dtype=np.uint8).reshape((1, 2))
        raw = raw[..., 0] | raw[..., 1]
        n_bits = max(1, int(math.ceil(math.log2(len(gmap)))))
        epb = 8 // n_bits
        raw = raw.reshape((-1, 1)) >> np.arange(0, 8, 8 // epb, dtype=np.uint8).reshape((1, epb))
        raw = (raw & ((1 << n_bits) - 1)).reshape((-1, 1))
        gmap_arr = np.array(gmap, dtype=np.float32).reshape((1, -1))
        g = np.take_along_axis(gmap_arr, raw, axis=-1).reshape((1, 1, *shape))
        _IQ_GRID_CACHE[name] = g
    return g


class GGUFStreamReader:
    """Pure-Python + NumPy out-of-core streamer for single or multi-shard .gguf models.
    Supports F32, F16, BF16, Q4_0, Q4_1, Q5_0, Q8_0, Q2_K..Q6_K and all IQ
    (importance) quants without external libs."""

    GGUF_TYPES = {
        0: ("<B", 1), 1: ("<b", 1), 2: ("<H", 2), 3: ("<h", 2),
        4: ("<I", 4), 5: ("<i", 4), 6: ("<f", 4), 7: ("<?", 1),
        10: ("<Q", 8), 11: ("<q", 8), 12: ("<d", 8),
    }

    # ggml_type -> (name, block_elems, block_bytes)
    GGML_QUANT = {
        0: ("F32", 1, 4),
        1: ("F16", 1, 2),
        2: ("Q4_0", 32, 18),
        3: ("Q4_1", 32, 20),
        6: ("Q5_0", 32, 22),
        7: ("Q5_1", 32, 24),
        8: ("Q8_0", 32, 34),
        10: ("Q2_K", 256, 84),
        11: ("Q3_K", 256, 110),
        12: ("Q4_K", 256, 144),
        13: ("Q5_K", 256, 176),
        14: ("Q6_K", 256, 210),
        16: ("IQ2_XXS", 256, 66),
        17: ("IQ2_XS", 256, 74),
        18: ("IQ3_XXS", 256, 98),
        19: ("IQ1_S", 256, 50),
        20: ("IQ4_NL", 32, 18),
        21: ("IQ3_S", 256, 110),
        22: ("IQ2_S", 256, 82),
        23: ("IQ4_XS", 256, 136),
        29: ("IQ1_M", 256, 56),
        30: ("BF16", 1, 2),
    }

    def __init__(self, gguf_path):
        self.files = self._discover_shards(gguf_path)
        self.meta = {}
        self.tensors = {}  # name -> {file, offset, shape:[rows, cols], ggml_type}
        for idx, fpath in enumerate(self.files):
            self._parse_file(fpath, parse_meta=(idx == 0))

    @staticmethod
    def _skip_val(fh, vtype):
        if vtype in GGUFStreamReader.GGUF_TYPES:
            fh.seek(GGUFStreamReader.GGUF_TYPES[vtype][1], os.SEEK_CUR)
        elif vtype == 8:
            n = struct.unpack("<Q", fh.read(8))[0]
            fh.seek(n, os.SEEK_CUR)
        elif vtype == 9:
            et = struct.unpack("<I", fh.read(4))[0]
            cnt = struct.unpack("<Q", fh.read(8))[0]
            if et in GGUFStreamReader.GGUF_TYPES:
                fh.seek(cnt * GGUFStreamReader.GGUF_TYPES[et][1], os.SEEK_CUR)
            elif et == 8:
                for _ in range(cnt):
                    n = struct.unpack("<Q", fh.read(8))[0]
                    fh.seek(n, os.SEEK_CUR)
            elif et == 9:
                for _ in range(cnt):
                    GGUFStreamReader._skip_val(fh, 9)
            else:
                raise ValueError(f"Unsupported GGUF metadata element type {et}")
        else:
            raise ValueError(f"Unsupported GGUF metadata type {vtype}")

    @classmethod
    def _probe_gguf_arch(cls, path):
        """Read only the GGUF metadata KV block and return general.architecture (or None)."""
        try:
            with open(path, "rb") as fh:
                if fh.read(4) != b"GGUF":
                    return None
                version = struct.unpack("<I", fh.read(4))[0]
                if version not in (2, 3):
                    return None
                fh.read(8)
                n_kv = struct.unpack("<Q", fh.read(8))[0]
                arch = None
                for _ in range(n_kv):
                    key = cls._read_str(fh)
                    vt = struct.unpack("<I", fh.read(4))[0]
                    if key == "general.architecture" and vt == 8:
                        arch = cls._read_str(fh)
                    else:
                        cls._skip_val(fh, vt)
                return arch
        except (OSError, ValueError, struct.error):
            return None

    @staticmethod
    def _is_vision_arch(arch):
        a = str(arch or "").lower()
        return "clip" in a or "mmproj" in a or "vision" in a or a in ("openai", "vit")

    @classmethod
    def _discover_shards(cls, path):
        if os.path.isdir(path):
            cands = sorted(os.path.join(path, f) for f in os.listdir(path) if f.endswith(".gguf"))
            if not cands:
                raise FileNotFoundError(f"No .gguf files found in {path}")
            groups = {}
            for c in cands:
                m = re.match(r"^(.*)-(\d{5})-of-(\d{5})\.gguf$", c)
                if m:
                    groups.setdefault((m.group(1), int(m.group(3))), []).append((int(m.group(2)), c))
            if groups:
                (prefix, total), members = max(sorted(groups.items()), key=lambda kv: len(kv[1]))
                shards = [c for _, c in sorted(members)]
                if len(shards) < total:
                    print(f"[GGUF] Note: {total - len(shards)} of {total} expected shards missing for "
                          f"{os.path.basename(prefix)}; using the {len(shards)} present")
                extra = [c for c in cands if c not in shards]
                if extra:
                    print(f"[GGUF] Note: ignoring {len(extra)} non-shard GGUF file(s) in this directory "
                          f"(e.g. {os.path.basename(extra[0])}; vision projector like mmproj-*.gguf is "
                          "not needed for text conversion)")
                return shards
            for c in cands:
                arch = cls._probe_gguf_arch(c)
                if arch is not None and cls._is_vision_arch(arch):
                    print(f"[GGUF] Skipping non-LLM GGUF: {os.path.basename(c)} (architecture '{arch}')")
                    continue
                if arch is None:
                    print(f"[GGUF] Skipping file without readable metadata: {os.path.basename(c)}")
                    continue
                return [c]
            raise FileNotFoundError(
                f"No LLM .gguf model found in {path} (only vision/mmproj or invalid GGUF files present)")
        m = re.match(r"^(.*)-(\d{5})-of-(\d{5})\.gguf$", path)
        if m:
            prefix, _, total_s = m.groups()
            total = int(total_s)
            shards = [f"{prefix}-{i:05d}-of-{total:05d}.gguf" for i in range(1, total + 1)]
            existing = [s for s in shards if os.path.exists(s)]
            if existing:
                if len(existing) < total:
                    print(f"[GGUF] Note: {total - len(existing)} of {total} expected shards missing for "
                          f"{os.path.basename(prefix)}; using the {len(existing)} present")
                return existing
        return [path]

    @staticmethod
    def _read_str(fh):
        n = struct.unpack("<Q", fh.read(8))[0]
        return fh.read(n).decode("utf-8", errors="replace")

    def _read_val(self, fh, vtype, skip_large_array=False):
        if vtype in self.GGUF_TYPES:
            fmt, sz = self.GGUF_TYPES[vtype]
            return struct.unpack(fmt, fh.read(sz))[0]
        if vtype == 8:
            return self._read_str(fh)
        if vtype == 9:
            et = struct.unpack("<I", fh.read(4))[0]
            cnt = struct.unpack("<Q", fh.read(8))[0]
            if skip_large_array and cnt > 500_000:
                if et in self.GGUF_TYPES:
                    fh.seek(cnt * self.GGUF_TYPES[et][1], os.SEEK_CUR)
                    return []
            return [self._read_val(fh, et, skip_large_array=skip_large_array) for _ in range(cnt)]
        raise ValueError(f"Unsupported GGUF metadata type {vtype}")

    def _parse_file(self, fpath, parse_meta=True):
        with open(fpath, "rb") as fh:
            magic = fh.read(4)
            if magic != b"GGUF":
                raise ValueError(f"Invalid GGUF magic in {fpath}: {magic!r}")
            version = struct.unpack("<I", fh.read(4))[0]
            if version not in (2, 3):
                raise ValueError(f"Unsupported GGUF version {version}")
            n_tensors = struct.unpack("<Q", fh.read(8))[0]
            n_kv = struct.unpack("<Q", fh.read(8))[0]

            alignment = 32
            for _ in range(n_kv):
                key = self._read_str(fh)
                vt = struct.unpack("<I", fh.read(4))[0]
                if parse_meta:
                    val = self._read_val(fh, vt)
                    self.meta[key] = val
                    if key == "general.alignment":
                        alignment = int(val)
                else:
                    val = self._read_val(fh, vt, skip_large_array=True)
                    if key == "general.alignment":
                        alignment = int(val)

            t_recs = []
            for _ in range(n_tensors):
                tname = self._read_str(fh)
                n_dims = struct.unpack("<I", fh.read(4))[0]
                dims = [struct.unpack("<Q", fh.read(8))[0] for _ in range(n_dims)]
                gtype = struct.unpack("<I", fh.read(4))[0]
                off = struct.unpack("<Q", fh.read(8))[0]
                # GGML dims[0] is innermost (cols), dims[1] is rows (or product of outer dims)
                if len(dims) == 1:
                    shape = [int(dims[0])]
                elif len(dims) == 2:
                    shape = [int(dims[1]), int(dims[0])]
                else:
                    # 3D MoE tensor: [ne2, ne1, ne0] -> outer_dims, cols
                    shape = [int(d) for d in reversed(dims)]
                t_recs.append((tname, shape, gtype, off))

            pos = fh.tell()
            data_start = ((pos + alignment - 1) // alignment) * alignment
            for tname, shape, gtype, off in t_recs:
                self.tensors[tname] = {
                    "file": fpath,
                    "offset": data_start + off,
                    "shape": shape,
                    "gtype": gtype,
                }

    def list_tensors(self, prefix=None):
        if prefix is None:
            return list(self.tensors.keys())
        return [k for k in self.tensors if k.startswith(prefix)]

    def tensor_info(self, name):
        return self.tensors.get(name)

    def find_first(self, candidates):
        for name in candidates:
            if name in self.tensors:
                return name
        for name in candidates:
            alt = name.replace("transformer.", "")
            if alt != name and alt in self.tensors:
                return alt
        return None

    def arch_config(self):
        arch = self.meta.get("general.architecture", "llama")
        def _get(suffix, default=None):
            return self.meta.get(f"{arch}.{suffix}", default)
        def _first_valid(val, default):
            """Per-layer GGUF lists (e.g. hybrid attention) -> first nonzero entry."""
            if isinstance(val, (list, tuple)):
                for v in val:
                    if int(v) > 0:
                        return int(v)
                return 0
            return int(val) if val is not None else default
        n_heads = _first_valid(_get("attention.head_count", 12), 12)
        d_model = int(_get("embedding_length", 768))
        n_kv = _first_valid(_get("attention.head_count_kv", n_heads), n_heads)
        head_dim = _get("attention.key_length")
        rope_dim = _get("rope.dimension_count")
        r_type = _get("rope.scaling.type")
        r_fac = _get("rope.scaling.factor")
        r_orig = _get("rope.scaling.original_context_length")
        r_attn = _get("rope.scaling.attn_factor")
        rope_scaling = None
        if r_type:
            rope_scaling = {
                "rope_type": str(r_type),
                "factor": float(r_fac) if r_fac is not None else 1.0,
                "original_max_position_embeddings": int(r_orig) if r_orig is not None else 8192,
            }
            if r_attn is not None:
                rope_scaling["attention_factor"] = float(r_attn)
        arch_l = str(arch).lower()
        default_act = "silu"
        if arch_l in ("gemma", "gemma2", "gemma3", "gemma3_text"):
            default_act = "gelu_pytorch_tanh"
        elif arch_l in ("gpt2", "bloom"):
            default_act = "gelu_new"
        cfg = {
            "arch": arch,
            "model_type": arch,
            "num_hidden_layers": int(_get("block_count", 12)),
            "hidden_size": d_model,
            "intermediate_size": int(_get("feed_forward_length", 2048)),
            "num_attention_heads": n_heads,
            "num_key_value_heads": n_kv,
            "num_local_experts": int(_get("expert_count", 0) or 0),
            "num_experts_per_tok": int(_get("expert_used_count", 2) or 2),
            "rms_norm_eps": float(_get("attention.layer_norm_rms_epsilon", 1e-5)),
            "layer_norm_epsilon": float(_get("attention.layer_norm_epsilon", 1e-5)),
            "rope_theta": float(_get("rope.freq_base", 10000.0)),
            "hidden_act": default_act,
            "is_gguf": True,
        }
        if head_dim is not None:
            cfg["head_dim"] = int(head_dim)
        if rope_dim is not None:
            cfg["rotary_dim"] = int(rope_dim)
        if rope_scaling is not None:
            cfg["rope_scaling"] = rope_scaling
        if _get("final_logit_softcapping") is not None:
            cfg["final_logit_softcapping"] = float(_get("final_logit_softcapping"))
        if _get("attn_logit_softcapping") is not None:
            cfg["attn_logit_softcapping"] = float(_get("attn_logit_softcapping"))
        if _get("attention.sliding_window") is not None:
            cfg["sliding_window"] = int(_get("attention.sliding_window"))
        if _get("expert_weights_scale") is not None:
            cfg["routed_scaling_factor"] = float(_get("expert_weights_scale"))
        if _get("expert_weights_norm") is not None:
            cfg["norm_topk_prob"] = bool(_get("expert_weights_norm"))
        if _get("expert_gating_func") is not None:
            gf = int(_get("expert_gating_func"))
            cfg["scoring_func"] = "sigmoid" if gf == 2 else "softmax"
        return cfg

    def tokenizer_data(self):
        tokens = self.meta.get("tokenizer.ggml.tokens")
        if not tokens:
            return None
        vocab = {tok: i for i, tok in enumerate(tokens)}
        merges = self.meta.get("tokenizer.ggml.merges") or []
        tmodel = self.meta.get("tokenizer.ggml.model", "llama")
        bos_id = self.meta.get("tokenizer.ggml.bos_token_id")
        eos_raw = self.meta.get("tokenizer.ggml.eos_token_id")
        eot_id = self.meta.get("tokenizer.ggml.eot_token_id")
        eog_id = self.meta.get("tokenizer.ggml.eog_token_id")
        eos_list = []
        for eid in (eos_raw, eot_id, eog_id):
            if eid is not None and int(eid) not in eos_list:
                eos_list.append(int(eid))
        eos_id = eos_list if len(eos_list) > 1 else (eos_list[0] if eos_list else None)

        scores = self.meta.get("tokenizer.ggml.scores")
        ttype = self.meta.get("tokenizer.ggml.token_type")
        special_set = set()
        if ttype and len(ttype) == len(tokens):
            for tok, tp in zip(tokens, ttype):
                if tp in (3, 4) and tok:
                    special_set.add(tok)
        for sid in ([bos_id] + eos_list):
            if sid is not None and 0 <= int(sid) < len(tokens) and tokens[int(sid)]:
                special_set.add(tokens[int(sid)])
        add_bos = self.meta.get("tokenizer.ggml.add_bos_token")
        if add_bos is None:
            add_bos = (bos_id is not None) and (tmodel != "gpt2")
        return {
            "vocab": vocab,
            "merges": merges,
            "scores": list(scores) if scores is not None else None,
            "special_tokens": sorted(special_set),
            "byte_level": (tmodel == "gpt2"),
            "pre_type": self.meta.get("tokenizer.ggml.pre") or tmodel,
            "add_bos": bool(add_bos),
            "add_dummy_prefix": bool(self.meta.get("tokenizer.ggml.add_space_prefix", tmodel == "llama")),
            "bos_id": int(bos_id) if bos_id is not None else None,
            "eos_id": eos_id,
        }

    def read_1d(self, name):
        if name is None or name not in self.tensors:
            return None
        for _, chunk in self.iter_row_chunks(name, chunk_rows=65536):
            return chunk.ravel()
        return None

    @classmethod
    def _dequant_rows(cls, raw_bytes, gtype, n_rows, n_cols):
        qname, qk, bsz = cls.GGML_QUANT[gtype]
        if qname == "F32":
            return np.frombuffer(raw_bytes, dtype=np.float32).reshape(n_rows, n_cols).copy()
        if qname == "F16":
            return np.frombuffer(raw_bytes, dtype=np.float16).reshape(n_rows, n_cols).astype(np.float32)
        if qname == "BF16":
            u16 = np.frombuffer(raw_bytes, dtype=np.uint16).reshape(n_rows, n_cols)
            return (u16.astype(np.uint32) << 16).view(np.float32)
        n_blk = n_cols // qk
        arr = np.frombuffer(raw_bytes, dtype=np.uint8).reshape(n_rows, n_blk, bsz)
        if qname == "Q8_0":
            d = arr[:, :, :2].copy().view(np.float16).astype(np.float32)
            qs = arr[:, :, 2:].view(np.int8).astype(np.float32)
            return (d * qs).reshape(n_rows, n_cols)
        if qname == "Q4_0":
            d = arr[:, :, :2].copy().view(np.float16).astype(np.float32)
            qs = arr[:, :, 2:]
            out = np.empty((n_rows, n_blk, 32), dtype=np.float32)
            out[:, :, :16] = ((qs & 0x0F).astype(np.float32) - 8.0) * d
            out[:, :, 16:] = ((qs >> 4).astype(np.float32) - 8.0) * d
            return out.reshape(n_rows, n_cols)
        if qname == "Q4_1":
            d = arr[:, :, :2].copy().view(np.float16).astype(np.float32)
            m = arr[:, :, 2:4].copy().view(np.float16).astype(np.float32)
            qs = arr[:, :, 4:]
            out = np.empty((n_rows, n_blk, 32), dtype=np.float32)
            out[:, :, :16] = (qs & 0x0F).astype(np.float32) * d + m
            out[:, :, 16:] = (qs >> 4).astype(np.float32) * d + m
            return out.reshape(n_rows, n_cols)
        if qname == "Q5_0":
            d = arr[:, :, :2].copy().view(np.float16).astype(np.float32)
            qh = np.frombuffer(arr[:, :, 2:6].tobytes(), dtype=np.uint32).reshape(n_rows, n_blk, 1)
            qs = arr[:, :, 6:]
            bits = np.arange(16, dtype=np.uint32)[None, None, :]
            h0 = ((qh >> bits) & 1).astype(np.float32) * 16.0
            h1 = ((qh >> (bits + 16)) & 1).astype(np.float32) * 16.0
            out = np.empty((n_rows, n_blk, 32), dtype=np.float32)
            out[:, :, :16] = (((qs & 0x0F).astype(np.float32) + h0) - 16.0) * d
            out[:, :, 16:] = (((qs >> 4).astype(np.float32) + h1) - 16.0) * d
            return out.reshape(n_rows, n_cols)
        if qname == "Q5_1":
            d = arr[:, :, :2].copy().view(np.float16).astype(np.float32)
            m = arr[:, :, 2:4].copy().view(np.float16).astype(np.float32)
            qh = np.frombuffer(arr[:, :, 4:8].tobytes(), dtype=np.uint32).reshape(n_rows, n_blk, 1)
            qs = arr[:, :, 8:]
            bits = np.arange(16, dtype=np.uint32)[None, None, :]
            h0 = ((qh >> bits) & 1).astype(np.float32) * 16.0
            h1 = ((qh >> (bits + 16)) & 1).astype(np.float32) * 16.0
            out = np.empty((n_rows, n_blk, 32), dtype=np.float32)
            out[:, :, :16] = ((qs & 0x0F).astype(np.float32) + h0) * d + m
            out[:, :, 16:] = ((qs >> 4).astype(np.float32) + h1) * d + m
            return out.reshape(n_rows, n_cols)
        if qname == "Q2_K":
            scales = arr[:, :, 0:16]
            qs = arr[:, :, 16:80].reshape(n_rows, n_blk, 2, 2, 16)
            d = arr[:, :, 80:82].copy().view(np.float16).astype(np.float32)
            dmin = arr[:, :, 82:84].copy().view(np.float16).astype(np.float32)
            dl = (d * (scales & 0x0F).astype(np.float32)).reshape(n_rows, n_blk, 2, 4, 2, 1)
            ml = (dmin * (scales >> 4).astype(np.float32)).reshape(n_rows, n_blk, 2, 4, 2, 1)
            shifts = np.array([0, 2, 4, 6], dtype=np.uint8)[None, None, None, :, None, None]
            q_vals = ((qs[:, :, :, None, :, :] >> shifts) & 3).astype(np.float32)
            return (q_vals * dl - ml).reshape(n_rows, n_cols)
        if qname == "Q3_K":
            hmask = arr[:, :, 0:32].reshape(n_rows, n_blk, 2, 16)
            qs = arr[:, :, 32:96].reshape(n_rows, n_blk, 2, 2, 16)
            aux = arr[:, :, 96:108].copy().view(np.uint32)
            tmp = aux[:, :, 2]
            km1, km2 = np.uint32(0x03030303), np.uint32(0x0F0F0F0F)
            sc_u32 = np.empty((n_rows, n_blk, 4), dtype=np.uint32)
            sc_u32[:, :, 0] = (aux[:, :, 0] & km2) | (((tmp >> 0) & km1) << 4)
            sc_u32[:, :, 1] = (aux[:, :, 1] & km2) | (((tmp >> 2) & km1) << 4)
            sc_u32[:, :, 2] = ((aux[:, :, 0] >> 4) & km2) | (((tmp >> 4) & km1) << 4)
            sc_u32[:, :, 3] = ((aux[:, :, 1] >> 4) & km2) | (((tmp >> 6) & km1) << 4)
            sc = sc_u32.view(np.uint8).astype(np.float32) - 32.0
            d_all = arr[:, :, 108:110].copy().view(np.float16).astype(np.float32)
            dl = (d_all * sc).reshape(n_rows, n_blk, 2, 4, 2, 1)
            shifts = np.array([0, 2, 4, 6], dtype=np.uint8)[None, None, None, :, None, None]
            q_vals = ((qs[:, :, :, None, :, :] >> shifts) & 3).astype(np.float32)
            m_bits = np.array([1, 2, 4, 8, 16, 32, 64, 128], dtype=np.uint8).reshape(1, 1, 2, 4, 1, 1)
            h_sub = np.where((hmask[:, :, None, None, :, :] & m_bits) == 0, np.float32(4.0), np.float32(0.0))
            return (dl * (q_vals - h_sub)).reshape(n_rows, n_cols)
        if qname == "Q4_K":
            d = arr[:, :, 0:2].copy().view(np.float16).astype(np.float32)
            dmin = arr[:, :, 2:4].copy().view(np.float16).astype(np.float32)
            sc_raw = arr[:, :, 4:16]
            qs = arr[:, :, 16:144]
            sc = np.empty((n_rows, n_blk, 8), dtype=np.float32)
            mn = np.empty((n_rows, n_blk, 8), dtype=np.float32)
            sc[:, :, 0:4] = (sc_raw[:, :, 0:4] & 63).astype(np.float32)
            mn[:, :, 0:4] = (sc_raw[:, :, 4:8] & 63).astype(np.float32)
            sc[:, :, 4:8] = ((sc_raw[:, :, 8:12] & 0x0F) | ((sc_raw[:, :, 0:4] >> 6) << 4)).astype(np.float32)
            mn[:, :, 4:8] = ((sc_raw[:, :, 8:12] >> 4) | ((sc_raw[:, :, 4:8] >> 6) << 4)).astype(np.float32)
            d_sc = d * sc
            dm_mn = dmin * mn
            qs_c = qs.reshape(n_rows, n_blk, 4, 32)
            out = np.empty((n_rows, n_blk, 8, 32), dtype=np.float32)
            out[:, :, 0::2, :] = (qs_c & 0x0F).astype(np.float32) * d_sc[:, :, 0::2, None] - dm_mn[:, :, 0::2, None]
            out[:, :, 1::2, :] = (qs_c >> 4).astype(np.float32) * d_sc[:, :, 1::2, None] - dm_mn[:, :, 1::2, None]
            return out.reshape(n_rows, n_cols)
        if qname == "Q5_K":
            d = arr[:, :, 0:2].copy().view(np.float16).astype(np.float32)
            dmin = arr[:, :, 2:4].copy().view(np.float16).astype(np.float32)
            sc_raw = arr[:, :, 4:16]
            qh = arr[:, :, 16:48]
            qs = arr[:, :, 48:176]
            sc = np.empty((n_rows, n_blk, 8), dtype=np.float32)
            mn = np.empty((n_rows, n_blk, 8), dtype=np.float32)
            sc[:, :, 0:4] = (sc_raw[:, :, 0:4] & 63).astype(np.float32)
            mn[:, :, 0:4] = (sc_raw[:, :, 4:8] & 63).astype(np.float32)
            sc[:, :, 4:8] = ((sc_raw[:, :, 8:12] & 0x0F) | ((sc_raw[:, :, 0:4] >> 6) << 4)).astype(np.float32)
            mn[:, :, 4:8] = ((sc_raw[:, :, 8:12] >> 4) | ((sc_raw[:, :, 4:8] >> 6) << 4)).astype(np.float32)
            d_sc = d * sc
            dm_mn = dmin * mn
            qs_c = qs.reshape(n_rows, n_blk, 4, 32)
            shifts = np.arange(0, 8, 2, dtype=np.uint8)[None, None, :, None]
            h0 = ((qh[:, :, None, :] >> shifts) & 1).astype(np.float32) * 16.0
            h1 = ((qh[:, :, None, :] >> (shifts + 1)) & 1).astype(np.float32) * 16.0
            out = np.empty((n_rows, n_blk, 8, 32), dtype=np.float32)
            out[:, :, 0::2, :] = ((qs_c & 0x0F).astype(np.float32) + h0) * d_sc[:, :, 0::2, None] - dm_mn[:, :, 0::2, None]
            out[:, :, 1::2, :] = ((qs_c >> 4).astype(np.float32) + h1) * d_sc[:, :, 1::2, None] - dm_mn[:, :, 1::2, None]
            return out.reshape(n_rows, n_cols)
        if qname == "Q6_K":
            ql = arr[:, :, 0:128].reshape(n_rows, n_blk, 2, 64)
            qh = arr[:, :, 128:192].reshape(n_rows, n_blk, 2, 32)
            sc = arr[:, :, 192:208].view(np.int8).astype(np.float32).reshape(n_rows, n_blk, 2, 8)
            d = arr[:, :, 208:210].copy().view(np.float16).astype(np.float32)[:, :, None]
            ql_lo, ql_hi = ql[:, :, :, 0:32], ql[:, :, :, 32:64]
            qs_parts = (
                ((ql_lo & 0x0F) | (((qh >> 0) & 3) << 4)).astype(np.float32) - 32.0,
                ((ql_hi & 0x0F) | (((qh >> 2) & 3) << 4)).astype(np.float32) - 32.0,
                ((ql_lo >> 4)   | (((qh >> 4) & 3) << 4)).astype(np.float32) - 32.0,
                ((ql_hi >> 4)   | (((qh >> 6) & 3) << 4)).astype(np.float32) - 32.0,
            )
            out = np.empty((n_rows, n_blk, 2, 128), dtype=np.float32)
            for k_idx, qk_part in enumerate(qs_parts):
                s_pair = np.repeat(sc[:, :, :, 2 * k_idx : 2 * k_idx + 2], 16, axis=3)
                out[:, :, :, k_idx * 32 : (k_idx + 1) * 32] = d * s_pair * qk_part
            return out.reshape(n_rows, n_cols)
        if qname.startswith("IQ"):
            N = n_rows * n_blk
            return cls._dequant_iq(np.ascontiguousarray(arr).reshape(N, bsz), qname).reshape(n_rows, n_cols)
        raise ValueError(f"Unhandled GGML quant {qname}")

    _IQ_KSIGNS = None

    @classmethod
    def _iq_ksigns(cls):
        if cls._IQ_KSIGNS is None:
            cls._IQ_KSIGNS = np.frombuffer(bytes.fromhex(_IQ2XXS_KSIGNS_HEX), dtype=np.uint8)
        return cls._IQ_KSIGNS

    _IQ_KVALUES = None

    @classmethod
    def _iq_kvalues(cls):
        if cls._IQ_KVALUES is None:
            cls._IQ_KVALUES = np.array(_IQ4NL_KVALUES, dtype=np.int8).reshape(1, 1, 16)
        return cls._IQ_KVALUES

    @classmethod
    def _dequant_iq(cls, blocks, qname):
        """Vectorized IQ (importance-grid) dequantization, faithful to gguf-py.
        `blocks` has shape (n_blocks, block_bytes); returns (n_blocks, 256) or (n_blocks, 32)."""
        fn = getattr(cls, f"_dq_{qname.lower()}", None)
        if fn is None:
            raise ValueError(f"Unhandled GGML quant {qname}")
        return fn(blocks)

    @staticmethod
    def _dq_iq2_xxs(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:].view(np.uint32).reshape(N, -1, 2)
        db = d * (np.float32(0.5) + (qs[..., 1] >> 28).astype(np.float32)) * np.float32(0.25)
        db = db.reshape(N, -1, 1, 1)
        signs = qs[..., 1].reshape(N, -1, 1) >> np.array([0, 7, 14, 21], dtype=np.uint32).reshape(1, 1, 4)
        signs = (signs & np.uint32(0x7F)).reshape(N, -1, 4, 1)
        signs = np.take_along_axis(GGUFStreamReader._iq_ksigns().reshape(1, 1, 1, 128), signs, axis=-1)
        signs = signs.reshape(N, -1, 4, 1) >> np.arange(8, dtype=np.uint8).reshape(1, 1, 1, 8)
        signs = np.where((signs & np.uint8(0x01)) == 0, np.float32(1), np.float32(-1)).reshape(N, -1, 4, 8)
        grid = np.take_along_axis(_iq_grid("IQ2_XXS"), qs[..., 0].copy().view(np.uint8).reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 4, 8)
        return (db * grid * signs).reshape(N, 256)

    @staticmethod
    def _dq_iq2_xs(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:66].view(np.uint16)
        scales = blocks[:, 66:].reshape(N, -1, 1) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2)
        scales = (scales & np.uint8(0x0F)).reshape(N, -1)
        db = (d * (np.float32(0.5) + scales) * np.float32(0.25)).reshape(N, -1, 1, 1)
        signs = np.take_along_axis(GGUFStreamReader._iq_ksigns().reshape(1, 1, 128), (qs >> 9).reshape(N, -1, 1), axis=-1)
        signs = signs.reshape(N, -1, 1) >> np.arange(8, dtype=np.uint8).reshape(1, 1, 8)
        signs = np.where((signs & np.uint8(0x01)) == 0, np.float32(1), np.float32(-1)).reshape(N, -1, 2, 8)
        grid = np.take_along_axis(_iq_grid("IQ2_XS"), (qs & np.uint16(511)).reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 2, 8)
        return (db * grid * signs).reshape(N, 256)

    @staticmethod
    def _dq_iq2_s(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:34]
        signs_raw = blocks[:, 34:66]
        qh = blocks[:, 66:74]
        scales = blocks[:, 74:].reshape(N, -1, 1) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2)
        scales = (scales & np.uint8(0x0F)).reshape(N, -1)
        db = (d * (np.float32(0.5) + scales) * np.float32(0.25)).reshape(N, -1, 1, 1)
        signs = signs_raw.reshape(N, -1, 1) >> np.arange(8, dtype=np.uint8).reshape(1, 1, 8)
        signs = np.where((signs & np.uint8(0x01)) == 0, np.float32(1), np.float32(-1)).reshape(N, -1, 2, 8)
        qh = qh.reshape(N, -1, 1) >> np.array([0, 2, 4, 6], dtype=np.uint8).reshape(1, 1, 4)
        qs = qs.astype(np.uint16) | ((qh & np.uint8(0x03)).astype(np.uint16) << 8).reshape(N, -1)
        grid = np.take_along_axis(_iq_grid("IQ2_S"), qs.reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 2, 8)
        return (db * grid * signs).reshape(N, 256)

    @staticmethod
    def _dq_iq3_xxs(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:66]
        scales = blocks[:, 66:].copy().view(np.uint32)
        db = d * (np.float32(0.5) + (scales >> 28).astype(np.float32)) * np.float32(0.5)
        db = db.reshape(N, -1, 1, 1)
        signs = scales.reshape(N, -1, 1) >> np.array([0, 7, 14, 21], dtype=np.uint32).reshape(1, 1, 4)
        signs = (signs & np.uint32(0x7F)).reshape(N, -1, 4, 1)
        signs = np.take_along_axis(GGUFStreamReader._iq_ksigns().reshape(1, 1, 1, 128), signs, axis=-1)
        signs = signs.reshape(N, -1, 4, 1) >> np.arange(8, dtype=np.uint8).reshape(1, 1, 1, 8)
        signs = np.where((signs & np.uint8(0x01)) == 0, np.float32(1), np.float32(-1)).reshape(N, -1, 4, 8)
        grid = np.take_along_axis(_iq_grid("IQ3_XXS"), qs.reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 4, 8)
        return (db * grid * signs).reshape(N, 256)

    @staticmethod
    def _dq_iq3_s(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:66]
        qh = blocks[:, 66:74]
        signs_raw = blocks[:, 74:106]
        scales = blocks[:, 106:]
        scales = scales.reshape(N, -1, 1) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2)
        scales = (scales & np.uint8(0x0F)).reshape(N, -1)
        db = (d * (1 + 2 * scales)).reshape(N, -1, 1, 1)
        signs = signs_raw.reshape(N, -1, 1) >> np.arange(8, dtype=np.uint8).reshape(1, 1, 8)
        signs = np.where((signs & np.uint8(0x01)) == 0, np.float32(1), np.float32(-1)).reshape(N, -1, 4, 8)
        qh = qh.reshape(N, -1, 1) >> np.arange(8, dtype=np.uint8)
        qh = (qh & np.uint8(0x01)).astype(np.uint16).reshape(N, -1)
        qs = qs.astype(np.uint16) | (qh << 8)
        grid = np.take_along_axis(_iq_grid("IQ3_S"), qs.reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 4, 8)
        return (db * grid * signs).reshape(N, 256)

    _IQ1_DELTA = np.float32(0.125)

    @staticmethod
    def _dq_iq1_s(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:34]
        qh = blocks[:, 34:].copy().view(np.uint16)
        dl = (d * (2 * ((qh >> 12) & np.uint16(7)) + 1)).reshape(N, -1, 1, 1)
        delta = np.where((qh & np.uint16(0x8000)) == 0, GGUFStreamReader._IQ1_DELTA, -GGUFStreamReader._IQ1_DELTA)
        delta = delta.reshape(N, -1, 1, 1)
        qh = qh.reshape(N, -1, 1) >> np.array([0, 3, 6, 9], dtype=np.uint16).reshape(1, 1, 4)
        qs = qs.astype(np.uint16) | ((qh & np.uint16(7)) << 8).reshape(N, -1)
        grid = np.take_along_axis(_iq_grid("IQ1_S"), qs.reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 4, 8)
        return (dl * (grid + delta)).reshape(N, 256)

    @staticmethod
    def _dq_iq1_m(blocks):
        N = blocks.shape[0]
        qs = blocks[:, :32]
        qh = blocks[:, 32:48]
        scales = blocks[:, 48:].copy().view(np.uint16)
        d = (scales.reshape(N, 4) & np.uint16(0xF000)) >> np.array([12, 8, 4, 0], dtype=np.uint16).reshape(1, 4)
        d = (d[:, 0] | d[:, 1] | d[:, 2] | d[:, 3]).view(np.float16).astype(np.float32).reshape(N, 1)
        scales = scales.reshape(N, -1, 1) >> np.array([0, 3, 6, 9], dtype=np.uint16).reshape(1, 1, 4)
        scales = (scales & np.uint16(0x07)).reshape(N, -1)
        dl = (d * (2 * scales + 1)).reshape(N, -1, 2, 1, 1)
        qh = qh.reshape(N, -1, 1) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2)
        qs = qs.astype(np.uint16) | ((qh & np.uint8(0x07)).astype(np.uint16) << 8).reshape(N, -1)
        delta = np.where((qh & np.uint8(0x08)) == 0, GGUFStreamReader._IQ1_DELTA, -GGUFStreamReader._IQ1_DELTA)
        delta = delta.reshape(N, -1, 2, 2, 1)
        grid = np.take_along_axis(_iq_grid("IQ1_S"), qs.reshape(N, -1, 1, 1), axis=-2)
        grid = grid.reshape(N, -1, 2, 2, 8)
        return (dl * (grid + delta)).reshape(N, 256)

    @staticmethod
    def _dq_iq4_nl(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        qs = blocks[:, 2:].reshape(N, -1, 1, 16) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2, 1)
        qs = (qs & np.uint8(0x0F)).reshape(N, -1, 1)
        qs = np.take_along_axis(GGUFStreamReader._iq_kvalues(), qs, axis=-1).astype(np.float32).reshape(N, -1)
        return d * qs

    @staticmethod
    def _dq_iq4_xs(blocks):
        N = blocks.shape[0]
        d = blocks[:, :2].copy().view(np.float16).astype(np.float32)
        scales_h = blocks[:, 2:4].copy().view(np.uint16)
        scales_l = blocks[:, 4:8]
        qs = blocks[:, 8:]
        scales_l = scales_l.reshape(N, -1, 1) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2)
        scales_h = scales_h.reshape(N, 1, -1) >> np.array([2 * i for i in range(8)], dtype=np.uint16).reshape(1, -1, 1)
        scales_l = scales_l.reshape(N, -1) & np.uint8(0x0F)
        scales_h = scales_h.reshape(N, -1).astype(np.uint8) & np.uint8(0x03)
        scales = (scales_l | (scales_h << np.uint8(4))).astype(np.int8) - np.int8(32)
        dl = (d * scales.astype(np.float32)).reshape(N, -1, 1)
        qs = qs.reshape(N, -1, 1, 16) >> np.array([0, 4], dtype=np.uint8).reshape(1, 1, 2, 1)
        qs = qs.reshape(N, -1, 32, 1) & np.uint8(0x0F)
        qs = np.take_along_axis(GGUFStreamReader._iq_kvalues().reshape(1, 1, 1, 16), qs, axis=-1).astype(np.float32).reshape(N, -1, 32)
        return (dl * qs).reshape(N, 256)

    def iter_row_chunks(self, name, chunk_rows=512, row_range=None):
        info = self.tensors[name]
        gtype = info["gtype"]
        if gtype not in self.GGML_QUANT:
            raise ValueError(f"Unsupported GGML tensor type {gtype} for {name}")
        _, qk, bsz = self.GGML_QUANT[gtype]
        shape = info["shape"]
        if len(shape) == 1:
            n_rows, n_cols = 1, shape[0]
        else:
            n_cols = shape[-1]
            n_rows = int(np.prod(shape[:-1]))
        if n_cols % qk != 0:
            raise ValueError(f"GGUF tensor {name} cols={n_cols} not divisible by block size {qk}")
        row_bytes = (n_cols // qk) * bsz
        r_lo, r_hi = (0, n_rows) if row_range is None else (max(0, row_range[0]), min(n_rows, row_range[1]))
        with open(info["file"], "rb") as fh:
            for r0 in range(r_lo, r_hi, chunk_rows):
                r1 = min(r_hi, r0 + chunk_rows)
                fh.seek(info["offset"] + r0 * row_bytes)
                raw = fh.read((r1 - r0) * row_bytes)
                yield r0 - r_lo, self._dequant_rows(raw, gtype, r1 - r0, n_cols)


# =====================================================================
# 2. Disk-Backed / RAM Sparse Connectome Storage (CSR + Memmap)
# =====================================================================
class ConnectomeStorage:
    """Stores outgoing sparse synapses in CSR format.
    Supports both in-memory arrays and disk-backed np.memmap."""

    def __init__(self, n_neurons, storage_dir=None, memmap_threshold_edges=15_000_000):
        self.N = int(n_neurons)
        self.storage_dir = storage_dir
        self.memmap_threshold = int(memmap_threshold_edges)
        self.use_memmap = storage_dir is not None

        self.indptr = np.zeros(self.N + 1, dtype=np.int64)
        self.nnz = 0
        self._finalized = False

        if self.use_memmap:
            os.makedirs(storage_dir, exist_ok=True)
            self._idx_path = os.path.join(storage_dir, "indices.u32")
            self._wt_path = os.path.join(storage_dir, "weights.i8")
            self._del_path = os.path.join(storage_dir, "delays.u8")
            self._cmp_path = os.path.join(storage_dir, "compartments.u8")
            self._f_idx = open(self._idx_path, "wb")
            self._f_wt = open(self._wt_path, "wb")
            self._f_del = open(self._del_path, "wb")
            self._f_cmp = open(self._cmp_path, "wb")
            self.indices = None
            self.weights_q8 = None
            self.delays = None
            self.compartments = None
        else:
            self._buf_idx = []
            self._buf_wt = []
            self._buf_del = []
            self._buf_cmp = []
            self.indices = np.empty(0, dtype=np.uint32)
            self.weights_q8 = np.empty(0, dtype=np.int8)
            self.delays = np.empty(0, dtype=np.uint8)
            self.compartments = np.empty(0, dtype=np.uint8)

        self._cursor = 0

    def append_neuron_block(self, src_start, src_count, src_local, dst, w_q8, delays, compartments):
        if src_start != self._cursor:
            raise ValueError(f"Sequential CSR append expected src_start={self._cursor}, got {src_start}")

        if len(src_local) > 0:
            order = np.argsort(src_local, kind="mergesort")
            s_ord = src_local[order]
            d_ord = dst[order].astype(np.uint32)
            w_ord = w_q8[order].astype(np.int8)
            dl_ord = delays[order].astype(np.uint8)
            cm_ord = compartments[order].astype(np.uint8)
            counts = np.bincount(s_ord, minlength=src_count)
        else:
            d_ord = np.empty(0, dtype=np.uint32)
            w_ord = np.empty(0, dtype=np.int8)
            dl_ord = np.empty(0, dtype=np.uint8)
            cm_ord = np.empty(0, dtype=np.uint8)
            counts = np.zeros(src_count, dtype=np.int64)

        self.indptr[src_start + 1 : src_start + src_count + 1] = self.nnz + np.cumsum(counts)
        self.nnz += len(d_ord)
        self._cursor += src_count

        if len(d_ord) > 0:
            if self.use_memmap:
                self._f_idx.write(d_ord.tobytes())
                self._f_wt.write(w_ord.tobytes())
                self._f_del.write(dl_ord.tobytes())
                self._f_cmp.write(cm_ord.tobytes())
            else:
                self._buf_idx.append(d_ord)
                self._buf_wt.append(w_ord)
                self._buf_del.append(dl_ord)
                self._buf_cmp.append(cm_ord)

    def finalize(self, writable=True):
        if self._finalized:
            return
        if self._cursor < self.N:
            self.indptr[self._cursor + 1 :] = self.nnz
            self._cursor = self.N

        if self.use_memmap:
            for fh in (self._f_idx, self._f_wt, self._f_del, self._f_cmp):
                if fh is not None and not fh.closed:
                    fh.close()
            if self.nnz > 0:
                mode = "r+" if writable else "r"
                self.indices = np.memmap(self._idx_path, dtype=np.uint32, mode=mode, shape=(self.nnz,))
                self.weights_q8 = np.memmap(self._wt_path, dtype=np.int8, mode=mode, shape=(self.nnz,))
                self.delays = np.memmap(self._del_path, dtype=np.uint8, mode=mode, shape=(self.nnz,))
                self.compartments = np.memmap(self._cmp_path, dtype=np.uint8, mode=mode, shape=(self.nnz,))
            else:
                self.indices = np.empty(0, dtype=np.uint32)
                self.weights_q8 = np.empty(0, dtype=np.int8)
                self.delays = np.empty(0, dtype=np.uint8)
                self.compartments = np.empty(0, dtype=np.uint8)
        else:
            if self.nnz > 0:
                self.indices = np.concatenate(self._buf_idx)
                self.weights_q8 = np.concatenate(self._buf_wt)
                self.delays = np.concatenate(self._buf_del)
                self.compartments = np.concatenate(self._buf_cmp)
            self._buf_idx.clear()
            self._buf_wt.clear()
            self._buf_del.clear()
            self._buf_cmp.clear()
        self._finalized = True

    def save_to_dir(self, out_dir):
        os.makedirs(out_dir, exist_ok=True)
        np.save(os.path.join(out_dir, "indptr.npy"), self.indptr)
        idx_p = os.path.join(out_dir, "indices.u32")
        wt_p = os.path.join(out_dir, "weights.i8")
        del_p = os.path.join(out_dir, "delays.u8")
        cmp_p = os.path.join(out_dir, "compartments.u8")

        if self.use_memmap and self.storage_dir and os.path.abspath(self.storage_dir) == os.path.abspath(out_dir):
            self.flush()
            return

        if self.nnz > 0:
            for arr, p in ((self.indices, idx_p), (self.weights_q8, wt_p),
                           (self.delays, del_p), (self.compartments, cmp_p)):
                with open(p, "wb") as fh:
                    for i0 in range(0, self.nnz, 4_000_000):
                        fh.write(np.asarray(arr[i0 : i0 + 4_000_000]).tobytes())

    @classmethod
    def load_from_dir(cls, storage_dir, writable=True):
        indptr = np.load(os.path.join(storage_dir, "indptr.npy"))
        N = len(indptr) - 1
        nnz = int(indptr[-1])
        obj = cls.__new__(cls)
        obj.N = N
        obj.storage_dir = storage_dir
        obj.memmap_threshold = 15_000_000
        obj.use_memmap = True
        obj.indptr = indptr
        obj.nnz = nnz
        obj._cursor = N
        obj._finalized = True
        obj._idx_path = os.path.join(storage_dir, "indices.u32")
        obj._wt_path = os.path.join(storage_dir, "weights.i8")
        obj._del_path = os.path.join(storage_dir, "delays.u8")
        obj._cmp_path = os.path.join(storage_dir, "compartments.u8")
        obj._f_idx = obj._f_wt = obj._f_del = obj._f_cmp = None
        if nnz > 0:
            mode = "r+" if writable else "r"
            obj.indices = np.memmap(obj._idx_path, dtype=np.uint32, mode=mode, shape=(nnz,))
            obj.weights_q8 = np.memmap(obj._wt_path, dtype=np.int8, mode=mode, shape=(nnz,))
            obj.delays = np.memmap(obj._del_path, dtype=np.uint8, mode=mode, shape=(nnz,))
            obj.compartments = np.memmap(obj._cmp_path, dtype=np.uint8, mode=mode, shape=(nnz,))
        else:
            obj.indices = np.empty(0, dtype=np.uint32)
            obj.weights_q8 = np.empty(0, dtype=np.int8)
            obj.delays = np.empty(0, dtype=np.uint8)
            obj.compartments = np.empty(0, dtype=np.uint8)
        return obj

    def flush(self):
        if self.use_memmap and self.nnz > 0:
            for arr in (self.indices, self.weights_q8, self.delays, self.compartments):
                if isinstance(arr, np.memmap):
                    arr.flush()

    def close(self):
        self.flush()
        if self.use_memmap:
            for name in ("indices", "weights_q8", "delays", "compartments"):
                arr = getattr(self, name, None)
                if isinstance(arr, np.memmap) and getattr(arr, "_mmap", None) is not None:
                    arr._mmap.close()
                setattr(self, name, None)

    def ram_bytes(self):
        base = self.indptr.nbytes
        if not self.use_memmap and self.indices is not None:
            base += self.indices.nbytes + self.weights_q8.nbytes + self.delays.nbytes + self.compartments.nbytes
        return int(base)

    def disk_bytes(self):
        return int(self.nnz * (4 + 1 + 1 + 1) + self.indptr.nbytes)


# =====================================================================
# 3. Biologically-Inspired Nervous System (`BiologicalBrain`)
# =====================================================================
class BiologicalBrain:
    """Zero-allocation spiking/oscillatory cortical brain tuned for 2014 CPUs."""

    def __init__(self, n_neurons, storage, neuron_sign, scale_pre, region_id,
                 sensory_slice, motor_slice, vocab_data=None, delay_max=6,
                 target_fire_rate=0.04, n_layers=1, source_model_path=None):
        self.N = int(n_neurons)
        self.storage = storage
        self.neuron_sign = np.asarray(neuron_sign, dtype=np.int8)
        self.scale_pre = np.asarray(scale_pre, dtype=np.float32)
        self.region_id = np.asarray(region_id, dtype=np.int32)
        self.sensory_slice = (int(sensory_slice[0]), int(sensory_slice[1]))
        self.motor_slice = (int(motor_slice[0]), int(motor_slice[1]))
        self.vocab_data = vocab_data
        self.delay_max = max(int(delay_max), 4)
        self.target_fire_rate = float(target_fire_rate)
        self.n_layers = int(n_layers)
        self.source_model_path = source_model_path

        self.v_basal = np.zeros(self.N, dtype=np.float32)
        self.v_apical = np.zeros(self.N, dtype=np.float32)
        self.theta = np.full(self.N, 0.60, dtype=np.float32)
        self.rate_ema = np.full(self.N, self.target_fire_rate, dtype=np.float32)
        self.refrac = np.zeros(self.N, dtype=np.uint8)

        self.delay_ring = np.zeros((self.delay_max, 2, self.N), dtype=np.float32)
        self._delay_ring_flat = self.delay_ring.ravel()

        self.pre_trace = np.zeros(self.N, dtype=np.float32)
        self.post_trace = np.zeros(self.N, dtype=np.float32)

        # Pre-allocated scratch buffers (eliminates ~15 full-N mallocs/tick)
        self._buf_i_soma = np.zeros(self.N, dtype=np.float32)
        self._buf_ap_tmp = np.zeros(self.N, dtype=np.float32)
        self._buf_ready = np.zeros(self.N, dtype=bool)
        self._buf_not_ready = np.zeros(self.N, dtype=bool)
        self._buf_fired = np.zeros(self.N, dtype=bool)
        self._buf_fired_f = np.zeros(self.N, dtype=np.float32)

        self.drives = {d: 0.5 for d in DRIVES}
        self.tick = 0
        self.prev_hist_mask = None
        self.last_spikes = np.empty(0, dtype=np.int64)
        self._n_regions = max(int(self.region_id.max()) + 1, 2) if self.N > 0 else 2
        self._k_bin = min(8, self._n_regions)
        self._reg_bin = (self.region_id % self._k_bin).astype(np.int64)

    def reset_state(self):
        self.v_basal.fill(0.0)
        self.v_apical.fill(0.0)
        self.refrac.fill(0)
        self.delay_ring.fill(0.0)
        self.pre_trace.fill(0.0)
        self.post_trace.fill(0.0)
        self.tick = 0
        self.prev_hist_mask = None
        self.last_spikes = np.empty(0, dtype=np.int64)

    def step(self, sensory_current=None, reward_signal=0.0, plasticity=False, homeostasis=None):
        """Executes ONE zero-allocation event-driven biological tick on CPU."""
        slot = self.tick % self.delay_max
        I_basal = self.delay_ring[slot, 0]
        I_apical = self.delay_ring[slot, 1]

        if sensory_current is not None:
            s0, s1 = self.sensory_slice
            I_basal[s0:s1] += sensory_current

        ach_gain = np.float32(0.35 + 0.90 * self.drives["flow_bifurcation"])
        ne_decay = np.float32(0.72 + 0.14 * self.drives["constraint_core"])
        ser_damp = 0.10 + 0.20 * self.drives["orbit_parity"]

        self.v_basal *= ne_decay
        self.v_basal += I_basal
        self.v_apical *= np.float32(0.88)
        self.v_apical += I_apical

        self.delay_ring[slot].fill(0.0)

        np.equal(self.refrac, 0, out=self._buf_ready)
        if not np.all(self._buf_ready):
            np.logical_not(self._buf_ready, out=self._buf_not_ready)
            self.refrac[self._buf_not_ready] -= 1
            self.v_basal[self._buf_not_ready] *= np.float32(0.25)

        # Sparse apical nonlinearity: only evaluate tanh on active apical dendrites
        np.copyto(self._buf_i_soma, self.v_basal)
        nz_ap = np.flatnonzero(self.v_apical > 1e-4)
        if len(nz_ap) > 0:
            self._buf_i_soma[nz_ap] *= np.float32(1.0) + ach_gain * np.tanh(self.v_apical[nz_ap])
        np.multiply(self.v_apical, np.float32(0.32), out=self._buf_ap_tmp)
        self._buf_i_soma += self._buf_ap_tmp

        np.greater_equal(self._buf_i_soma, self.theta, out=self._buf_fired)
        self._buf_fired &= self._buf_ready
        spiked = np.flatnonzero(self._buf_fired)

        max_spikes = max(16, int(self.N * max(self.target_fire_rate * 3.0, 0.12)))
        if len(spiked) > max_spikes:
            diff = self._buf_i_soma[spiked] - self.theta[spiked]
            top_idx = np.argpartition(diff, -max_spikes)[-max_spikes:]
            spiked = np.sort(spiked[top_idx])
            self._buf_fired.fill(False)
            self._buf_fired[spiked] = True

        if len(spiked) > 0:
            self.v_basal[spiked] = 0.0
            self.v_apical[spiked] *= np.float32(0.2)
            self.refrac[spiked] = 1 + (1 if ser_damp > 0.22 else 0)

        if homeostasis is None:
            homeostasis = plasticity
        fire_rate = float(len(spiked) / max(self.N, 1))
        if homeostasis:
            np.copyto(self._buf_fired_f, self._buf_fired, casting="unsafe")
            self.rate_ema *= np.float32(0.94)
            self.rate_ema += np.float32(0.06) * self._buf_fired_f
            self.theta += np.float32(0.10) * self._buf_fired_f
            self.theta -= np.float32(0.020) * (self.theta - np.float32(0.60))
            self.theta += np.float32(0.08) * (self.rate_ema - np.float32(self.target_fire_rate))
            self.theta += np.float32(0.15 * (fire_rate - self.target_fire_rate))
            np.clip(self.theta, 0.28, 3.0, out=self.theta)

        tot_edges_active = 0
        if len(spiked) > 0:
            starts = self.storage.indptr[spiked]
            ends = self.storage.indptr[spiked + 1]
            lens = ends - starts
            tot_edges_active = int(lens.sum())
            if tot_edges_active > 0:
                cum = np.cumsum(lens)
                offsets = np.repeat(starts - (cum - lens), lens)
                e_ids = np.arange(tot_edges_active, dtype=np.int64) + offsets
                targets = self.storage.indices[e_ids].astype(np.int64)
                pre_ids = np.repeat(spiked, lens)

                amp = np.clip(0.95 + 0.30 * (self._buf_i_soma[pre_ids] - self.theta[pre_ids]), 0.75, 2.0)
                contrib = (self.storage.weights_q8[e_ids].astype(np.float32)
                           * self.scale_pre[pre_ids] * amp)

                delays_e = np.maximum(self.storage.delays[e_ids].astype(np.int64), 1)
                arr_slot = (self.tick + delays_e) % self.delay_max
                cmp_arr = self.storage.compartments[e_ids].astype(np.int64)
                flat_targets = (arr_slot * 2 + cmp_arr) * self.N + targets

                # Empirically tuned: np.add.at outperforms bincount up to ~delay_max * N edges
                if tot_edges_active < self.delay_max * self.N:
                    np.add.at(self._delay_ring_flat, flat_targets, contrib)
                else:
                    accum = np.bincount(flat_targets, weights=contrib, minlength=self.delay_max * 2 * self.N)
                    self.delay_ring += accum.reshape(self.delay_max, 2, self.N).astype(np.float32)

                if plasticity:
                    self._apply_stdp(e_ids, pre_ids, targets, reward_signal)

        self.pre_trace *= np.float32(0.80)
        self.post_trace *= np.float32(0.80)
        if len(spiked) > 0:
            self.pre_trace[spiked] += np.float32(1.0)
            self.post_trace[spiked] += np.float32(1.0)

        self._update_drives(spiked, self._buf_fired, fire_rate, reward_signal)
        self.last_spikes = spiked
        self.tick += 1

        return {
            "tick": self.tick - 1,
            "n_spiked": len(spiked),
            "fire_rate": fire_rate,
            "active_synapses": tot_edges_active,
            "drives": dict(self.drives),
        }

    def _apply_stdp(self, e_ids, pre_ids, targets, reward_signal):
        """Soft-bounded Three-Factor STDP preserving Dale's Law."""
        da_mod = math.tanh(reward_signal)
        gate = 0.04 + 0.14 * abs(da_mod) + 0.05 * self.drives["bilinear_fiber"]
        coinc = (0.25 + self.pre_trace[pre_ids]) * (self.post_trace[targets] - 0.18)
        sign_mod = 1.0 if reward_signal >= -0.05 else -0.5

        w_cur = self.storage.weights_q8[e_ids].astype(np.float32)
        sgn = self.neuron_sign[pre_ids].astype(np.float32)
        abs_w = np.abs(w_cur)
        soft_gain = np.where(sign_mod * coinc >= 0.0, (127.0 - abs_w) / 127.0, abs_w / 127.0)
        dw = gate * sign_mod * coinc * (0.25 + 0.75 * soft_gain)
        w_new = w_cur + sgn * np.round(dw * 3.0)

        pos_mask = sgn > 0
        w_new[pos_mask] = np.clip(w_new[pos_mask], 1.0, 127.0)
        w_new[~pos_mask] = np.clip(w_new[~pos_mask], -127.0, -1.0)
        self.storage.weights_q8[e_ids] = w_new.astype(np.int8)

    def _update_drives(self, spiked, fired_mask, fire_rate, reward_signal):
        if len(spiked) > 4:
            H_reg = fast_entropy_batch(self._reg_bin[spiked], self._k_bin) / max(math.log(self._k_bin), 1e-9)
        else:
            H_reg = 0.0

        if self.prev_hist_mask is not None:
            mi_t = _fast_binary_mi(self.prev_hist_mask, spiked, self.N) / math.log(2.0)
        else:
            mi_t = 0.0
            self.prev_hist_mask = np.zeros(self.N, dtype=bool)
        np.copyto(self.prev_hist_mask, fired_mask)

        e_spikes = int(np.sum(self.neuron_sign[spiked] > 0)) if len(spiked) else 0
        ei_balance = 1.0 - abs((e_spikes / max(len(spiked), 1)) - 0.80)

        self.drives["homomorphism"] = float(np.clip(0.5 + 0.5 * math.tanh(reward_signal), 0.0, 1.0))
        self.drives["flow_bifurcation"] = float(np.clip(0.7 * self.drives["flow_bifurcation"] + 0.3 * H_reg, 0.0, 1.0))
        self.drives["spectral_op"] = float(np.clip(0.7 * self.drives["spectral_op"] + 0.3 * mi_t * 3.0, 0.0, 1.0))
        self.drives["constraint_core"] = float(np.clip(1.0 - abs(fire_rate - self.target_fire_rate) * 8.0, 0.0, 1.0))
        self.drives["orbit_parity"] = float(np.clip(0.6 * self.drives["orbit_parity"] + 0.4 * ei_balance, 0.0, 1.0))
        self.drives["bilinear_fiber"] = float(np.clip(0.5 * H_reg + 0.5 * ei_balance, 0.0, 1.0))

    def think(self, sensory_input, n_ticks=None, reward_signal=0.0, plasticity=False):
        if n_ticks is None:
            n_ticks = min(max(self.n_layers + 4, 8), 20)

        m0, m1 = self.motor_slice
        motor_acc = np.zeros(m1 - m0, dtype=np.float32)
        stats = []
        stim_ticks = max(1, n_ticks // 3)
        for t in range(n_ticks):
            st = self.step(
                sensory_current=(sensory_input if t < stim_ticks else None),
                reward_signal=reward_signal,
                plasticity=plasticity,
            )
            stats.append(st)
            w_t = (1.5 if t >= n_ticks // 2 else 0.5) / max(n_ticks, 1)
            motor_acc += w_t * np.maximum(self.v_basal[m0:m1] + 0.5 * self.v_apical[m0:m1], 0.0)
            if len(self.last_spikes) > 0:
                m_sp = self.last_spikes[(self.last_spikes >= m0) & (self.last_spikes < m1)] - m0
                if len(m_sp) > 0:
                    motor_acc[m_sp] += w_t * 2.0
        return motor_acc, stats

    def calibrate(self, n_probes=10, ticks_per_probe=10, seed=7):
        rng = np.random.default_rng(seed)
        s0, s1 = self.sensory_slice
        n_sens = s1 - s0
        k_on = max(8, n_sens // 10)
        rates = []
        motor_norms = []
        for _ in range(n_probes):
            self.reset_state()
            stim = np.zeros(n_sens, dtype=np.float32)
            stim[rng.choice(n_sens, size=k_on, replace=False)] = 1.35
            mot, stats = self.think(stim, n_ticks=ticks_per_probe, reward_signal=0.15, plasticity=True)
            rates.append(float(np.mean([s["fire_rate"] for s in stats])))
            motor_norms.append(float(np.linalg.norm(mot)))
        return {
            "avg_fire_rate": float(np.mean(rates)),
            "avg_motor_norm": float(np.mean(motor_norms)),
            "mean_theta": float(np.mean(self.theta)),
        }

    def save(self, out_dir):
        os.makedirs(out_dir, exist_ok=True)
        self.storage.save_to_dir(out_dir)
        np.save(os.path.join(out_dir, "neuron_sign.npy"), self.neuron_sign)
        np.save(os.path.join(out_dir, "scale_pre.npy"), self.scale_pre)
        np.save(os.path.join(out_dir, "region_id.npy"), self.region_id)
        np.save(os.path.join(out_dir, "theta.npy"), self.theta)
        np.save(os.path.join(out_dir, "rate_ema.npy"), self.rate_ema)

        if self.vocab_data is not None:
            v_dir = os.path.join(out_dir, "vocab")
            os.makedirs(v_dir, exist_ok=True)
            v_meta = {
                "vocab_size": int(self.vocab_data["vocab_size"]),
                "embed_dim": int(self.vocab_data["embed_dim"]),
                "head_dim": int(self.vocab_data["head_dim"]),
                "tied": bool(self.vocab_data.get("tied", False)),
            }
            with open(os.path.join(v_dir, "vocab_meta.json"), "w", encoding="utf-8") as fh:
                json.dump(v_meta, fh)
            for k, v in self.vocab_data.items():
                if k in ("vocab_size", "embed_dim", "head_dim", "tied", "embed_q8", "head_q8"):
                    continue
                if isinstance(v, np.ndarray):
                    np.save(os.path.join(v_dir, f"{k}.npy"), v)
                else:
                    with open(os.path.join(v_dir, f"{k}.json"), "w", encoding="utf-8") as fh:
                        json.dump(v, fh)
            # Save memmap-backed int8 tables if not already written in v_dir
            for key, fname in (("embed_q8", "embed_q8.i8"), ("head_q8", "head_q8.i8")):
                if key == "head_q8" and v_meta["tied"]:
                    continue
                arr = self.vocab_data.get(key)
                if arr is not None:
                    dst_p = os.path.join(v_dir, fname)
                    src_fn = getattr(arr, "filename", None)
                    if src_fn and os.path.abspath(src_fn) == os.path.abspath(dst_p):
                        if isinstance(arr, np.memmap):
                            arr.flush()
                    else:
                        with open(dst_p, "wb") as fh:
                            for r0 in range(0, arr.shape[0], 16384):
                                fh.write(np.asarray(arr[r0 : r0 + 16384]).tobytes())

        meta = {
            "version": "4.0",
            "N": self.N,
            "sensory_slice": list(self.sensory_slice),
            "motor_slice": list(self.motor_slice),
            "delay_max": self.delay_max,
            "target_fire_rate": self.target_fire_rate,
            "n_layers": self.n_layers,
            "drives": self.drives,
            "has_vocab": self.vocab_data is not None,
            "source_model_path": self.source_model_path,
        }
        with open(os.path.join(out_dir, "brain_meta.json"), "w", encoding="utf-8") as fh:
            json.dump(meta, fh, indent=2)

    @classmethod
    def load(cls, brain_dir, writable=True):
        with open(os.path.join(brain_dir, "brain_meta.json"), "r", encoding="utf-8") as fh:
            meta = json.load(fh)
        storage = ConnectomeStorage.load_from_dir(brain_dir, writable=writable)
        neuron_sign = np.load(os.path.join(brain_dir, "neuron_sign.npy"))
        scale_pre = np.load(os.path.join(brain_dir, "scale_pre.npy"))
        region_id = np.load(os.path.join(brain_dir, "region_id.npy"))
        theta = np.load(os.path.join(brain_dir, "theta.npy"))
        rate_ema_p = os.path.join(brain_dir, "rate_ema.npy")
        rate_ema = np.load(rate_ema_p) if os.path.exists(rate_ema_p) else None

        vocab_data = None
        if meta.get("has_vocab"):
            v_dir = os.path.join(brain_dir, "vocab")
            if os.path.isdir(v_dir):
                vocab_data = {}
                for fn in os.listdir(v_dir):
                    p = os.path.join(v_dir, fn)
                    if fn.endswith(".npy"):
                        vocab_data[fn[:-4]] = np.load(p)
                    elif fn.endswith(".json") and fn != "vocab_meta.json":
                        with open(p, "r", encoding="utf-8") as fh:
                            vocab_data[fn[:-5]] = json.load(fh)
                vm_p = os.path.join(v_dir, "vocab_meta.json")
                if os.path.exists(vm_p):
                    with open(vm_p, "r", encoding="utf-8") as fh:
                        vm = json.load(fh)
                    vocab_data.update(vm)
                    V = int(vm["vocab_size"])
                    ed, hd = int(vm["embed_dim"]), int(vm["head_dim"])
                    eq8_p = os.path.join(v_dir, "embed_q8.i8")
                    if os.path.exists(eq8_p):
                        vocab_data["embed_q8"] = np.memmap(eq8_p, dtype=np.int8, mode="r", shape=(V, ed))
                    if vm.get("tied"):
                        vocab_data["head_q8"] = vocab_data.get("embed_q8")
                        vocab_data["head_scale"] = vocab_data.get("embed_scale")
                    else:
                        hq8_p = os.path.join(v_dir, "head_q8.i8")
                        if os.path.exists(hq8_p):
                            vocab_data["head_q8"] = np.memmap(hq8_p, dtype=np.int8, mode="r", shape=(V, hd))

        brain = cls(
            meta["N"], storage, neuron_sign, scale_pre, region_id,
            sensory_slice=tuple(meta["sensory_slice"]),
            motor_slice=tuple(meta["motor_slice"]),
            vocab_data=vocab_data,
            delay_max=meta["delay_max"],
            target_fire_rate=meta["target_fire_rate"],
            n_layers=meta.get("n_layers", 1),
            source_model_path=meta.get("source_model_path"),
        )
        brain.theta = theta.astype(np.float32)
        if rate_ema is not None:
            brain.rate_ema = rate_ema.astype(np.float32)
        brain.drives = meta.get("drives", brain.drives)
        return brain

    def close(self):
        self.storage.close()
        if self.vocab_data:
            for k in ("embed_q8", "head_q8"):
                arr = self.vocab_data.get(k)
                if isinstance(arr, np.memmap) and getattr(arr, "_mmap", None) is not None:
                    arr._mmap.close()
                self.vocab_data[k] = None


# =====================================================================
# 4. Out-of-Core Frontier LLM -> Biological Brain Converter
# =====================================================================
class LLMToBrainConverter:
    """Converts HuggingFace Safetensors OR GGUF frontier models (Dense SwiGLU,
    MoE Experts, GQA, RMSNorm, Tied Embeddings, FP8/BF16/Q4_K/Q6_K/Q8_0)
    into a sparse Dale's-Law-compliant BiologicalBrain on a 2014 CPU."""

    @staticmethod
    def _fold_columns(chunk_f32, col_target):
        """15x faster vectorized variance-preserving cortical column pooling."""
        rows, cols = chunk_f32.shape
        if cols == col_target:
            return chunk_f32
        if cols > col_target:
            if cols % col_target == 0:
                blk = cols // col_target
                pooled = chunk_f32.reshape(rows, col_target, blk).mean(axis=2)
                return pooled * np.float32(math.sqrt(blk))
            col_ids = (np.arange(cols, dtype=np.int64) * col_target) // cols
            counts = np.bincount(col_ids, minlength=col_target).astype(np.float32)
            starts = np.flatnonzero(np.concatenate(([True], col_ids[1:] != col_ids[:-1])))
            scale = (np.sqrt(counts) / np.maximum(counts, 1.0)).astype(np.float32)
            return np.add.reduceat(chunk_f32, starts, axis=1) * scale[None, :]
        reps = math.ceil(col_target / cols)
        return np.tile(chunk_f32, (1, reps))[:, :col_target]

    @classmethod
    def _fold_1d(cls, vec, col_target):
        if vec is None:
            return None
        return cls._fold_columns(vec.reshape(1, -1).astype(np.float32), col_target).ravel()

    @classmethod
    def _stream_fold_matrix(cls, row_chunk_iter, total_rows, src_dim_target, dst_dim_target,
                            transpose=False, col_norm=None):
        """Streams a matrix W in row chunks and returns compact folded matrix [dst, src]."""
        if transpose:
            # W stored as [in_dim, out_dim]; total_rows = in_dim, cols = out_dim
            acc = np.zeros((dst_dim_target, src_dim_target), dtype=np.float32)
            cnt = np.zeros(src_dim_target, dtype=np.int32)
            col_scale = math.sqrt(max(total_rows / max(src_dim_target, 1), 1.0))
            for r0, chunk in row_chunk_iter:
                if col_norm is not None:
                    chunk = chunk * col_norm[r0 : r0 + chunk.shape[0], None]
                folded_dst = cls._fold_columns(chunk, dst_dim_target)  # (n_r, dst_dim_target)
                n_r = folded_dst.shape[0]
                src_ids = (np.arange(r0, r0 + n_r, dtype=np.int64) * src_dim_target) // max(total_rows, 1)
                np.add.at(acc.T, src_ids, folded_dst)
                np.add.at(cnt, src_ids, 1)
                del chunk, folded_dst
            acc /= np.maximum(cnt[None, :], 1)
            return acc * np.float32(col_scale)

        acc = np.zeros((dst_dim_target, src_dim_target), dtype=np.float32)
        cnt = np.zeros(dst_dim_target, dtype=np.int32)
        row_scale = math.sqrt(max(total_rows / max(dst_dim_target, 1), 1.0))
        norm_folded = cls._fold_1d(col_norm, src_dim_target) if col_norm is not None else None

        for r0, chunk in row_chunk_iter:
            folded = cls._fold_columns(chunk, src_dim_target)
            if norm_folded is not None:
                folded *= norm_folded[None, :]
            n_r = folded.shape[0]
            dst_ids = (np.arange(r0, r0 + n_r, dtype=np.int64) * dst_dim_target) // max(total_rows, 1)
            np.add.at(acc, dst_ids, folded)
            np.add.at(cnt, dst_ids, 1)
            del chunk, folded

        acc /= np.maximum(cnt[:, None], 1)
        return acc * np.float32(row_scale)

    @classmethod
    def _topk_from_folded_matrix(cls, mat_dst_src, k_per_src, target_rms=0.30):
        dst_n, src_n = mat_dst_src.shape
        mat_T = np.ascontiguousarray(mat_dst_src.T)
        k_eff = min(max(int(k_per_src), 1), dst_n)

        if k_eff < dst_n:
            top_dst = np.argpartition(np.abs(mat_T), -k_eff, axis=1)[:, -k_eff:]
            row_idx = np.arange(src_n, dtype=np.int64)[:, None]
            top_w = mat_T[row_idx, top_dst]
        else:
            top_dst = np.broadcast_to(np.arange(dst_n, dtype=np.int64), (src_n, dst_n)).copy()
            top_w = mat_T.copy()

        rms = float(np.sqrt(np.mean(top_w * top_w))) + 1e-8
        top_w = top_w * np.float32(target_rms / rms)

        src_flat = np.repeat(np.arange(src_n, dtype=np.int64), k_eff)
        dst_flat = top_dst.ravel().astype(np.int64)
        w_flat = top_w.ravel().astype(np.float32)

        nz = np.abs(w_flat) > 1e-5
        if not np.all(nz):
            src_flat, dst_flat, w_flat = src_flat[nz], dst_flat[nz], w_flat[nz]
        return src_flat, dst_flat, w_flat

    @classmethod
    def _extract_topk_edges_from_stream(cls, row_chunk_iter, total_rows, src_dim_target,
                                        dst_dim_target, k_per_src, seed=7, target_rms=0.30,
                                        transpose=False, col_norm=None):
        acc = cls._stream_fold_matrix(
            row_chunk_iter, total_rows, src_dim_target, dst_dim_target,
            transpose=transpose, col_norm=col_norm,
        )
        return cls._topk_from_folded_matrix(acc, k_per_src, target_rms=target_rms)

    @staticmethod
    def _dedup_edges(src, dst, w, cmp_arr, n_src, max_k=None, protected_mask=None):
        if len(src) == 0:
            return src, dst, w, cmp_arr
        src = np.asarray(src, dtype=np.int64)
        dst = np.asarray(dst, dtype=np.int64)
        w = np.asarray(w, dtype=np.float32)
        cmp_arr = np.asarray(cmp_arr, dtype=np.uint8)
        prot = (np.asarray(protected_mask, dtype=bool)
                if protected_mask is not None else np.zeros(len(src), dtype=bool))

        order = np.lexsort((cmp_arr, dst, src))
        s_s, d_s, c_s, w_s, p_s = src[order], dst[order], cmp_arr[order], w[order], prot[order]

        uniq_mask = np.empty(len(s_s), dtype=bool)
        uniq_mask[0] = True
        uniq_mask[1:] = (s_s[1:] != s_s[:-1]) | (d_s[1:] != d_s[:-1]) | (c_s[1:] != c_s[:-1])

        first_idx = np.flatnonzero(uniq_mask)
        w_sum = np.add.reduceat(w_s, first_idx)
        p_any = np.maximum.reduceat(p_s.astype(np.uint8), first_idx).astype(bool)
        src_u, dst_u, cmp_u = s_s[first_idx], d_s[first_idx], c_s[first_idx]

        nz = np.abs(w_sum) > 1e-5
        src_u, dst_u, w_sum, cmp_u, p_any = src_u[nz], dst_u[nz], w_sum[nz], cmp_u[nz], p_any[nz]

        if max_k is not None and len(src_u) > 0:
            counts = np.bincount(src_u, minlength=n_src)
            if np.any(counts > max_k):
                keep_parts = []
                starts = np.zeros(n_src, dtype=np.int64)
                starts[1:] = np.cumsum(counts[:-1])
                for s_id in np.flatnonzero(counts):
                    st = starts[s_id]
                    cnt = counts[s_id]
                    if cnt <= max_k:
                        keep_parts.append(np.arange(st, st + cnt, dtype=np.int64))
                    else:
                        sub_p = p_any[st:st + cnt]
                        prot_idx = np.flatnonzero(sub_p)
                        if len(prot_idx) >= max_k:
                            sel = prot_idx[np.argpartition(np.abs(w_sum[st + prot_idx]), -max_k)[-max_k:]]
                            keep_parts.append(st + sel)
                        else:
                            unprot_idx = np.flatnonzero(~sub_p)
                            rem = max_k - len(prot_idx)
                            if len(unprot_idx) > rem:
                                top_u = unprot_idx[np.argpartition(np.abs(w_sum[st + unprot_idx]), -rem)[-rem:]]
                            else:
                                top_u = unprot_idx
                            keep_parts.append(st + np.concatenate([prot_idx, top_u]))
                keep_idx = np.sort(np.concatenate(keep_parts))
                src_u, dst_u, w_sum, cmp_u = src_u[keep_idx], dst_u[keep_idx], w_sum[keep_idx], cmp_u[keep_idx]
        return src_u, dst_u, w_sum, cmp_u

    @classmethod
    def _emit_dale_compliant_pool(cls, storage, n_pyr, n_inh,
                                  pyr_edges, scale_pre, neuron_sign, region_id,
                                  reg_val, pyr_base, prev_pyr_base,
                                  k_synapses, delay_max, rng,
                                  protected_edges=None):
        src_l, dst_g, w_f, cmps = pyr_edges
        inh_base = pyr_base + n_pyr

        neuron_sign[pyr_base:inh_base] = 1
        region_id[pyr_base:inh_base] = reg_val

        pos_mask = w_f >= 0.0
        neg_mask = ~pos_mask

        e_src = [src_l[pos_mask]]
        e_dst = [dst_g[pos_mask]]
        e_w = [w_f[pos_mask]]
        e_cmp = [cmps[pos_mask]]
        e_prot = [np.zeros(int(np.sum(pos_mask)), dtype=bool)]

        if protected_edges is not None:
            ps, pd, pw, pc = protected_edges
            e_src.append(ps); e_dst.append(pd); e_w.append(pw); e_cmp.append(pc)
            e_prot.append(np.ones(len(ps), dtype=bool))

        if np.any(neg_mask) and n_inh > 0:
            neg_src = src_l[neg_mask]
            neg_dst_t = dst_g[neg_mask]
            neg_w = np.abs(w_f[neg_mask])
            local_i = neg_dst_t % n_inh

            e_src.append(neg_src)
            e_dst.append(inh_base + local_i)
            e_w.append(np.maximum(neg_w * 1.15, 0.24))
            e_cmp.append(np.zeros(len(neg_src), dtype=np.uint8))
            e_prot.append(np.zeros(len(neg_src), dtype=bool))

            i_src_raw, i_dst_raw, i_w_raw, i_cmp_raw = local_i, neg_dst_t, -neg_w, cmps[neg_mask]
        else:
            i_src_raw = np.empty(0, dtype=np.int64)
            i_dst_raw = np.empty(0, dtype=np.int64)
            i_w_raw = np.empty(0, dtype=np.float32)
            i_cmp_raw = np.empty(0, dtype=np.uint8)

        loc_src = np.arange(n_pyr, dtype=np.int64)
        loc_dst = pyr_base + ((loc_src + rng.integers(1, max(n_pyr // 4, 2), size=n_pyr)) % n_pyr)
        e_src.append(loc_src); e_dst.append(loc_dst)
        e_w.append(np.full(n_pyr, 0.26, dtype=np.float32))
        e_cmp.append(np.zeros(n_pyr, dtype=np.uint8))
        e_prot.append(np.ones(n_pyr, dtype=bool))

        if prev_pyr_base is not None:
            fb_src = np.arange(0, n_pyr, 2, dtype=np.int64)
            fb_dst = prev_pyr_base + (fb_src % n_pyr)
            e_src.append(fb_src); e_dst.append(fb_dst)
            e_w.append(np.full(len(fb_src), 0.24, dtype=np.float32))
            e_cmp.append(np.ones(len(fb_src), dtype=np.uint8))
            e_prot.append(np.zeros(len(fb_src), dtype=bool))

        e_src_all, e_dst_all, e_w_all, e_cmp_all = cls._dedup_edges(
            np.concatenate(e_src), np.concatenate(e_dst),
            np.concatenate(e_w), np.concatenate(e_cmp),
            n_pyr, max_k=k_synapses + 10, protected_mask=np.concatenate(e_prot),
        )

        e_scales = np.ones(n_pyr, dtype=np.float32) * 0.01
        if len(e_src_all) > 0:
            max_abs = np.zeros(n_pyr, dtype=np.float32)
            np.maximum.at(max_abs, e_src_all, np.abs(e_w_all))
            e_scales = np.maximum(max_abs / 127.0, 1e-5)
            e_q8 = np.clip(np.round(e_w_all / e_scales[e_src_all]), 1, 127).astype(np.int8)
            e_del = rng.integers(1, min(4, delay_max), size=len(e_src_all), dtype=np.uint8)
        else:
            e_q8 = np.empty(0, dtype=np.int8)
            e_del = np.empty(0, dtype=np.uint8)
        scale_pre[pyr_base:inh_base] = e_scales
        storage.append_neuron_block(pyr_base, n_pyr, e_src_all, e_dst_all, e_q8, e_del, e_cmp_all)

        neuron_sign[inh_base:inh_base + n_inh] = -1
        region_id[inh_base:inh_base + n_inh] = reg_val

        lat_i_src = np.arange(n_inh, dtype=np.int64)
        lat_i_dst = pyr_base + ((lat_i_src * max(n_pyr // max(n_inh, 1), 1)) % n_pyr)
        lat_i_w = np.full(n_inh, -0.28, dtype=np.float32)
        lat_i_cmp = np.zeros(n_inh, dtype=np.uint8)

        all_i_src = np.concatenate([i_src_raw, lat_i_src]) if len(i_src_raw) else lat_i_src
        all_i_dst = np.concatenate([i_dst_raw, lat_i_dst]) if len(i_src_raw) else lat_i_dst
        all_i_w = np.concatenate([-np.abs(i_w_raw) * 0.85, lat_i_w]) if len(i_src_raw) else lat_i_w
        all_i_cmp = np.concatenate([i_cmp_raw, lat_i_cmp]) if len(i_src_raw) else lat_i_cmp

        all_i_src, all_i_dst, all_i_w, all_i_cmp = cls._dedup_edges(
            all_i_src, all_i_dst, all_i_w, all_i_cmp, n_inh, max_k=max(k_synapses * 2, 32)
        )

        i_scales = np.ones(n_inh, dtype=np.float32) * 0.01
        if len(all_i_src) > 0:
            max_abs_i = np.zeros(n_inh, dtype=np.float32)
            np.maximum.at(max_abs_i, all_i_src, np.abs(all_i_w))
            i_scales = np.maximum(max_abs_i / 127.0, 1e-5)
            i_q8 = np.clip(np.round(all_i_w / i_scales[all_i_src]), -127, -1).astype(np.int8)
            i_del = rng.integers(1, min(3, delay_max), size=len(all_i_src), dtype=np.uint8)
        else:
            i_q8 = np.empty(0, dtype=np.int8)
            i_del = np.empty(0, dtype=np.uint8)
        scale_pre[inh_base:inh_base + n_inh] = i_scales
        storage.append_neuron_block(inh_base, n_inh, all_i_src, all_i_dst, i_q8, i_del, all_i_cmp)

    @classmethod
    def _extract_vocab_projection_memmap(cls, reader, tensor_name, col_target, out_q8_path, chunk_rows=2048):
        """Streams embed_tokens / lm_head [vocab, d_model] directly into disk-backed int8 memmap."""
        tinfo = reader.tensor_info(tensor_name)
        if tinfo is None:
            return None, None, 0
        v_size = int(tinfo["shape"][0])
        scales = np.empty(v_size, dtype=np.float32)
        if out_q8_path is not None:
            os.makedirs(os.path.dirname(out_q8_path), exist_ok=True)
            with open(out_q8_path, "wb") as fh:
                for r0, chunk in reader.iter_row_chunks(tensor_name, chunk_rows=chunk_rows):
                    folded = cls._fold_columns(chunk, col_target)
                    row_max = np.maximum(np.max(np.abs(folded), axis=1), 1e-5)
                    sc = row_max / 127.0
                    r1 = r0 + folded.shape[0]
                    q8 = np.clip(np.round(folded / sc[:, None]), -127, 127).astype(np.int8)
                    fh.write(q8.tobytes())
                    scales[r0:r1] = sc
            q8_mat = np.memmap(out_q8_path, dtype=np.int8, mode="r", shape=(v_size, col_target))
        else:
            q8_mat = np.empty((v_size, col_target), dtype=np.int8)
            for r0, chunk in reader.iter_row_chunks(tensor_name, chunk_rows=chunk_rows):
                folded = cls._fold_columns(chunk, col_target)
                row_max = np.maximum(np.max(np.abs(folded), axis=1), 1e-5)
                sc = row_max / 127.0
                r1 = r0 + folded.shape[0]
                q8_mat[r0:r1] = np.clip(np.round(folded / sc[:, None]), -127, 127).astype(np.int8)
                scales[r0:r1] = sc
        return q8_mat, scales, v_size

    @classmethod
    def convert_model(cls, model_path, out_dir=None, col_neurons=256,
                      k_synapses=24, max_ram_mb=512, delay_max=6,
                      seed=7, log=print):
        """Auto-detects HuggingFace Safetensors directory OR GGUF file(s) and converts."""
        is_gguf = os.path.isfile(model_path) and model_path.endswith(".gguf")
        if not is_gguf and os.path.isdir(model_path):
            has_st = any(f.endswith(".safetensors") for f in os.listdir(model_path))
            has_gguf = any(f.endswith(".gguf") for f in os.listdir(model_path))
            if has_gguf and not has_st:
                is_gguf = True
        if is_gguf:
            return cls.convert_gguf(model_path, out_dir=out_dir, col_neurons=col_neurons,
                                    k_synapses=k_synapses, max_ram_mb=max_ram_mb,
                                    delay_max=delay_max, seed=seed, log=log)
        return cls.convert_safetensors_dir(model_path, out_dir=out_dir, col_neurons=col_neurons,
                                           k_synapses=k_synapses, max_ram_mb=max_ram_mb,
                                           delay_max=delay_max, seed=seed, log=log)

    @classmethod
    def _convert_from_reader(cls, reader, cfg, tok_meta, out_dir=None, col_neurons=256,
                             k_synapses=24, max_ram_mb=512, delay_max=6, seed=7, log=print,
                             source_model_path=None):
        t0 = time.time()
        n_layers = int(cfg.get("num_hidden_layers", cfg.get("n_layer", 12)))
        d_model = int(cfg.get("hidden_size", cfg.get("n_embd", 768)))
        n_heads = int(cfg.get("num_attention_heads", max(1, d_model // 64)))
        n_kv_heads = int(cfg.get("num_key_value_heads", n_heads))
        n_pyr = min(int(col_neurons), d_model)
        n_inh = max(16, n_pyr // 4)
        per_layer = n_pyr + n_inh

        n_sensory = n_pyr
        n_motor = n_pyr
        total_neurons = n_sensory + n_layers * per_layer + n_motor

        est_edges = total_neurons * (k_synapses + 10)
        use_memmap = (est_edges * 7) > (max_ram_mb * 1024 * 1024 // 2) or (out_dir is not None)
        if use_memmap and out_dir is None:
            out_dir = tempfile.mkdtemp(prefix="apeiron_brain_")

        storage = ConnectomeStorage(total_neurons, storage_dir=out_dir if use_memmap else None)
        neuron_sign = np.ones(total_neurons, dtype=np.int8)
        scale_pre = np.ones(total_neurons, dtype=np.float32) * 0.01
        region_id = np.zeros(total_neurons, dtype=np.int32)
        rng = np.random.default_rng(seed)

        log(f"[Converter] Streaming {n_layers} layers (d_model={d_model} -> {n_pyr}E+{n_inh}I/layer, "
            f"N={total_neurons:,}, memmap={use_memmap})")

        # Memmap-backed Vocabulary Extraction
        vocab_data = None
        emb_name = reader.find_first([
            "model.embed_tokens.weight", "transformer.wte.weight",
            "model.decoder.embed_tokens.weight", "token_embd.weight",
        ])
        head_name = reader.find_first(["lm_head.weight", "output.weight"])
        if emb_name is not None:
            v_dir = os.path.join(out_dir, "vocab") if out_dir is not None else None
            emb_p = os.path.join(v_dir, "embed_q8.i8") if v_dir else None
            emb_q8, emb_sc, v_size = cls._extract_vocab_projection_memmap(reader, emb_name, n_sensory, emb_p)

            tied = (head_name is None) or bool(cfg.get("tie_word_embeddings", False))
            if not tied and head_name is not None:
                head_p = os.path.join(v_dir, "head_q8.i8") if v_dir else None
                head_q8, head_sc, _ = cls._extract_vocab_projection_memmap(reader, head_name, n_motor, head_p)
            else:
                tied = True
                head_q8, head_sc = emb_q8, emb_sc

            vocab_data = {
                "vocab_size": v_size,
                "embed_dim": n_sensory,
                "head_dim": n_motor,
                "tied": tied,
                "embed_q8": emb_q8,
                "embed_scale": emb_sc,
                "head_q8": head_q8,
                "head_scale": head_sc,
            }
            if tok_meta:
                for tk, tv in tok_meta.items():
                    if tv is not None:
                        vocab_data[tk] = tv

        # 1. Sensory Thalamo-Cortical Layer -> Layer 0 (+ long-range white-matter skips)
        s_src = [np.arange(n_sensory, dtype=np.int64)]
        s_dst = [n_sensory + np.arange(n_sensory, dtype=np.int64) % n_pyr]
        s_w = [np.full(n_sensory, 95, dtype=np.int8)]
        s_del = [np.ones(n_sensory, dtype=np.uint8)]
        s_cmp = [np.zeros(n_sensory, dtype=np.uint8)]
        if n_layers > 4:
            for frac, w_val, d_val in ((0.5, 55, 2), (0.85, 40, 3)):
                skip_l = min(n_layers - 1, max(1, int(n_layers * frac)))
                idx_s = np.arange(0, n_sensory, 2, dtype=np.int64)
                s_src.append(idx_s)
                s_dst.append(n_sensory + skip_l * per_layer + (idx_s % n_pyr))
                s_w.append(np.full(len(idx_s), w_val, dtype=np.int8))
                s_del.append(np.full(len(idx_s), d_val, dtype=np.uint8))
                s_cmp.append(np.zeros(len(idx_s), dtype=np.uint8))
        scale_pre[:n_sensory] = 0.022
        storage.append_neuron_block(
            0, n_sensory,
            np.concatenate(s_src), np.concatenate(s_dst),
            np.concatenate(s_w), np.concatenate(s_del), np.concatenate(s_cmp),
        )

        # 2. Stream Each Transformer Layer Out-of-Core
        motor_base = n_sensory + n_layers * per_layer
        for L in range(n_layers):
            pyr_base = n_sensory + L * per_layer
            next_pyr_base = pyr_base + per_layer
            prev_pyr_base = (pyr_base - per_layer) if L > 0 else None

            all_src, all_dst, all_w, all_cmp = [], [], [], []
            prot_src, prot_dst, prot_w, prot_cmp = [], [], [], []

            in_norm = reader.read_1d(reader.find_first([
                f"model.layers.{L}.input_layernorm.weight",
                f"transformer.h.{L}.ln_1.weight",
                f"blk.{L}.attn_norm.weight",
            ]))
            post_norm = reader.read_1d(reader.find_first([
                f"model.layers.{L}.post_attention_layernorm.weight",
                f"transformer.h.{L}.ln_2.weight",
                f"blk.{L}.ffn_norm.weight",
            ]))

            # Attention Output + Q/K/V GQA Structural Modulation
            attn_name = reader.find_first([
                f"model.layers.{L}.self_attn.o_proj.weight",
                f"transformer.h.{L}.attn.c_proj.weight",
                f"model.layers.{L}.self_attn.dense.weight",
                f"blk.{L}.attn_output.weight",
            ])
            q_name = reader.find_first([f"model.layers.{L}.self_attn.q_proj.weight", f"blk.{L}.attn_q.weight"])
            k_name = reader.find_first([f"model.layers.{L}.self_attn.k_proj.weight", f"blk.{L}.attn_k.weight"])
            v_name = reader.find_first([f"model.layers.{L}.self_attn.v_proj.weight", f"blk.{L}.attn_v.weight"])
            qkv_name = reader.find_first([
                f"model.layers.{L}.self_attn.qkv_proj.weight",
                f"transformer.h.{L}.attn.c_attn.weight",
                f"blk.{L}.attn_qkv.weight",
            ])

            if attn_name is not None:
                tinfo = reader.tensor_info(attn_name)
                is_conv1d = ("c_proj" in attn_name) and (len(tinfo["shape"]) == 2 and tinfo["shape"][0] == d_model)
                o_col = cls._stream_fold_matrix(
                    reader.iter_row_chunks(attn_name, chunk_rows=512),
                    tinfo["shape"][0], n_pyr, n_pyr, transpose=is_conv1d,
                )
                if q_name is not None and k_name is not None:
                    q_col = cls._stream_fold_matrix(
                        reader.iter_row_chunks(q_name, chunk_rows=512),
                        reader.tensor_info(q_name)["shape"][0], n_pyr, n_pyr, col_norm=in_norm,
                    )
                    k_col = cls._stream_fold_matrix(
                        reader.iter_row_chunks(k_name, chunk_rows=512),
                        reader.tensor_info(k_name)["shape"][0], n_pyr, n_pyr, col_norm=in_norm,
                    )
                    # Effective bilinear Q^T K structural interaction (GQA-compatible in folded space)
                    qk_eff = np.tanh((q_col.T @ k_col) / np.float32(max(math.sqrt(n_pyr), 1.0)))
                    attn_eff = o_col @ (np.eye(n_pyr, dtype=np.float32) + np.float32(0.25) * qk_eff)
                    del q_col, k_col, qk_eff
                else:
                    attn_eff = o_col
                s_loc, d_loc, w_loc = cls._topk_from_folded_matrix(
                    attn_eff, max(6, k_synapses // 2), target_rms=0.34
                )
                all_src.append(s_loc); all_dst.append(next_pyr_base + d_loc)
                all_w.append(w_loc); all_cmp.append(np.zeros(len(s_loc), dtype=np.uint8))
                del o_col, attn_eff

            if v_name is not None:
                tinfo = reader.tensor_info(v_name)
                s_loc, d_loc, w_loc = cls._extract_topk_edges_from_stream(
                    reader.iter_row_chunks(v_name, chunk_rows=512),
                    total_rows=tinfo["shape"][0],
                    src_dim_target=n_pyr, dst_dim_target=n_pyr,
                    k_per_src=max(4, k_synapses // 4), seed=seed + L * 29,
                    target_rms=0.20, col_norm=in_norm,
                )
                all_src.append(s_loc); all_dst.append(next_pyr_base + d_loc)
                all_w.append(w_loc); all_cmp.append(np.ones(len(s_loc), dtype=np.uint8))
            elif qkv_name is not None:
                # Fused QKV: take Value slice (last third) into apical compartment
                tinfo = reader.tensor_info(qkv_name)
                tot_r = tinfo["shape"][0]
                v_start = (2 * tot_r) // 3
                s_loc, d_loc, w_loc = cls._extract_topk_edges_from_stream(
                    reader.iter_row_chunks(qkv_name, chunk_rows=512, row_range=(v_start, tot_r)),
                    total_rows=tot_r - v_start,
                    src_dim_target=n_pyr, dst_dim_target=n_pyr,
                    k_per_src=max(4, k_synapses // 4), seed=seed + L * 29,
                    target_rms=0.20, col_norm=in_norm,
                )
                all_src.append(s_loc); all_dst.append(next_pyr_base + d_loc)
                all_w.append(w_loc); all_cmp.append(np.ones(len(s_loc), dtype=np.uint8))

            # Dense SwiGLU MLP OR MoE Experts (Mixtral / DeepSeek / Qwen-MoE)
            up_name = reader.find_first([
                f"model.layers.{L}.mlp.up_proj.weight",
                f"transformer.h.{L}.mlp.c_fc.weight",
                f"blk.{L}.ffn_up.weight",
                f"model.layers.{L}.mlp.shared_experts.up_proj.weight",
                f"blk.{L}.ffn_up_shexp.weight",
            ])
            gate_name = reader.find_first([
                f"model.layers.{L}.mlp.gate_proj.weight",
                f"blk.{L}.ffn_gate.weight",
                f"model.layers.{L}.mlp.shared_experts.gate_proj.weight",
                f"blk.{L}.ffn_gate_shexp.weight",
            ])
            down_name = reader.find_first([
                f"model.layers.{L}.mlp.down_proj.weight",
                f"transformer.h.{L}.mlp.c_proj.weight",
                f"blk.{L}.ffn_down.weight",
                f"model.layers.{L}.mlp.shared_experts.down_proj.weight",
                f"blk.{L}.ffn_down_shexp.weight",
            ])

            mlp_acc = None
            if up_name is not None and down_name is not None:
                is_c_fc = ("c_fc" in up_name) and (reader.tensor_info(up_name)["shape"][0] == d_model)
                is_c_proj = ("c_proj" in down_name) and (reader.tensor_info(down_name)["shape"][1] == d_model)
                up_col = cls._stream_fold_matrix(
                    reader.iter_row_chunks(up_name, chunk_rows=512),
                    reader.tensor_info(up_name)["shape"][0], n_pyr, n_pyr,
                    transpose=is_c_fc, col_norm=post_norm,
                )
                if gate_name is not None:
                    gate_col = cls._stream_fold_matrix(
                        reader.iter_row_chunks(gate_name, chunk_rows=512),
                        reader.tensor_info(gate_name)["shape"][0], n_pyr, n_pyr,
                        col_norm=post_norm,
                    )
                    mid_col = up_col * (1.0 + 0.5 * np.tanh(gate_col))
                    del gate_col
                else:
                    mid_col = up_col
                down_col = cls._stream_fold_matrix(
                    reader.iter_row_chunks(down_name, chunk_rows=512),
                    reader.tensor_info(down_name)["shape"][0], n_pyr, n_pyr,
                    transpose=is_c_proj,
                )
                mlp_acc = (down_col @ mid_col) / np.float32(math.sqrt(n_pyr))
                del up_col, mid_col, down_col

            # Check for MoE routed experts (out-of-core expert-by-expert streaming)
            exp_prefix = f"model.layers.{L}.mlp.experts."
            exp_keys = reader.list_tensors(exp_prefix)
            if exp_keys:
                exp_ids = sorted({int(k[len(exp_prefix):].split(".")[0]) for k in exp_keys
                                  if k[len(exp_prefix):].split(".")[0].isdigit()})
                max_exp_sample = min(len(exp_ids), 16)
                exp_sum = np.zeros((n_pyr, n_pyr), dtype=np.float32)
                for eid in exp_ids[:max_exp_sample]:
                    eu = reader.find_first([f"{exp_prefix}{eid}.up_proj.weight", f"{exp_prefix}{eid}.w3.weight"])
                    eg = reader.find_first([f"{exp_prefix}{eid}.gate_proj.weight", f"{exp_prefix}{eid}.w1.weight"])
                    ed = reader.find_first([f"{exp_prefix}{eid}.down_proj.weight", f"{exp_prefix}{eid}.w2.weight"])
                    if eu and ed:
                        u_c = cls._stream_fold_matrix(
                            reader.iter_row_chunks(eu, chunk_rows=512),
                            reader.tensor_info(eu)["shape"][0], n_pyr, n_pyr, col_norm=post_norm
                        )
                        if eg:
                            g_c = cls._stream_fold_matrix(
                                reader.iter_row_chunks(eg, chunk_rows=512),
                                reader.tensor_info(eg)["shape"][0], n_pyr, n_pyr, col_norm=post_norm
                            )
                            u_c = u_c * (1.0 + 0.5 * np.tanh(g_c))
                            del g_c
                        d_c = cls._stream_fold_matrix(
                            reader.iter_row_chunks(ed, chunk_rows=512),
                            reader.tensor_info(ed)["shape"][0], n_pyr, n_pyr
                        )
                        exp_sum += (d_c @ u_c) / np.float32(math.sqrt(n_pyr))
                        del u_c, d_c
                if max_exp_sample > 0:
                    exp_sum /= np.float32(max_exp_sample)
                    mlp_acc = exp_sum if mlp_acc is None else (0.5 * mlp_acc + 0.5 * exp_sum)
                del exp_sum

            # GGUF stacked 3D MoE experts: blk.{L}.ffn_up_exps.weight [n_exp, d_ff, d_model]
            gguf_exp_u = reader.find_first([f"blk.{L}.ffn_up_exps.weight"])
            gguf_exp_d = reader.find_first([f"blk.{L}.ffn_down_exps.weight"])
            gguf_exp_g = reader.find_first([f"blk.{L}.ffn_gate_exps.weight"])
            if gguf_exp_u and gguf_exp_d:
                ui = reader.tensor_info(gguf_exp_u)["shape"]
                di = reader.tensor_info(gguf_exp_d)["shape"]
                if len(ui) == 3 and len(di) == 3:
                    n_exps, r_u, _ = ui
                    _, r_d, _ = di
                    n_sample = min(n_exps, 16)
                    exp_sum = np.zeros((n_pyr, n_pyr), dtype=np.float32)
                    for eid in range(n_sample):
                        u_c = cls._stream_fold_matrix(
                            reader.iter_row_chunks(gguf_exp_u, chunk_rows=512, row_range=(eid * r_u, (eid + 1) * r_u)),
                            r_u, n_pyr, n_pyr, col_norm=post_norm
                        )
                        if gguf_exp_g:
                            r_g = reader.tensor_info(gguf_exp_g)["shape"][1]
                            g_c = cls._stream_fold_matrix(
                                reader.iter_row_chunks(gguf_exp_g, chunk_rows=512, row_range=(eid * r_g, (eid + 1) * r_g)),
                                r_g, n_pyr, n_pyr, col_norm=post_norm
                            )
                            u_c = u_c * (1.0 + 0.5 * np.tanh(g_c))
                            del g_c
                        d_c = cls._stream_fold_matrix(
                            reader.iter_row_chunks(gguf_exp_d, chunk_rows=512, row_range=(eid * r_d, (eid + 1) * r_d)),
                            r_d, n_pyr, n_pyr
                        )
                        exp_sum += (d_c @ u_c) / np.float32(math.sqrt(n_pyr))
                        del u_c, d_c
                    exp_sum /= np.float32(n_sample)
                    mlp_acc = exp_sum if mlp_acc is None else (0.5 * mlp_acc + 0.5 * exp_sum)
                    del exp_sum

            if mlp_acc is not None:
                s_loc, d_loc, w_loc = cls._topk_from_folded_matrix(
                    mlp_acc, max(6, k_synapses // 2), target_rms=0.34
                )
                all_src.append(s_loc); all_dst.append(next_pyr_base + d_loc)
                all_w.append(w_loc); all_cmp.append(np.zeros(len(s_loc), dtype=np.uint8))
                del mlp_acc
            elif down_name is not None:
                tinfo = reader.tensor_info(down_name)
                s_loc, d_loc, w_loc = cls._extract_topk_edges_from_stream(
                    reader.iter_row_chunks(down_name, chunk_rows=512),
                    total_rows=tinfo["shape"][0],
                    src_dim_target=n_pyr, dst_dim_target=n_pyr,
                    k_per_src=max(6, k_synapses // 2), seed=seed + L * 23, target_rms=0.34,
                )
                all_src.append(s_loc); all_dst.append(next_pyr_base + d_loc)
                all_w.append(w_loc); all_cmp.append(np.zeros(len(s_loc), dtype=np.uint8))

            # Protected Residual Skip + White-Matter Long-Range Bundles
            skip_s = np.arange(n_pyr, dtype=np.int64)
            prot_src.append(skip_s); prot_dst.append(next_pyr_base + skip_s)
            prot_w.append(np.full(n_pyr, 0.72, dtype=np.float32))
            prot_cmp.append(np.zeros(n_pyr, dtype=np.uint8))

            if L + 4 < n_layers:
                jump_base = n_sensory + (L + 4) * per_layer
                wm_s = np.arange(0, n_pyr, 4, dtype=np.int64)
                prot_src.append(wm_s); prot_dst.append(jump_base + wm_s)
                prot_w.append(np.full(len(wm_s), 0.40, dtype=np.float32))
                prot_cmp.append(np.zeros(len(wm_s), dtype=np.uint8))

            if L >= max(0, n_layers - 2) and L < n_layers - 1:
                mot_s = np.arange(0, n_pyr, 2, dtype=np.int64)
                prot_src.append(mot_s); prot_dst.append(motor_base + mot_s)
                prot_w.append(np.full(len(mot_s), 0.45, dtype=np.float32))
                prot_cmp.append(np.zeros(len(mot_s), dtype=np.uint8))

            if not all_src:
                all_src = [np.arange(n_pyr, dtype=np.int64)]
                all_dst = [next_pyr_base + np.arange(n_pyr, dtype=np.int64)]
                all_w = [np.full(n_pyr, 0.30, dtype=np.float32)]
                all_cmp = [np.zeros(n_pyr, dtype=np.uint8)]

            cls._emit_dale_compliant_pool(
                storage, n_pyr, n_inh,
                (np.concatenate(all_src), np.concatenate(all_dst),
                 np.concatenate(all_w), np.concatenate(all_cmp)),
                scale_pre, neuron_sign, region_id, L + 1,
                pyr_base, prev_pyr_base, k_synapses, delay_max, rng,
                protected_edges=(np.concatenate(prot_src), np.concatenate(prot_dst),
                                 np.concatenate(prot_w), np.concatenate(prot_cmp)),
            )
            gc.collect()

        # 3. Motor / Readout Cortex
        last_pyr = motor_base - per_layer
        m_idx = np.arange(n_motor, dtype=np.int64)
        m_src = np.concatenate([m_idx, m_idx, m_idx])
        m_dst = np.concatenate([
            last_pyr + (m_idx % n_pyr),
            motor_base + ((m_idx + 1) % n_motor),
            motor_base + ((m_idx + 7) % n_motor),
        ])
        m_q8 = np.concatenate([
            np.full(n_motor, 45, dtype=np.int8),
            np.full(n_motor, 65, dtype=np.int8),
            np.full(n_motor, 45, dtype=np.int8),
        ])
        m_del = np.ones(len(m_src), dtype=np.uint8)
        m_cmp = np.concatenate([
            np.ones(n_motor, dtype=np.uint8),
            np.zeros(2 * n_motor, dtype=np.uint8),
        ])
        region_id[motor_base:] = n_layers + 1
        scale_pre[motor_base:] = 0.011
        storage.append_neuron_block(motor_base, n_motor, m_src, m_dst, m_q8, m_del, m_cmp)
        storage.finalize()

        brain = BiologicalBrain(
            total_neurons, storage, neuron_sign, scale_pre, region_id,
            sensory_slice=(0, n_sensory),
            motor_slice=(motor_base, motor_base + n_motor),
            vocab_data=vocab_data, delay_max=delay_max, n_layers=n_layers,
            source_model_path=source_model_path,
        )
        if out_dir is not None and use_memmap:
            brain.save(out_dir)

        log(f"[Converter] Done in {time.time() - t0:.2f}s | Neurons={total_neurons:,} | "
            f"Synapses={storage.nnz:,} | RAM={storage.ram_bytes()/1e6:.2f} MB | "
            f"Disk={storage.disk_bytes()/1e6:.2f} MB")
        return brain

    @staticmethod
    def load_hf_tokenizer_meta(model_dir, cfg):
        tok_path = os.path.join(model_dir, "tokenizer.json")
        if not os.path.exists(tok_path):
            return None
        with open(tok_path, "r", encoding="utf-8") as fh:
            tj = json.load(fh)
        model_sec = tj.get("model", {})
        raw_vocab = model_sec.get("vocab")
        scores = None
        if isinstance(raw_vocab, dict):
            vocab_map = dict(raw_vocab)
        elif isinstance(raw_vocab, list):
            vocab_map = {}
            scores = []
            for idx, entry in enumerate(raw_vocab):
                if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    vocab_map[str(entry[0])] = idx
                    scores.append(float(entry[1]))
                else:
                    vocab_map[str(entry)] = idx
                    scores.append(0.0)
        else:
            return None

        special_tokens = []
        for t in tj.get("added_tokens", []):
            if isinstance(t, dict) and "content" in t and "id" in t:
                vocab_map[t["content"]] = int(t["id"])
                special_tokens.append(t["content"])

        def _walk_nodes(node):
            if isinstance(node, dict):
                yield node
                for k in ("normalizers", "pretokenizers", "decoders"):
                    if isinstance(node.get(k), list):
                        for ch in node[k]:
                            yield from _walk_nodes(ch)
            elif isinstance(node, list):
                for ch in node:
                    yield from _walk_nodes(ch)

        pre_sec = tj.get("pre_tokenizer") or {}
        dec_sec = tj.get("decoder") or {}
        norm_sec = tj.get("normalizer") or {}
        pre_nodes = list(_walk_nodes(pre_sec))
        dec_nodes = list(_walk_nodes(dec_sec))
        norm_nodes = list(_walk_nodes(norm_sec))

        byte_level = any(n.get("type") == "ByteLevel" for n in pre_nodes + dec_nodes)
        byte_level_prefix_space = any(
            n.get("type") == "ByteLevel" and bool(n.get("add_prefix_space", False))
            for n in pre_nodes
        )
        has_split_pre = any(n.get("type") == "Split" for n in pre_nodes)
        gpt2_pre = byte_level and (not has_split_pre) and any(
            n.get("type") == "ByteLevel" and bool(n.get("use_regex", True))
            for n in pre_nodes
        )

        add_dummy = False
        for n in norm_nodes:
            if n.get("type") == "Prepend" and n.get("prepend") == "▁":
                add_dummy = True
        for n in pre_nodes:
            if n.get("type") == "Metaspace":
                ps = n.get("prepend_scheme")
                aps = n.get("add_prefix_space")
                if ps in ("always", "first") or (ps is None and aps is not False):
                    add_dummy = True

        norm_type = None
        for n in norm_nodes:
            if n.get("type") in ("NFC", "NFKC", "NFD", "NFKD"):
                norm_type = n.get("type")
                break

        tc_path0 = os.path.join(model_dir, "tokenizer_config.json")
        tc0 = {}
        if os.path.exists(tc_path0):
            try:
                with open(tc_path0, "r", encoding="utf-8") as fh:
                    tc0 = json.load(fh)
            except Exception:
                tc0 = {}
        if tc0.get("bos_token"):
            bt0 = tc0["bos_token"]
            b0_str = bt0["content"] if isinstance(bt0, dict) else str(bt0)
            bos_id = vocab_map.get(b0_str)
            if bos_id is None:
                bos_id = cfg.get("bos_token_id")
        else:
            bos_id = cfg.get("bos_token_id")
        eos_raw = cfg.get("eos_token_id")
        eos_ids = []
        if isinstance(eos_raw, (list, tuple)):
            eos_ids.extend(int(x) for x in eos_raw)
        elif eos_raw is not None:
            eos_ids.append(int(eos_raw))

        gen_cfg_p = os.path.join(model_dir, "generation_config.json")
        if os.path.exists(gen_cfg_p):
            try:
                with open(gen_cfg_p, "r", encoding="utf-8") as fh:
                    gc_json = json.load(fh)
                gc_eos = gc_json.get("eos_token_id")
                if isinstance(gc_eos, (list, tuple)):
                    for x in gc_eos:
                        if int(x) not in eos_ids:
                            eos_ids.append(int(x))
                elif gc_eos is not None and int(gc_eos) not in eos_ids:
                    eos_ids.append(int(gc_eos))
            except Exception:
                pass

        add_bos = None
        tc_path = os.path.join(model_dir, "tokenizer_config.json")
        if os.path.exists(tc_path):
            with open(tc_path, "r", encoding="utf-8") as fh:
                tc = json.load(fh)
            if "add_bos_token" in tc:
                add_bos = bool(tc["add_bos_token"])
            if bos_id is None and tc.get("bos_token"):
                bt = tc["bos_token"]
                b_str = bt["content"] if isinstance(bt, dict) else str(bt)
                bos_id = vocab_map.get(b_str)
            if not eos_ids and tc.get("eos_token"):
                et = tc["eos_token"]
                e_str = et["content"] if isinstance(et, dict) else str(et)
                if e_str in vocab_map:
                    eos_ids.append(int(vocab_map[e_str]))
            if add_bos is None and ("bos_token" in tc) and (tc["bos_token"] is None):
                add_bos = False
        if add_bos is None:
            pp_str = json.dumps(tj.get("post_processor") or {})
            bos_tok_str = str(vocab_map.get(bos_id, "")) if bos_id is not None else ""
            if bos_id is not None and (
                (bos_tok_str and bos_tok_str in pp_str)
                or any(k for k, v in vocab_map.items() if v == bos_id and k in pp_str)
            ):
                add_bos = True
            else:
                add_bos = (bos_id is not None) and (not byte_level or cfg.get("model_type") in ("llama",))

        eos_id = eos_ids if len(eos_ids) > 1 else (eos_ids[0] if eos_ids else None)
        pre_type = "gpt2" if gpt2_pre else cfg.get("model_type")
        return {
            "vocab": vocab_map,
            "merges": model_sec.get("merges", []),
            "scores": scores,
            "special_tokens": special_tokens,
            "byte_level": byte_level,
            "byte_level_prefix_space": byte_level_prefix_space,
            "norm_type": norm_type,
            "pre_type": pre_type,
            "add_bos": bool(add_bos),
            "add_dummy_prefix": bool(add_dummy),
            "bos_id": bos_id,
            "eos_id": eos_id,
        }

    @classmethod
    def convert_safetensors_dir(cls, model_dir, out_dir=None, col_neurons=256,
                                k_synapses=24, max_ram_mb=512, delay_max=6,
                                seed=7, log=print):
        cfg_path = os.path.join(model_dir, "config.json")
        with open(cfg_path, "r", encoding="utf-8") as fh:
            cfg = json.load(fh)
        reader = SafetensorsStreamReader(model_dir)
        tok_meta = cls.load_hf_tokenizer_meta(model_dir, cfg)
        return cls._convert_from_reader(
            reader, cfg, tok_meta, out_dir=out_dir, col_neurons=col_neurons,
            k_synapses=k_synapses, max_ram_mb=max_ram_mb, delay_max=delay_max, seed=seed, log=log,
            source_model_path=os.path.abspath(model_dir),
        )

    @classmethod
    def convert_gguf(cls, gguf_path, out_dir=None, col_neurons=256,
                     k_synapses=24, max_ram_mb=512, delay_max=6,
                     seed=7, log=print):
        reader = GGUFStreamReader(gguf_path)
        cfg = reader.arch_config()
        tok_meta = reader.tokenizer_data()
        log(f"[GGUF] Detected arch={cfg['arch']} layers={cfg['num_hidden_layers']} "
            f"d_model={cfg['hidden_size']} experts={cfg['num_local_experts']}")
        return cls._convert_from_reader(
            reader, cfg, tok_meta, out_dir=out_dir, col_neurons=col_neurons,
            k_synapses=k_synapses, max_ram_mb=max_ram_mb, delay_max=delay_max, seed=seed, log=log,
            source_model_path=os.path.abspath(gguf_path),
        )

    @classmethod
    def stream_virtual_frontier(cls, n_layers=126, d_model=16384, d_ff=53248,
                                col_neurons=512, k_synapses=24, out_dir=None,
                                max_chunk_rows=256, delay_max=6, seed=7, log=print):
        t0 = time.time()
        n_pyr = int(col_neurons)
        n_inh = max(16, n_pyr // 4)
        per_layer = n_pyr + n_inh
        n_sensory = n_pyr
        n_motor = n_pyr
        total_neurons = n_sensory + n_layers * per_layer + n_motor
        est_params = n_layers * (4 * d_model * d_model + 3 * d_model * d_ff)

        if out_dir is None:
            out_dir = tempfile.mkdtemp(prefix="apeiron_frontier_")
        storage = ConnectomeStorage(total_neurons, storage_dir=out_dir)
        neuron_sign = np.ones(total_neurons, dtype=np.int8)
        scale_pre = np.ones(total_neurons, dtype=np.float32) * 0.01
        region_id = np.zeros(total_neurons, dtype=np.int32)
        rng = np.random.default_rng(seed)

        s_src = np.arange(n_sensory, dtype=np.int64)
        s_dst = n_sensory + s_src
        s_w = np.full(n_sensory, 95, dtype=np.int8)
        s_del = np.ones(n_sensory, dtype=np.uint8)
        s_cmp = np.zeros(n_sensory, dtype=np.uint8)
        if n_layers >= 16:
            idx_q = np.arange(0, n_sensory, 4, dtype=np.int64)
            for jump_l in (n_layers // 4, n_layers // 2, (3 * n_layers) // 4):
                s_src = np.concatenate([s_src, idx_q])
                s_dst = np.concatenate([s_dst, n_sensory + jump_l * per_layer + idx_q])
                s_w = np.concatenate([s_w, np.full(len(idx_q), 60, dtype=np.int8)])
                s_del = np.concatenate([s_del, np.full(len(idx_q), 2, dtype=np.uint8)])
                s_cmp = np.concatenate([s_cmp, np.zeros(len(idx_q), dtype=np.uint8)])
        storage.append_neuron_block(0, n_sensory, s_src, s_dst, s_w, s_del, s_cmp)
        scale_pre[:n_sensory] = 0.022

        peak_chunk_mb = (max_chunk_rows * d_model * 4) / 1e6
        motor_base = n_sensory + n_layers * per_layer
        for L in range(n_layers):
            pyr_base = n_sensory + L * per_layer
            next_pyr_base = pyr_base + per_layer
            prev_pyr_base = (pyr_base - per_layer) if L > 0 else None

            def _virtual_chunks(seed_off):
                lrng = np.random.default_rng(seed_off)
                for r0 in range(0, 2 * max_chunk_rows, max_chunk_rows):
                    yield r0, lrng.standard_normal((max_chunk_rows, d_model), dtype=np.float32) * np.float32(0.02)

            s_loc, d_loc, w_loc = cls._extract_topk_edges_from_stream(
                _virtual_chunks(seed + L * 31),
                total_rows=2 * max_chunk_rows,
                src_dim_target=n_pyr, dst_dim_target=n_pyr,
                k_per_src=k_synapses, seed=seed + L, target_rms=0.34,
            )

            skip_s = np.arange(n_pyr, dtype=np.int64)
            prot_s = [skip_s]
            prot_d = [next_pyr_base + skip_s]
            prot_w = [np.full(n_pyr, 0.72, dtype=np.float32)]
            prot_c = [np.zeros(n_pyr, dtype=np.uint8)]

            if L + 8 < n_layers:
                wm_s = np.arange(0, n_pyr, 2, dtype=np.int64)
                prot_s.append(wm_s); prot_d.append(n_sensory + (L + 8) * per_layer + wm_s)
                prot_w.append(np.full(len(wm_s), 0.45, dtype=np.float32))
                prot_c.append(np.zeros(len(wm_s), dtype=np.uint8))
            if L > 0 and (L % max(n_layers // 8, 1) == 0):
                mot_s = np.arange(0, n_pyr, 4, dtype=np.int64)
                prot_s.append(mot_s); prot_d.append(motor_base + mot_s)
                prot_w.append(np.full(len(mot_s), 0.42, dtype=np.float32))
                prot_c.append(np.zeros(len(mot_s), dtype=np.uint8))

            cls._emit_dale_compliant_pool(
                storage, n_pyr, n_inh,
                (s_loc, next_pyr_base + d_loc, w_loc, np.zeros(len(s_loc), dtype=np.uint8)),
                scale_pre, neuron_sign, region_id, L + 1,
                pyr_base, prev_pyr_base, k_synapses, delay_max, rng,
                protected_edges=(np.concatenate(prot_s), np.concatenate(prot_d),
                                 np.concatenate(prot_w), np.concatenate(prot_c)),
            )

        last_pyr = motor_base - per_layer
        m_idx = np.arange(n_motor, dtype=np.int64)
        m_src = np.concatenate([m_idx, m_idx])
        m_dst = np.concatenate([last_pyr + m_idx, motor_base + ((m_idx + 1) % n_motor)])
        m_q8 = np.concatenate([np.full(n_motor, 45, dtype=np.int8), np.full(n_motor, 60, dtype=np.int8)])
        m_del = np.ones(len(m_src), dtype=np.uint8)
        m_cmp = np.concatenate([np.ones(n_motor, dtype=np.uint8), np.zeros(n_motor, dtype=np.uint8)])
        region_id[motor_base:] = n_layers + 1
        scale_pre[motor_base:] = 0.011
        storage.append_neuron_block(motor_base, n_motor, m_src, m_dst, m_q8, m_del, m_cmp)
        storage.finalize()

        brain = BiologicalBrain(
            total_neurons, storage, neuron_sign, scale_pre, region_id,
            sensory_slice=(0, n_sensory),
            motor_slice=(motor_base, motor_base + n_motor),
            delay_max=delay_max, n_layers=n_layers,
        )
        log(f"[Frontier Stream] Simulated {est_params/1e9:.1f}B-scale architecture ({n_layers}L x {d_model}d) "
            f"in {time.time() - t0:.2f}s | Peak chunk={peak_chunk_mb:.1f} MB | "
            f"Brain N={total_neurons:,}, Synapses={storage.nnz:,} | "
            f"Active RAM={storage.ram_bytes()/1e6:.2f} MB | Memmap Disk={storage.disk_bytes()/1e6:.2f} MB")
        return brain


# =====================================================================
# 5. Connectome & Biological Law Verifier (`BrainIntegrityKernel`)
# =====================================================================
class BrainIntegrityKernel:
    """Zero-trust structural, spectral, liveness, and biological verifier."""

    @classmethod
    def verify(cls, brain, max_ram_mb=1024, chunk_neurons=4096, check_liveness=False):
        checks = []
        N = brain.N
        st = brain.storage
        if N <= 0 or st.nnz <= 0:
            return False, {"reason": "Empty connectome", "checks": checks}

        if st.indptr[0] != 0 or st.indptr[-1] != st.nnz or np.any(np.diff(st.indptr) < 0):
            return False, {"reason": "Corrupt CSR indptr", "checks": checks}

        if not (np.all(np.isfinite(brain.scale_pre)) and np.all(np.isfinite(brain.theta))):
            return False, {"reason": "Non-finite neuron scale_pre or theta", "checks": checks}

        density = float(st.nnz) / float(N * N)
        if density >= 0.25:
            return False, {"reason": f"Connectome too dense ({density:.3f}); violates sparse wiring", "checks": checks}
        checks.append(f"sparse_density={density:.6f}")

        pos_mass = 0.0
        neg_mass = 0.0
        max_row_l1 = 0.0
        for u0 in range(0, N, chunk_neurons):
            u1 = min(N, u0 + chunk_neurons)
            e0 = int(st.indptr[u0])
            e1 = int(st.indptr[u1])
            if e1 <= e0:
                continue

            u_idx = np.repeat(np.arange(u0, u1, dtype=np.int64), np.diff(st.indptr[u0 : u1 + 1]))
            w_s = st.weights_q8[e0:e1]
            d_s = st.indices[e0:e1]
            dl_s = st.delays[e0:e1]
            cm_s = st.compartments[e0:e1]

            signs_exp = brain.neuron_sign[u_idx]
            if not (np.all((signs_exp > 0) == (w_s > 0)) and np.all(w_s != 0)):
                return False, {"reason": f"Dale's Law violation in neuron block [{u0}, {u1})", "checks": checks}

            if np.any(d_s >= N) or np.any(dl_s < 1) or np.any(dl_s >= brain.delay_max) or np.any(cm_s > 1):
                return False, {"reason": f"Out-of-bounds target/delay/compartment in [{u0}, {u1})", "checks": checks}

            w_real = w_s.astype(np.float32) * brain.scale_pre[u_idx]
            pos_mask = w_real > 0
            pos_mass += float(np.sum(w_real[pos_mask]))
            neg_mass += float(np.sum(-w_real[~pos_mask]))

            row_l1 = np.bincount(u_idx - u0, weights=np.abs(w_real), minlength=u1 - u0)
            max_row_l1 = max(max_row_l1, float(np.max(row_l1)))

        checks.append("dales_law_100pct")
        checks.append("csr_delays_compartments_valid")

        e_frac = float(np.mean(brain.neuron_sign > 0))
        if e_frac <= 0.50 or e_frac >= 0.98:
            return False, {"reason": f"Unbalanced E/I population ratio ({e_frac:.2f})", "checks": checks}
        ei_mass_ratio = pos_mass / max(neg_mass, 1e-6)
        if ei_mass_ratio < 0.8 or ei_mass_ratio > 15.0:
            return False, {"reason": f"Extreme E/I synaptic mass imbalance ({ei_mass_ratio:.2f})", "checks": checks}
        checks.append(f"ei_pop={e_frac:.2f}")
        checks.append(f"ei_mass_ratio={ei_mass_ratio:.2f}")

        v = np.ones(N, dtype=np.float32) / math.sqrt(N)
        rho_est = 0.0
        for _ in range(12):
            y = np.zeros(N, dtype=np.float32)
            for u0 in range(0, N, chunk_neurons):
                u1 = min(N, u0 + chunk_neurons)
                e0, e1 = int(st.indptr[u0]), int(st.indptr[u1])
                if e1 <= e0:
                    continue
                u_idx = np.repeat(np.arange(u0, u1, dtype=np.int64), np.diff(st.indptr[u0 : u1 + 1]))
                contrib = st.weights_q8[e0:e1].astype(np.float32) * brain.scale_pre[u_idx] * v[u_idx]
                np.add.at(y, st.indices[e0:e1].astype(np.int64), contrib)
            nrm = float(np.linalg.norm(y))
            if not math.isfinite(nrm):
                return False, {"reason": "Non-finite spectral norm", "checks": checks}
            if nrm < 1e-12:
                rho_est = 0.0
                break
            rho_est = nrm
            v = y / nrm
        if rho_est > 50.0:
            return False, {"reason": f"Explosive spectral norm ({rho_est:.2f})", "checks": checks}
        checks.append(f"spectral_rho={rho_est:.3f}")
        checks.append(f"max_l1={max_row_l1:.2f}")

        ram_mb = st.ram_bytes() / 1e6
        if ram_mb > max_ram_mb:
            return False, {"reason": f"RAM {ram_mb:.1f} MB exceeds 2014 budget {max_ram_mb} MB", "checks": checks}
        checks.append(f"ram_mb={ram_mb:.2f}")

        if check_liveness:
            s0, s1 = brain.sensory_slice
            n_sens = s1 - s0
            stim = np.zeros(n_sens, dtype=np.float32)
            stim[: max(8, n_sens // 8)] = 1.40
            saved_tick = brain.tick
            brain.reset_state()
            mot, _ = brain.think(stim, n_ticks=min(max(brain.n_layers + 4, 8), 16), plasticity=False)
            mot_norm = float(np.linalg.norm(mot))
            brain.reset_state()
            brain.tick = saved_tick
            if mot_norm < 0.05:
                return False, {"reason": f"Signal collapse: motor_norm={mot_norm:.4f}", "checks": checks}
            checks.append(f"liveness_motor_norm={mot_norm:.2f}")

        return True, {"reason": "All biological, spectral & 2014-CPU constraints verified", "checks": checks}


# =====================================================================
# 6. Pure-Python Subword Tokenizer + Language Bridges (Byte & Frontier)
# =====================================================================
def _bytes_to_unicode():
    bs = list(range(ord("!"), ord("~") + 1)) + list(range(ord("¡"), ord("¬") + 1)) + list(range(ord("®"), ord("ÿ") + 1))
    cs = bs[:]
    n = 0
    for b in range(256):
        if b not in bs:
            bs.append(b)
            cs.append(256 + n)
            n += 1
    return dict(zip(bs, [chr(c) for c in cs]))


_BYTE_ENCODER = _bytes_to_unicode()
_BYTE_DECODER = {v: k for k, v in _BYTE_ENCODER.items()}


def _is_letter(ch):
    return unicodedata.category(ch).startswith("L")


def _is_number(ch):
    return unicodedata.category(ch).startswith("N")


def _pretokenize_byte_level(text, gpt2_style=False):
    """Pure-Python GPT-2 / Llama-3 / Qwen2 Unicode pre-tokenizer."""
    out = []
    n = len(text)
    i = 0
    contractions = ("'s", "'t", "'re", "'ve", "'m", "'ll", "'d")
    while i < n:
        if text[i] == "'":
            low = text[i : i + 3].lower()
            matched_c = None
            for c in contractions:
                if (gpt2_style and text[i : i + len(c)] == c) or (not gpt2_style and low.startswith(c)):
                    matched_c = c
                    break
            if matched_c is not None:
                out.append(text[i : i + len(matched_c)])
                i += len(matched_c)
                continue

        ch = text[i]
        if _is_letter(ch):
            j = i + 1
            while j < n and _is_letter(text[j]):
                j += 1
            out.append(text[i:j])
            i = j
            continue
        if gpt2_style:
            if ch == " " and i + 1 < n and _is_letter(text[i + 1]):
                j = i + 2
                while j < n and _is_letter(text[j]):
                    j += 1
                out.append(text[i:j])
                i = j
                continue
            if _is_number(ch) or (ch == " " and i + 1 < n and _is_number(text[i + 1])):
                j = i + 1
                while j < n and _is_number(text[j]):
                    j += 1
                out.append(text[i:j])
                i = j
                continue
        else:
            if ch not in ("\r", "\n") and not _is_number(ch) and (i + 1 < n and _is_letter(text[i + 1])):
                j = i + 2
                while j < n and _is_letter(text[j]):
                    j += 1
                out.append(text[i:j])
                i = j
                continue
            if _is_number(ch):
                j = i + 1
                while j < n and (j - i) < 3 and _is_number(text[j]):
                    j += 1
                out.append(text[i:j])
                i = j
                continue

        if (ch == " " and i + 1 < n and not text[i + 1].isspace()
                and not _is_letter(text[i + 1]) and not _is_number(text[i + 1])) or (
            not ch.isspace() and not _is_letter(ch) and not _is_number(ch)
        ):
            j = i + (1 if ch == " " else 0)
            while j < n and not text[j].isspace() and not _is_letter(text[j]) and not _is_number(text[j]):
                j += 1
            if not gpt2_style:
                while j < n and text[j] in ("\r", "\n"):
                    j += 1
            out.append(text[i:j])
            i = j
            continue

        if ch.isspace():
            j = i
            last_nl = -1
            while j < n and text[j].isspace():
                if not gpt2_style and text[j] in ("\r", "\n"):
                    last_nl = j
                j += 1
            if last_nl != -1:
                out.append(text[i : last_nl + 1])
                i = last_nl + 1
            elif j < n and (j - i) > 1:
                out.append(text[i : j - 1])
                i = j - 1
            else:
                out.append(text[i:j])
                i = j
            continue

        out.append(ch)
        i += 1
    return out


class SubwordTokenizer:
    """Pure-Python BPE / SentencePiece BPE & Unigram / ByteLevel tokenizer for HF & GGUF."""

    def __init__(self, vocab, merges=None, byte_level=False, bos_id=None, eos_id=None,
                 scores=None, special_tokens=None, add_bos=None, add_dummy_prefix=None,
                 pre_type=None, norm_type=None, byte_level_prefix_space=False):
        self.tok_to_id = {str(k): int(v) for k, v in vocab.items()}
        self.id_to_tok = {int(v): str(k) for k, v in self.tok_to_id.items()}
        self.byte_level = bool(byte_level)
        self.byte_level_prefix_space = bool(byte_level_prefix_space)
        self.norm_type = norm_type
        self.bos_id = int(bos_id) if bos_id is not None else None
        if isinstance(eos_id, (list, tuple, set)):
            self.eos_ids = {int(x) for x in eos_id}
            self.eos_id = int(eos_id[0]) if eos_id else None
        elif eos_id is not None:
            self.eos_ids = {int(eos_id)}
            self.eos_id = int(eos_id)
        else:
            self.eos_ids = set()
            self.eos_id = None

        self.scores = list(scores) if scores is not None else None
        self.pre_type = pre_type
        self.gpt2_style = str(pre_type or "").lower() in ("gpt2", "gpt-2", "roberta")
        self.bpe_ranks = {}
        if merges:
            for rank, item in enumerate(merges):
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    self.bpe_ranks[(item[0], item[1])] = rank
                elif isinstance(item, str) and " " in item:
                    parts = item.split(" ", 1)
                    self.bpe_ranks[(parts[0], parts[1])] = rank

        self.has_sp_space = any(k.startswith("▁") for k in self.tok_to_id)
        self.has_bpe_space = any(k.startswith("Ġ") for k in self.tok_to_id)
        self.has_byte_fallback = "<0x0A>" in self.tok_to_id
        if self.has_bpe_space and not self.bpe_ranks and not self.has_sp_space:
            self.byte_level = True
        self.add_bos = bool(add_bos) if add_bos is not None else (self.bos_id is not None)
        self.add_dummy_prefix = bool(add_dummy_prefix) if add_dummy_prefix is not None else self.has_sp_space
        self._max_tok_len = min(64, max((len(k) for k in self.tok_to_id), default=1))

        # Compile atomic regex for special / added tokens
        st_set = {str(t) for t in (special_tokens or []) if t and str(t) in self.tok_to_id}
        if self.bos_id is not None and self.bos_id in self.id_to_tok:
            st_set.add(self.id_to_tok[self.bos_id])
        for eid in self.eos_ids:
            if eid in self.id_to_tok:
                st_set.add(self.id_to_tok[eid])
        st_list = sorted(st_set, key=len, reverse=True)
        self.special_set = set(st_list)
        self._special_re = re.compile("(" + "|".join(re.escape(t) for t in st_list) + ")") if st_list else None
        self._bpe_cache = {}
        self._byte_tok_re = re.compile(r"^<0x([0-9A-Fa-f]{2})>$")

    def _bpe(self, word_chars):
        key = tuple(word_chars)
        if key in self._bpe_cache:
            return self._bpe_cache[key]
        word = key
        if len(word) <= 1:
            return word
        while len(word) > 1:
            best_pair = None
            best_rank = 10**12
            for i in range(len(word) - 1):
                pair = (word[i], word[i + 1])
                r = self.bpe_ranks.get(pair)
                if r is not None and r < best_rank:
                    best_rank = r
                    best_pair = pair
            if best_pair is None:
                break
            a, b = best_pair
            new_word = []
            i = 0
            while i < len(word):
                if i < len(word) - 1 and word[i] == a and word[i + 1] == b:
                    new_word.append(a + b)
                    i += 2
                else:
                    new_word.append(word[i])
                    i += 1
            word = tuple(new_word)
        if len(self._bpe_cache) < 32768:
            self._bpe_cache[key] = word
        return word

    def _bpe_by_score(self, symbols):
        word = list(symbols)
        while len(word) > 1:
            best_i = -1
            best_sc = -1e18
            for i in range(len(word) - 1):
                merged = word[i] + word[i + 1]
                tid = self.tok_to_id.get(merged)
                if tid is not None:
                    sc = float(self.scores[tid]) if tid < len(self.scores) else 0.0
                    if sc > best_sc:
                        best_sc = sc
                        best_i = i
            if best_i < 0:
                break
            a, b = word[best_i], word[best_i + 1]
            ab = a + b
            new_word = []
            i = 0
            while i < len(word):
                if i < len(word) - 1 and word[i] == a and word[i + 1] == b:
                    new_word.append(ab)
                    i += 2
                else:
                    new_word.append(word[i])
                    i += 1
            word = new_word
        return tuple(word)

    def _encode_byte_fallback(self, ch):
        out = []
        for b in ch.encode("utf-8"):
            btok = f"<0x{b:02X}>"
            if btok in self.tok_to_id:
                out.append(self.tok_to_id[btok])
            elif "<unk>" in self.tok_to_id:
                out.append(self.tok_to_id["<unk>"])
            else:
                out.append(0)
        return out

    def _to_sp_symbols(self, norm):
        syms = []
        for ch in norm:
            if ch in self.tok_to_id or not self.has_byte_fallback:
                syms.append(ch)
            else:
                for b in ch.encode("utf-8"):
                    syms.append(f"<0x{b:02X}>")
        return syms

    def _encode_unigram_viterbi(self, norm):
        n = len(norm)
        dp = [-1e18] * (n + 1)
        back = [None] * (n + 1)
        dp[0] = 0.0
        for i in range(n):
            if dp[i] <= -1e17:
                continue
            max_l = min(self._max_tok_len, n - i)
            matched = False
            for L in range(1, max_l + 1):
                sub = norm[i : i + L]
                tid = self.tok_to_id.get(sub)
                if tid is not None:
                    sc = float(self.scores[tid]) if (self.scores and tid < len(self.scores)) else -float(L)
                    cand = dp[i] + sc
                    if cand > dp[i + L]:
                        dp[i + L] = cand
                        back[i + L] = (i, [tid])
                    matched = True
            if not matched or back[i + 1] is None:
                fb_ids = self._encode_byte_fallback(norm[i])
                cand = dp[i] - 20.0 * len(fb_ids)
                if cand > dp[i + 1]:
                    dp[i + 1] = cand
                    back[i + 1] = (i, fb_ids)
        res = []
        cur = n
        while cur > 0:
            prev, tids = back[cur]
            res.extend(reversed(tids))
            cur = prev
        res.reverse()
        return res

    def _encode_segment(self, text):
        if not text:
            return []
        if self.norm_type in ("NFC", "NFKC", "NFD", "NFKD"):
            text = unicodedata.normalize(self.norm_type, text)
        ids = []
        if self.bpe_ranks:
            if self.byte_level:
                if self.byte_level_prefix_space and not text.startswith(" "):
                    text = " " + text
                pieces = _pretokenize_byte_level(text, gpt2_style=self.gpt2_style)
                for p in pieces:
                    bpe_str = "".join(_BYTE_ENCODER[b] for b in p.encode("utf-8"))
                    for tok in self._bpe(list(bpe_str)):
                        if tok in self.tok_to_id:
                            ids.append(self.tok_to_id[tok])
                        else:
                            for ch in tok:
                                ids.append(self.tok_to_id.get(ch, 0))
                return ids

            if self.has_sp_space:
                norm = text.replace(" ", "▁")
                if self.add_dummy_prefix and not norm.startswith("▁"):
                    norm = "▁" + norm
            else:
                norm = text
            for tok in self._bpe(self._to_sp_symbols(norm)):
                if tok in self.tok_to_id:
                    ids.append(self.tok_to_id[tok])
                else:
                    for ch in tok:
                        if ch in self.tok_to_id:
                            ids.append(self.tok_to_id[ch])
                        else:
                            ids.extend(self._encode_byte_fallback(ch))
            return ids

        if self.byte_level:
            norm = "".join(_BYTE_ENCODER[b] for b in text.encode("utf-8"))
        elif self.has_sp_space:
            norm = text.replace(" ", "▁")
            if self.add_dummy_prefix and not norm.startswith("▁"):
                norm = "▁" + norm
        else:
            norm = text

        if self.scores is not None and len(self.scores) >= len(self.tok_to_id):
            if self.has_sp_space and str(self.pre_type or "").lower() not in ("t5", "unigram"):
                for tok in self._bpe_by_score(self._to_sp_symbols(norm)):
                    if tok in self.tok_to_id:
                        ids.append(self.tok_to_id[tok])
                    else:
                        ids.extend(self._encode_byte_fallback(tok))
                return ids
            return self._encode_unigram_viterbi(norm)

        i = 0
        while i < len(norm):
            matched = None
            for L in range(min(self._max_tok_len, len(norm) - i), 0, -1):
                sub = norm[i : i + L]
                if sub in self.tok_to_id:
                    matched = self.tok_to_id[sub]
                    i += L
                    break
            if matched is None:
                if norm[i] in self.tok_to_id:
                    ids.append(int(self.tok_to_id[norm[i]]))
                else:
                    ids.extend(self._encode_byte_fallback(norm[i]))
                i += 1
            else:
                ids.append(int(matched))
        return ids

    def encode(self, text, add_bos=None):
        if add_bos is None:
            add_bos = self.add_bos
        ids = []
        if add_bos and self.bos_id is not None:
            bos_tok = self.id_to_tok.get(self.bos_id)
            if not (bos_tok and text and text.startswith(bos_tok)):
                ids.append(int(self.bos_id))
        if not text:
            return ids
        if self._special_re is not None:
            parts = self._special_re.split(text)
            for part in parts:
                if not part:
                    continue
                if part in self.special_set:
                    ids.append(self.tok_to_id[part])
                else:
                    ids.extend(self._encode_segment(part))
            return ids
        ids.extend(self._encode_segment(text))
        return ids

    def decode(self, ids, skip_special_tokens=False):
        id_list = [int(x) for x in ids]
        if self.byte_level:
            b = bytearray()
            for idx, tid_i in enumerate(id_list):
                if self.bos_id is not None and tid_i == int(self.bos_id) and (idx == 0 or skip_special_tokens):
                    continue
                t = self.id_to_tok.get(tid_i, "")
                if skip_special_tokens and (t in self.special_set or tid_i in self.eos_ids):
                    continue
                if t in self.special_set:
                    b.extend(t.encode("utf-8"))
                    continue
                for ch in t:
                    if ch in _BYTE_DECODER:
                        b.append(_BYTE_DECODER[ch])
                    else:
                        b.extend(ch.encode("utf-8"))
            return b.decode("utf-8", errors="replace")

        b_buf = bytearray()
        for idx, tid_i in enumerate(id_list):
            if self.bos_id is not None and tid_i == int(self.bos_id) and (idx == 0 or skip_special_tokens):
                continue
            t = self.id_to_tok.get(tid_i, "")
            if skip_special_tokens and (t in self.special_set or tid_i in self.eos_ids):
                continue
            m = self._byte_tok_re.match(t)
            if m:
                b_buf.append(int(m.group(1), 16))
            else:
                b_buf.extend(t.replace("▁", " ").replace("Ġ", " ").encode("utf-8"))
        out = b_buf.decode("utf-8", errors="replace")
        if self.has_sp_space and self.add_dummy_prefix and out.startswith(" "):
            out = out[1:]
        return out

class CorticalLanguageBridge:
    """Byte-level Sparse Distributed Representation bridge with working-memory + AdamW."""

    def __init__(self, brain, seed=7):
        self.brain = brain
        s0, s1 = brain.sensory_slice
        m0, m1 = brain.motor_slice
        self.n_sens = s1 - s0
        self.n_mot = m1 - m0
        rng = np.random.default_rng(seed)
        self.byte_to_sdr = np.zeros((256, self.n_sens), dtype=np.float32)
        k_on = max(12, self.n_sens // 8)
        for b in range(256):
            idx = rng.choice(self.n_sens, size=k_on, replace=False)
            self.byte_to_sdr[b, idx] = 1.40

        self.feat_dim = 2 * self.n_mot
        self.readout = np.zeros((256, self.feat_dim), dtype=np.float32)
        self.bias = np.zeros(256, dtype=np.float32)
        self.ctx_trace = np.zeros(self.n_mot, dtype=np.float32)

        self._m_w = np.zeros_like(self.readout)
        self._v_w = np.zeros_like(self.readout)
        self._m_b = np.zeros_like(self.bias)
        self._v_b = np.zeros_like(self.bias)
        self._adam_t = 0

    def reset_context(self):
        self.brain.reset_state()
        self.ctx_trace.fill(0.0)

    def _step_token(self, byte_val, ticks_per_token=6, reward_signal=0.0, plasticity=False):
        m0, m1 = self.brain.motor_slice
        mot_acc = np.zeros(self.n_mot, dtype=np.float32)
        stim = self.byte_to_sdr[byte_val]
        for t in range(ticks_per_token):
            self.brain.step(
                sensory_current=(stim if t < 2 else None),
                reward_signal=reward_signal,
                plasticity=plasticity,
            )
            mot_acc += np.maximum(self.brain.v_basal[m0:m1] + 0.5 * self.brain.v_apical[m0:m1], 0.0)
            if len(self.brain.last_spikes) > 0:
                m_sp = self.brain.last_spikes[(self.brain.last_spikes >= m0) & (self.brain.last_spikes < m1)] - m0
                if len(m_sp) > 0:
                    mot_acc[m_sp] += 1.6
        mot_now = mot_acc / max(ticks_per_token, 1)
        echo = stim[:self.n_mot] if self.n_sens >= self.n_mot else np.pad(stim, (0, self.n_mot - self.n_sens))
        self.ctx_trace = 0.72 * self.ctx_trace + 0.28 * mot_now + 0.18 * echo
        feat = np.concatenate([mot_now, self.ctx_trace])
        nrm = float(np.linalg.norm(feat))
        return (feat / nrm) if nrm > 1e-6 else feat

    def train_sequence(self, text, lr=0.025, ticks_per_token=None, epochs=1, stdp_epochs=2):
        if ticks_per_token is None:
            ticks_per_token = min(max(self.brain.n_layers + 2, 6), 10)
        data = text.encode("utf-8", errors="ignore")
        losses = []
        beta1, beta2, eps, wd = 0.9, 0.999, 1e-6, 1e-4

        for ep in range(epochs):
            self.reset_context()
            ep_loss = 0.0
            lr_ep = lr * (0.96 ** ep)
            use_stdp = ep < min(stdp_epochs, max(1, epochs // 3)) if epochs > 1 else (stdp_epochs > 0)
            for i in range(len(data) - 1):
                b_in, b_tgt = data[i], data[i + 1]
                feat = self._step_token(
                    b_in, ticks_per_token=ticks_per_token,
                    reward_signal=0.25 if use_stdp else 0.0, plasticity=use_stdp,
                )
                logits = self.readout @ feat + self.bias
                probs = np.exp(logits - logits.max())
                probs /= probs.sum()
                ep_loss += -math.log(max(float(probs[b_tgt]), 1e-9))

                grad_logits = probs
                grad_logits[b_tgt] -= 1.0
                g_w = np.outer(grad_logits, feat) + wd * self.readout
                g_b = grad_logits

                self._adam_t += 1
                self._m_w = beta1 * self._m_w + (1.0 - beta1) * g_w
                self._v_w = beta2 * self._v_w + (1.0 - beta2) * (g_w * g_w)
                self._m_b = beta1 * self._m_b + (1.0 - beta1) * g_b
                self._v_b = beta2 * self._v_b + (1.0 - beta2) * (g_b * g_b)

                bc1 = 1.0 - (beta1 ** self._adam_t)
                bc2 = 1.0 - (beta2 ** self._adam_t)
                self.readout -= lr_ep * (self._m_w / bc1) / (np.sqrt(self._v_w / bc2) + eps)
                self.bias -= lr_ep * (self._m_b / bc1) / (np.sqrt(self._v_b / bc2) + eps)

            losses.append(ep_loss / max(len(data) - 1, 1))
        return losses

    def generate(self, prompt, max_bytes=48, ticks_per_token=None, temperature=0.0, top_k=8, seed=7):
        if ticks_per_token is None:
            ticks_per_token = min(max(self.brain.n_layers + 2, 6), 10)
        data = prompt.encode("utf-8", errors="ignore")
        self.reset_context()
        feat = np.zeros(self.feat_dim, dtype=np.float32)
        for b in data:
            feat = self._step_token(b, ticks_per_token=ticks_per_token, plasticity=False)
        out = bytearray(data)
        rng = np.random.default_rng(seed)
        for _ in range(max_bytes):
            logits = self.readout @ feat + self.bias
            if temperature <= 1e-4:
                nxt = int(np.argmax(logits))
            else:
                scaled = logits / float(temperature)
                if 0 < top_k < len(scaled):
                    top_idx = np.argpartition(scaled, -top_k)[-top_k:]
                    sub = np.exp(scaled[top_idx] - scaled[top_idx].max())
                    sub /= sub.sum()
                    nxt = int(rng.choice(top_idx, p=sub))
                else:
                    probs = np.exp(scaled - scaled.max())
                    probs /= probs.sum()
                    nxt = int(rng.choice(len(probs), p=probs))
            out.append(nxt)
            feat = self._step_token(nxt, ticks_per_token=ticks_per_token, plasticity=False)
        return out.decode("utf-8", errors="replace")

    def save(self, out_dir):
        b_dir = os.path.join(out_dir, "bridge")
        os.makedirs(b_dir, exist_ok=True)
        np.save(os.path.join(b_dir, "byte_to_sdr.npy"), self.byte_to_sdr)
        np.save(os.path.join(b_dir, "readout.npy"), self.readout)
        np.save(os.path.join(b_dir, "bias.npy"), self.bias)
        np.save(os.path.join(b_dir, "adam_mw.npy"), self._m_w)
        np.save(os.path.join(b_dir, "adam_vw.npy"), self._v_w)
        np.save(os.path.join(b_dir, "adam_mb.npy"), self._m_b)
        np.save(os.path.join(b_dir, "adam_vb.npy"), self._v_b)
        with open(os.path.join(b_dir, "bridge_meta.json"), "w", encoding="utf-8") as fh:
            json.dump({"adam_t": self._adam_t, "feat_dim": self.feat_dim}, fh)

    @classmethod
    def load_or_create(cls, brain, brain_dir):
        b_dir = os.path.join(brain_dir, "bridge")
        obj = cls(brain)
        if os.path.isdir(b_dir):
            r_loaded = np.load(os.path.join(b_dir, "readout.npy"))
            if r_loaded.shape == obj.readout.shape:
                obj.byte_to_sdr = np.load(os.path.join(b_dir, "byte_to_sdr.npy"))
                obj.readout = r_loaded
                obj.bias = np.load(os.path.join(b_dir, "bias.npy"))
                for attr, fn in (("_m_w", "adam_mw.npy"), ("_v_w", "adam_vw.npy"),
                                 ("_m_b", "adam_mb.npy"), ("_v_b", "adam_vb.npy")):
                    p = os.path.join(b_dir, fn)
                    if os.path.exists(p):
                        setattr(obj, attr, np.load(p))
                meta_p = os.path.join(b_dir, "bridge_meta.json")
                if os.path.exists(meta_p):
                    with open(meta_p, "r", encoding="utf-8") as fh:
                        obj._adam_t = int(json.load(fh).get("adam_t", 0))
        return obj


class CorpusNGram:
    """Token-level n-gram LM with stupid backoff, trained on the model's own tokenizer.
    Gives the brain's vocab bridge genuine local language statistics so generation
    reads as fluent text, while cortical drives still steer token selection."""

    BACKOFF = 0.4

    def __init__(self, order=4):
        self.order = max(1, int(order))
        self.counts = [dict() for _ in range(self.order)]
        self.totals = [dict() for _ in range(self.order)]
        self.n_tokens = 0
        self.n_ctx = 0

    def train_text(self, text, tokenizer):
        ids = tokenizer.encode(text, add_bos=True)
        return self.train_ids(ids)

    def train_ids(self, ids):
        n = len(ids)
        self.n_tokens += n
        for k in range(1, self.order + 1):
            ck = self.counts[k - 1]
            tk = self.totals[k - 1]
            new_ctx = 0
            for i in range(n - k + 1):
                hist = tuple(ids[i:i + k - 1])
                nxt = ids[i + k - 1]
                d = ck.get(hist)
                if d is None:
                    d = ck[hist] = {}
                    new_ctx += 1
                d[nxt] = d.get(nxt, 0) + 1
                tk[hist] = tk.get(hist, 0) + 1
            self.n_ctx += new_ctx
        return self

    def logprob_of(self, ctx_ids, w, floor=-20.0):
        alpha = 1.0
        for k in range(self.order, 1, -1):
            hist = tuple(ctx_ids[-(k - 1):]) if k > 1 else ()
            d = self.counts[k - 1].get(hist)
            if d:
                tot = self.totals[k - 1].get(hist, 0)
                if tot > 0:
                    c = d.get(w)
                    if c:
                        return math.log(alpha * c / tot)
            alpha *= self.BACKOFF
        uni = self.counts[0].get(())
        if uni:
            c = uni.get(w)
            if c:
                tot = self.totals[0].get((), 1)
                return math.log(max(self.BACKOFF ** (self.order - 1) * c / tot, 1e-12))
        return floor

    def logprobs(self, ctx_ids, vocab_size, floor=-20.0):
        out = np.full(vocab_size, floor, dtype=np.float32)
        uni = self.counts[0].get(())
        if uni:
            tot0 = max(self.totals[0].get((), 1), 1)
            base = self.BACKOFF ** (self.order - 1) / tot0
            for w, c in uni.items():
                out[w] = math.log(max(base * c, 1e-12))
        assigned = np.zeros(vocab_size, dtype=bool)
        alpha = 1.0
        for k in range(self.order, 1, -1):
            hist = tuple(ctx_ids[-(k - 1):]) if k > 1 else ()
            d = self.counts[k - 1].get(hist)
            if d:
                tot = self.totals[k - 1].get(hist, 0)
                if tot > 0:
                    inv = alpha / tot
                    for w, c in d.items():
                        if not assigned[w]:
                            out[w] = math.log(max(c * inv, 1e-12))
                            assigned[w] = True
            alpha *= self.BACKOFF
        return out

    def save(self, path):
        ser = {
            "order": self.order,
            "n_tokens": self.n_tokens,
            "counts": [
                {
                    ",".join(map(str, hist)) if hist else "":
                    {str(w): c for w, c in d.items()}
                    for hist, d in ck.items()
                }
                for ck in self.counts
            ],
        }
        with gzip.open(path, "wt", encoding="utf-8") as fh:
            json.dump(ser, fh, separators=(",", ":"))

    @classmethod
    def load(cls, path):
        with gzip.open(path, "rt", encoding="utf-8") as fh:
            ser = json.load(fh)
        obj = cls(ser["order"])
        obj.n_tokens = int(ser.get("n_tokens", 0))
        for k, ck_ser in enumerate(ser["counts"]):
            ck = obj.counts[k]
            tk = obj.totals[k]
            for hist_str, d_ser in ck_ser.items():
                hist = tuple(int(x) for x in hist_str.split(",")) if hist_str else ()
                d = ck[hist] = {int(w): int(c) for w, c in d_ser.items()}
                tk[hist] = sum(d.values())
            obj.n_ctx += len(ck)
        return obj


class LanguageQualitySolver:
    """Autonomous solver for the brain's language-quality issue, run under
    AutonomousProofEngine v2 discipline (strict non-settlement):

    DECLARED SYSTEM: find a token-selection distribution P(w | ctx) realizable by
    the brain's vocab bridge whose teacher-forced cross-entropy against a corpus
    is minimal.  The engine ENUMERATES the candidate family space itself,
    MEASURES exact residuals, PINS the free parameters on train data, ELIMINATES
    losing branches with recorded reasons, and CERTIFIES only what survives
    held-out verification.  No mechanism is hard-wired: the winning n-gram order
    and cortical mixture weight are discovered by measurement on every corpus.

    CANDIDATE FAMILY SPACE (autonomous enumeration):
      F1  untrained cortical readout          (fresh W_proj, measured pre-STDP)
      F2  trained cortical readout            (post STDP + ridge alignment)
      F3  pure corpus n-gram, order k         (k in `orders`)
      F4  mixture (1-lam)*P_ng(k) + lam*P_cortical   (lam in LAM_GRID, per k)

    EXACT RESIDUAL: teacher-forced cross-entropy (nats/token) -- deterministic
    function of the certified count tables / weights, no sampling anywhere.

    NON-SETTLEMENT: PROVEN_CLASSIFICATION requires an interior pinned optimum
    that strictly dominates every pure branch on HELD-OUT ids; otherwise the
    honest boundary tier is recorded with the winning pure branch.
    """

    LAM_GRID = tuple(round(0.05 * i, 2) for i in range(21))
    ORDERS = (2, 3, 4, 5, 6)

    def __init__(self, bridge):
        self.bridge = bridge

    def _cortical_pass(self, ids, max_positions):
        br = self.bridge
        br.reset_context()
        feat = np.zeros(br.feat_dim, dtype=np.float32)
        t0 = min(len(ids) - 1, int(max_positions) + 1)
        p_ct = np.empty(max(t0 - 1, 0), dtype=np.float64)
        for i in range(t0 - 1):
            feat = br._step_token(int(ids[i]), ticks_per_token=4, plasticity=False)
            h = br._project_to_head(feat)
            logits = br._compute_logits(h)
            mx = float(logits.max())
            ex = np.exp(logits - mx)
            p_ct[i] = max(float(ex[int(ids[i + 1])]) / max(float(ex.sum()), 1e-12), 1e-12)
        return p_ct

    @staticmethod
    def _ngram_pass(ngram, ids, n_pos):
        p_ng = np.empty(max(n_pos, 0), dtype=np.float64)
        for i in range(n_pos):
            ctx = ids[max(0, i + 1 - ngram.order):i + 1]
            p_ng[i] = max(math.exp(ngram.logprob_of(ctx, int(ids[i + 1]))), 1e-12)
        return p_ng

    @staticmethod
    def _ce(p_ng, p_ct, lam):
        mix = (1.0 - lam) * p_ng + lam * p_ct
        return float(-np.mean(np.log(np.maximum(mix, 1e-12))))

    def solve(self, ids_train, ids_meas, max_positions=800, orders=None,
              f1_ce=None):
        cert = {
            "problem": "brain vocab-bridge token selection reproducing corpus conditionals",
            "candidates": [],
            "eliminated": [],
            "gaps": [],
            "status": "INCOMPLETE",
            "pinned": None,
        }
        orders = tuple(orders) if orders else self.ORDERS
        if len(ids_train) < 64 or len(ids_meas) < 32:
            cert["gaps"].append({"tag": "corpus_too_small",
                                 "detail": "need >=64 train and >=32 measurement tokens"})
            return cert
        p_ct = self._cortical_pass(ids_meas, max_positions)
        half = max(1, len(p_ct) // 2)
        p_ct_pin, p_ct_ver = p_ct[:half], p_ct[half:]
        r2 = self._ce(np.zeros_like(p_ct_ver), p_ct_ver, 1.0)
        cert["candidates"].append({"family": "F2 cortical-only (trained)",
                                   "residual_ce": round(r2, 4), "verified": "held-out"})
        best = None
        r3_best = None
        for k in orders:
            ng = CorpusNGram(k).train_ids(list(ids_train))
            p_ng = self._ngram_pass(ng, ids_meas, len(p_ct))
            p_ng_pin, p_ng_ver = p_ng[:half], p_ng[half:]
            lam_k = None
            r_pin = None
            for lam in self.LAM_GRID:
                r = self._ce(p_ng_pin, p_ct_pin, lam)
                if r_pin is None or r < r_pin:
                    lam_k, r_pin = lam, r
            r_k = self._ce(p_ng_ver, p_ct_ver, lam_k)
            r3 = self._ce(p_ng_ver, p_ct_ver, 0.0)
            cert["candidates"].append({"family": f"F4 order-{k} ngram x cortical mixture",
                                       "residual_ce": round(r_k, 4), "order": k,
                                       "pinned_lam": lam_k,
                                       "pin_status": "PINNED_ON_TRAIN_SLICE",
                                       "verified": "held-out"})
            cert["candidates"].append({"family": f"F3 pure ngram order-{k}",
                                       "residual_ce": round(r3, 4), "order": k,
                                       "verified": "held-out"})
            if r3_best is None or r3 < r3_best:
                r3_best = r3
            if best is None or r_k < best[2]:
                best = (k, lam_k, r_k, r3, ng)
        k_star, lam_star, r_star, r3_star, ng_star = best
        if f1_ce is not None:
            cert["candidates"].insert(0, {"family": "F1 untrained cortical readout",
                                          "residual_ce": round(f1_ce, 4),
                                          "measured": "pre-STDP pass", "verified": True})
        for k in orders:
            if k != k_star:
                cert["eliminated"].append({
                    "family": f"ngram order {k}",
                    "reason": f"held-out residual not minimal (winner order {k_star}: "
                              f"{r_star:.4f} nats/token)"})
        cert["eliminated"].append({
            "family": "F1 untrained cortical readout",
            "reason": "fresh W_proj projects untrained reservoir state; carries no corpus "
                      "conditional structure (measured pre-STDP residual above)"})
        interior = 0.0 < (lam_star or 0.0) < 1.0
        if interior and r_star < min(r2, r3_star) - 1e-6:
            cert["status"] = "PROVEN_CLASSIFICATION"
        else:
            cert["status"] = "CERTIFIED_BOUNDARY"
            cert["gaps"].append({
                "tag": "boundary_optimum",
                "detail": f"optimum at lam={lam_star}: "
                          + ("pure n-gram branch dominates" if (lam_star or 0.0) == 0.0
                             else "pure cortical branch dominates" if lam_star == 1.0
                             else "mixture not strictly dominant on held-out data")})
        cert["pinned"] = {"order": k_star, "lam": lam_star, "residual_ce": round(r_star, 4)}
        cert["ngram"] = ng_star
        cert["residuals"] = {"F1_untrained_cortical": (round(f1_ce, 4) if f1_ce is not None else None),
                             "F2_trained_cortical": round(r2, 4),
                             "F3_best_ngram": round(r3_star, 4),
                             "F4_pinned_mixture": round(r_star, 4)}
        cert["gaps"].append({
            "tag": "finite_order_coherence",
            "detail": f"n-gram order {k_star} bounds long-range coherence; grammar and "
                      "semantics beyond the certified transition statistics are NOT "
                      "claimed -- frontier-grade coherence requires the exact engine path"})
        cert["residual_note"] = ("teacher-forced cross-entropy (nats/token), lower is better; "
                                 f"pinned on {half} train-slice positions, verified on "
                                 f"{len(p_ct_ver)} held-out positions")
        return cert


class VocabTokenBridge:
    """Frontier Subword Bridge for 2014 CPUs:
    - Pure-Python BPE / SentencePiece tokenizer
    - Chunked memmap int8 lm_head matvec (< 16 MB RAM even for 256K vocab)
    - Working-memory ctx_trace + cortical-to-head linear adapter W_proj
    - Ridge self-alignment + AdamW online subword adaptation
    - Pipelined prompt prefill + temperature / top-k / top-p / repetition penalty."""

    def __init__(self, brain, chunk_vocab=8192):
        if not brain.vocab_data or "vocab" not in brain.vocab_data:
            raise ValueError("Brain does not contain HF/GGUF vocab_data + tokenizer map")
        self.brain = brain
        self.emb_q8 = brain.vocab_data["embed_q8"]
        self.emb_sc = brain.vocab_data["embed_scale"]
        self.head_q8 = brain.vocab_data["head_q8"]
        self.head_sc = brain.vocab_data["head_scale"]
        self.vocab_size = int(self.head_q8.shape[0])
        self.n_sens = brain.sensory_slice[1] - brain.sensory_slice[0]
        self.n_mot = brain.motor_slice[1] - brain.motor_slice[0]
        self.chunk_vocab = int(chunk_vocab)

        self.tokenizer = SubwordTokenizer(
            vocab=brain.vocab_data["vocab"],
            merges=brain.vocab_data.get("merges"),
            byte_level=brain.vocab_data.get("byte_level", False),
            bos_id=brain.vocab_data.get("bos_id"),
            eos_id=brain.vocab_data.get("eos_id"),
            scores=brain.vocab_data.get("scores"),
            special_tokens=brain.vocab_data.get("special_tokens"),
            add_bos=brain.vocab_data.get("add_bos"),
            add_dummy_prefix=brain.vocab_data.get("add_dummy_prefix"),
            pre_type=brain.vocab_data.get("pre_type"),
            norm_type=brain.vocab_data.get("norm_type"),
            byte_level_prefix_space=brain.vocab_data.get("byte_level_prefix_space", False),
        )

        # Cortical state = [mot_now (n_mot), ctx_trace (n_mot)] -> projected into head space (n_mot)
        self.feat_dim = 2 * self.n_mot
        self.W_proj = np.zeros((self.n_mot, self.feat_dim), dtype=np.float32)
        self.W_proj[:, :self.n_mot] = 1.60 * np.eye(self.n_mot, dtype=np.float32)
        self.W_proj[:, self.n_mot:] = 0.90 * np.eye(self.n_mot, dtype=np.float32)
        self.b_proj = np.zeros(self.n_mot, dtype=np.float32)
        self.head_bias = np.zeros(self.vocab_size, dtype=np.float32)
        self.ctx_trace = np.zeros(self.n_mot, dtype=np.float32)

        # AdamW state for W_proj + head_bias
        self._m_w = np.zeros_like(self.W_proj)
        self._v_w = np.zeros_like(self.W_proj)
        self._m_b = np.zeros_like(self.b_proj)
        self._v_b = np.zeros_like(self.b_proj)
        self._m_hb = np.zeros_like(self.head_bias)
        self._v_hb = np.zeros_like(self.head_bias)
        self._adam_t = 0

        # Reusable chunk scratch buffer (never allocates full [V, n_mot] float32!)
        self._scratch_chunk = np.empty((min(self.chunk_vocab, self.vocab_size), self.n_mot), dtype=np.float32)

        # Optional corpus n-gram LM that dominates fluency; cortical logits steer (see attach_ngram)
        self.ngram = None
        self.brain_influence = 0.35

    def attach_ngram(self, ngram, influence=0.35):
        self.ngram = ngram
        self.brain_influence = float(min(max(influence, 0.0), 1.0))

    def reset_context(self):
        self.brain.reset_state()
        self.ctx_trace.fill(0.0)

    def _embed_stim(self, tid):
        emb = self.emb_q8[tid].astype(np.float32) * self.emb_sc[tid]
        nrm = float(np.linalg.norm(emb))
        if nrm > 1e-6:
            emb = emb * np.float32((math.sqrt(self.n_sens) * 0.45) / nrm)
        return emb

    def _step_token(self, tid, ticks_per_token=6, reward_signal=0.0, plasticity=False):
        m0, m1 = self.brain.motor_slice
        stim = self._embed_stim(tid)
        mot_acc = np.zeros(self.n_mot, dtype=np.float32)
        stim_ticks = max(1, ticks_per_token // 3)
        for t in range(ticks_per_token):
            self.brain.step(
                sensory_current=(stim if t < stim_ticks else None),
                reward_signal=reward_signal,
                plasticity=plasticity,
            )
            w_t = (1.5 if t >= ticks_per_token // 2 else 0.5) / max(ticks_per_token, 1)
            mot_acc += w_t * np.maximum(self.brain.v_basal[m0:m1] + 0.5 * self.brain.v_apical[m0:m1], 0.0)
            if len(self.brain.last_spikes) > 0:
                m_sp = self.brain.last_spikes[(self.brain.last_spikes >= m0) & (self.brain.last_spikes < m1)] - m0
                if len(m_sp) > 0:
                    mot_acc[m_sp] += w_t * 2.0
        echo = stim[:self.n_mot] if self.n_sens >= self.n_mot else np.pad(stim, (0, self.n_mot - self.n_sens))
        self.ctx_trace = 0.68 * self.ctx_trace + 0.32 * mot_acc + 0.12 * echo
        feat = np.concatenate([mot_acc, self.ctx_trace])
        nrm = float(np.linalg.norm(feat))
        return (feat / nrm) if nrm > 1e-6 else feat

    def _project_to_head(self, feat):
        return self.W_proj @ feat + self.b_proj

    def _compute_logits(self, h_vec):
        """Chunked memmap int8 matvec: bounded RAM even for 256K+ frontier vocab."""
        logits = np.empty(self.vocab_size, dtype=np.float32)
        c_sz = self.chunk_vocab
        for r0 in range(0, self.vocab_size, c_sz):
            r1 = min(self.vocab_size, r0 + c_sz)
            m = r1 - r0
            buf = self._scratch_chunk[:m]
            np.copyto(buf, self.head_q8[r0:r1], casting="unsafe")
            logits[r0:r1] = (buf @ h_vec) * self.head_sc[r0:r1] + self.head_bias[r0:r1]
        return logits

    def align_cortex(self, n_probes=48, ticks_per_token=6, seed=7):
        """Fast ridge-regression alignment between cortical motor state and lm_head space."""
        rng = np.random.default_rng(seed)
        probe_ids = rng.integers(0, self.vocab_size, size=n_probes)
        X = np.empty((n_probes, self.feat_dim), dtype=np.float32)
        Y = np.empty((n_probes, self.n_mot), dtype=np.float32)
        for i, tid in enumerate(probe_ids):
            self.reset_context()
            X[i] = self._step_token(int(tid), ticks_per_token=ticks_per_token, plasticity=False)
            tgt = self.head_q8[tid].astype(np.float32) * self.head_sc[tid]
            tn = float(np.linalg.norm(tgt))
            Y[i] = (tgt / tn) if tn > 1e-6 else tgt
        XtX = X.T @ X + 0.5 * np.eye(self.feat_dim, dtype=np.float32)
        self.W_proj = np.linalg.solve(XtX, X.T @ Y).T.astype(np.float32)
        self.b_proj.fill(0.0)
        return float(np.mean(np.sum((X @ self.W_proj.T) * Y, axis=1)))

    def train_sequence(self, text, lr=0.015, ticks_per_token=None, epochs=10, stdp_epochs=2):
        """Trains W_proj + cortical STDP over subword tokens via chunked memmap AdamW."""
        if ticks_per_token is None:
            ticks_per_token = min(max(self.brain.n_layers + 2, 5), 10)
        tok_ids = self.tokenizer.encode(text, add_bos=True)
        if len(tok_ids) < 2:
            return [0.0]
        losses = []
        beta1, beta2, eps, wd = 0.9, 0.999, 1e-6, 1e-4

        for ep in range(epochs):
            self.reset_context()
            ep_loss = 0.0
            lr_ep = lr * (0.96 ** ep)
            use_stdp = ep < min(stdp_epochs, max(1, epochs // 3)) if epochs > 1 else (stdp_epochs > 0)
            for i in range(len(tok_ids) - 1):
                t_in, t_tgt = tok_ids[i], tok_ids[i + 1]
                feat = self._step_token(
                    t_in, ticks_per_token=ticks_per_token,
                    reward_signal=0.25 if use_stdp else 0.0, plasticity=use_stdp,
                )
                h = self.W_proj @ feat + self.b_proj

                logits = self._compute_logits(h)
                probs = np.exp(logits - logits.max())
                probs /= probs.sum()
                ep_loss += -math.log(max(float(probs[t_tgt]), 1e-9))

                grad_logits = probs
                grad_logits[t_tgt] -= 1.0
                # Chunked memmap gradient: g_h = sum_v grad_logits[v] * head_sc[v] * head_q8[v]
                g_h = np.zeros(self.n_mot, dtype=np.float32)
                for r0 in range(0, self.vocab_size, self.chunk_vocab):
                    r1 = min(self.vocab_size, r0 + self.chunk_vocab)
                    m = r1 - r0
                    buf = self._scratch_chunk[:m]
                    np.copyto(buf, self.head_q8[r0:r1], casting="unsafe")
                    w_grad = grad_logits[r0:r1] * self.head_sc[r0:r1]
                    g_h += w_grad @ buf

                g_w = np.outer(g_h, feat) + wd * self.W_proj
                g_b = g_h

                self._adam_t += 1
                self._m_w = beta1 * self._m_w + (1.0 - beta1) * g_w
                self._v_w = beta2 * self._v_w + (1.0 - beta2) * (g_w * g_w)
                self._m_b = beta1 * self._m_b + (1.0 - beta1) * g_b
                self._v_b = beta2 * self._v_b + (1.0 - beta2) * (g_b * g_b)
                self._m_hb = beta1 * self._m_hb + (1.0 - beta1) * grad_logits
                self._v_hb = beta2 * self._v_hb + (1.0 - beta2) * (grad_logits * grad_logits)

                bc1 = 1.0 - (beta1 ** self._adam_t)
                bc2 = 1.0 - (beta2 ** self._adam_t)
                self.W_proj -= lr_ep * (self._m_w / bc1) / (np.sqrt(self._v_w / bc2) + eps)
                self.b_proj -= lr_ep * (self._m_b / bc1) / (np.sqrt(self._v_b / bc2) + eps)
                self.head_bias -= lr_ep * (self._m_hb / bc1) / (np.sqrt(self._v_hb / bc2) + eps)

            losses.append(ep_loss / max(len(tok_ids) - 1, 1))
        return losses

    @staticmethod
    def _sample_next(logits, generated_ids, temperature=0.0, top_k=40, top_p=0.95, rep_penalty=1.0, rng=None):
        if rep_penalty != 1.0 and generated_ids:
            recent = np.unique(np.asarray(generated_ids[-64:], dtype=np.int64))
            sub = logits[recent]
            logits[recent] = np.where(sub > 0, sub / rep_penalty, sub * rep_penalty)

        if temperature <= 1e-4:
            return int(np.argmax(logits))

        scaled = logits / float(temperature)
        if 0 < top_k < len(scaled):
            idx = np.argpartition(scaled, -top_k)[-top_k:]
            sub = scaled[idx]
        else:
            idx = np.arange(len(scaled), dtype=np.int64)
            sub = scaled

        order = np.argsort(sub)[::-1]
        idx = idx[order]
        sub = sub[order]
        probs = np.exp(sub - sub[0])
        probs /= probs.sum()

        if 0.0 < top_p < 1.0 and len(probs) > 1:
            cdf = np.cumsum(probs)
            cut = int(np.searchsorted(cdf, top_p, side="right")) + 1
            idx = idx[:cut]
            probs = probs[:cut]
            probs /= probs.sum()

        return int(rng.choice(idx, p=probs))

    def generate_tokens(self, prompt, max_tokens=24, ticks_per_token=None, prefill_ticks=None,
                        temperature=0.0, top_k=40, top_p=0.95, rep_penalty=1.0,
                        seed=7, return_stats=False):
        if ticks_per_token is None:
            ticks_per_token = min(max(self.brain.n_layers + 2, 5), 10)
        if prefill_ticks is None:
            prefill_ticks = ticks_per_token if len(prompt) < 128 else max(2, ticks_per_token // 2)

        tok_ids = self.tokenizer.encode(prompt, add_bos=True)
        if not tok_ids:
            tok_ids = [0]

        t0 = time.time()
        self.reset_context()
        feat = np.zeros(self.feat_dim, dtype=np.float32)
        for idx, tid in enumerate(tok_ids):
            nt = ticks_per_token if idx == len(tok_ids) - 1 else prefill_ticks
            feat = self._step_token(tid, ticks_per_token=nt, plasticity=False)

        gen_ids = []
        rng = np.random.default_rng(seed)
        eos_ids = self.tokenizer.eos_ids
        lam = self.brain_influence if self.ngram is not None else 1.0
        for _ in range(max_tokens):
            h = self._project_to_head(feat)
            logits = self._compute_logits(h)
            if self.ngram is not None:
                ng = self.ngram.logprobs(tok_ids + gen_ids, self.vocab_size)
                mx = float(logits.max())
                ex = np.exp(logits - mx)
                clp = np.log(ex + 1e-9) - math.log(max(float(ex.sum()), 1e-12))
                logits = (1.0 - lam) * ng + lam * clp
            nxt = self._sample_next(
                logits, tok_ids + gen_ids, temperature=temperature,
                top_k=top_k, top_p=top_p, rep_penalty=rep_penalty, rng=rng,
            )
            if nxt in eos_ids:
                break
            gen_ids.append(nxt)
            feat = self._step_token(nxt, ticks_per_token=ticks_per_token, plasticity=False)

        dt = max(time.time() - t0, 1e-6)
        text_out = self.tokenizer.decode(tok_ids + gen_ids)
        if return_stats:
            return text_out, {
                "prompt_tokens": len(tok_ids),
                "generated_tokens": len(gen_ids),
                "elapsed_s": dt,
                "tokens_per_s": (len(tok_ids) + len(gen_ids)) / dt,
                "drives": dict(self.brain.drives),
                "ngram": self.ngram is not None,
                "brain_influence": lam,
            }
        return text_out

    def save(self, out_dir):
        vb_dir = os.path.join(out_dir, "vocab_bridge")
        os.makedirs(vb_dir, exist_ok=True)
        np.save(os.path.join(vb_dir, "W_proj.npy"), self.W_proj)
        np.save(os.path.join(vb_dir, "b_proj.npy"), self.b_proj)
        np.save(os.path.join(vb_dir, "head_bias.npy"), self.head_bias)
        np.save(os.path.join(vb_dir, "adam_mw.npy"), self._m_w)
        np.save(os.path.join(vb_dir, "adam_vw.npy"), self._v_w)
        np.save(os.path.join(vb_dir, "adam_mb.npy"), self._m_b)
        np.save(os.path.join(vb_dir, "adam_vb.npy"), self._v_b)
        np.save(os.path.join(vb_dir, "adam_mhb.npy"), self._m_hb)
        np.save(os.path.join(vb_dir, "adam_vhb.npy"), self._v_hb)
        with open(os.path.join(vb_dir, "vbridge_meta.json"), "w", encoding="utf-8") as fh:
            json.dump({"adam_t": self._adam_t, "feat_dim": self.feat_dim,
                       "brain_influence": self.brain_influence}, fh)
        if self.ngram is not None:
            self.ngram.save(os.path.join(vb_dir, "ngram.json.gz"))

    @classmethod
    def load_or_create(cls, brain, brain_dir):
        obj = cls(brain)
        vb_dir = os.path.join(brain_dir, "vocab_bridge")
        if os.path.isdir(vb_dir):
            w_p = os.path.join(vb_dir, "W_proj.npy")
            if os.path.exists(w_p):
                w_l = np.load(w_p)
                if w_l.shape == obj.W_proj.shape:
                    obj.W_proj = w_l
                    obj.b_proj = np.load(os.path.join(vb_dir, "b_proj.npy"))
                    hb_p = os.path.join(vb_dir, "head_bias.npy")
                    if os.path.exists(hb_p):
                        obj.head_bias = np.load(hb_p)
                    for attr, fn in (("_m_w", "adam_mw.npy"), ("_v_w", "adam_vw.npy"),
                                     ("_m_b", "adam_mb.npy"), ("_v_b", "adam_vb.npy"),
                                     ("_m_hb", "adam_mhb.npy"), ("_v_hb", "adam_vhb.npy")):
                        p = os.path.join(vb_dir, fn)
                        if os.path.exists(p):
                            setattr(obj, attr, np.load(p))
                    mp = os.path.join(vb_dir, "vbridge_meta.json")
                    if os.path.exists(mp):
                        with open(mp, "r", encoding="utf-8") as fh:
                            meta = json.load(fh)
                        obj._adam_t = int(meta.get("adam_t", 0))
                        obj.brain_influence = float(meta.get("brain_influence", 0.35))
                    ng_p = os.path.join(vb_dir, "ngram.json.gz")
                    if os.path.exists(ng_p):
                        obj.ngram = CorpusNGram.load(ng_p)
        return obj




# =====================================================================
# 6b. Exact Out-of-Core Frontier Transformer Engine (Zero PyTorch)
# =====================================================================
try:
    from scipy.special import erf as _scipy_erf
except ImportError:
    _scipy_erf = None


class ExactFrontierEngine:
    """Exact pure-NumPy out-of-core Transformer inference engine for Safetensors & GGUF.
    Computes exact RMSNorm/LayerNorm, RoPE (standard/interleaved/linear/llama3/yarn/longrope),
    GQA + KV-cache, QK-Norm, SwiGLU/GeGLU/GELU, and MoE (+ shared experts)
    to produce identical tokens and text to the source frontier model."""

    def __init__(self, reader, cfg, tok_meta, cache_ram_mb=512):
        self.reader = reader
        self.cfg = dict(cfg)
        self.cache_ram_bytes = max(0, int(cache_ram_mb)) * 1024 * 1024
        self._cache = {}
        self._cache_bytes = 0

        self.n_layers = int(cfg.get("num_hidden_layers", cfg.get("n_layer", 12)))
        self.d_model = int(cfg.get("hidden_size", cfg.get("n_embd", 768)))
        self.n_heads = int(cfg.get("num_attention_heads", cfg.get("n_head", max(1, self.d_model // 64))))
        self.n_kv_heads = int(cfg.get("num_key_value_heads", self.n_heads))
        self.model_type = str(cfg.get("model_type", cfg.get("arch", "llama"))).lower()
        self.is_gguf = bool(cfg.get("is_gguf", False))
        if self.is_gguf:
            hybrid = self._detect_hybrid_gguf(reader)
            if hybrid:
                raise NotImplementedError(
                    f"ExactFrontierEngine does not support hybrid GGUF architecture '{hybrid}' "
                    "(it uses MLA/DSA-indexer/KDA-linear-attention/hyper-connection tensors that this "
                    "exact transformer graph cannot reproduce). Use the brain-conversion path instead: "
                    "--convert-gguf <path> / --mode brain (LLMToBrainConverter folds the weights into a "
                    "biological connectome without needing graph semantics).")
        is_gemma = self.model_type in ("gemma", "gemma2", "gemma3", "gemma3_text")
        self.scale_embeddings = is_gemma
        self.gemma_norm = (not self.is_gguf) and is_gemma
        self.eps = float(cfg.get("rms_norm_eps", cfg.get("layer_norm_epsilon", cfg.get("layer_norm_eps", 1e-5))))
        self.hidden_act = str(
            cfg.get("hidden_activation") or cfg.get("hidden_act") or cfg.get("activation_function") or "silu"
        ).lower()
        self.attn_softcap = cfg.get("attn_logit_softcapping")
        self.final_softcap = cfg.get("final_logit_softcapping")
        self.sliding_window = cfg.get("sliding_window")
        self.sliding_window_pattern = int(cfg.get("sliding_window_pattern", 2 if self.model_type == "gemma2" else 6))
        self.norm_topk_prob = bool(cfg.get("norm_topk_prob", self.model_type != "qwen2_moe"))
        self.scoring_func = str(cfg.get("scoring_func", "softmax")).lower()
        self.routed_scaling_factor = float(cfg.get("routed_scaling_factor", 1.0) or 1.0)
        self.n_experts_per_tok = int(cfg.get("num_experts_per_tok", 2) or 2)

        # Infer head_dim accurately (handles Qwen3 / Gemma2 where head_dim != d_model // n_heads)
        if cfg.get("head_dim") is not None:
            self.head_dim = int(cfg["head_dim"])
        else:
            q0 = reader.find_first(["model.layers.0.self_attn.q_proj.weight", "blk.0.attn_q.weight"])
            k0 = reader.find_first(["model.layers.0.self_attn.k_proj.weight", "blk.0.attn_k.weight"])
            if q0 is not None:
                self.head_dim = int(reader.tensor_info(q0)["shape"][0]) // self.n_heads
            elif k0 is not None:
                self.head_dim = int(reader.tensor_info(k0)["shape"][0]) // self.n_kv_heads
            else:
                self.head_dim = self.d_model // self.n_heads

        # Attention scale (supports Gemma-2/3 query_pre_attn_scalar)
        if cfg.get("query_pre_attn_scalar") is not None:
            self.attn_scale = np.float32(1.0 / math.sqrt(float(cfg["query_pre_attn_scalar"])))
        elif self.is_gguf and self.model_type == "gemma2" and self.d_model == 4608 and self.head_dim == 128:
            self.attn_scale = np.float32(1.0 / math.sqrt(144.0))
        else:
            self.attn_scale = np.float32(1.0 / math.sqrt(self.head_dim))

        # RoPE configuration (supports standard, interleaved GGUF, Llama3, Linear, YaRN, LongRoPE, Gemma3 local/global)
        self.rope_theta = float(cfg.get("rope_theta", 10000.0))
        self.rope_local_theta = cfg.get("rope_local_base_freq")
        if cfg.get("rotary_dim") is not None:
            self.rope_dim = int(cfg["rotary_dim"])
        elif cfg.get("partial_rotary_factor") is not None:
            self.rope_dim = int(self.head_dim * float(cfg["partial_rotary_factor"]))
        else:
            self.rope_dim = self.head_dim
        self.rope_dim = (self.rope_dim // 2) * 2
        self.rope_interleaved = self.is_gguf and (self.model_type in (
            "llama", "mistral", "mixtral", "baichuan", "internlm2",
            "deepseek", "minicpm", "xverse", "orion", "granite", "arctic", "olmo",
        ))
        self.inv_freq, self.rope_mscale = self._build_inv_freq(
            self.rope_dim, self.rope_theta, cfg.get("rope_scaling"),
            max_pos=cfg.get("max_position_embeddings", 8192),
        )
        if self.is_gguf and reader.tensor_info("rope_freqs.weight") is not None:
            rf = reader.read_1d("rope_freqs.weight").astype(np.float32)
            if len(rf) == len(self.inv_freq):
                self.inv_freq = (self.inv_freq / np.maximum(rf, 1e-12)).astype(np.float32)
        if self.rope_local_theta is not None:
            self.inv_freq_local, _ = self._build_inv_freq(
                self.rope_dim, float(self.rope_local_theta), None
            )
        else:
            self.inv_freq_local = None

        # Embedding / Head / Positional Embedding / Final Norm names
        self.emb_name = reader.find_first([
            "model.embed_tokens.weight", "transformer.wte.weight",
            "model.decoder.embed_tokens.weight", "token_embd.weight",
        ])
        self.wpe_name = reader.find_first(["transformer.wpe.weight"])
        self.has_rope = (self.wpe_name is None)
        self.final_norm_w = reader.find_first([
            "model.norm.weight", "transformer.ln_f.weight",
            "model.decoder.final_layer_norm.weight", "output_norm.weight",
        ])
        self.final_norm_b = reader.find_first([
            "transformer.ln_f.bias", "model.norm.bias", "output_norm.bias",
        ])
        head_cand = reader.find_first(["lm_head.weight", "output.weight"])
        if head_cand is None or bool(cfg.get("tie_word_embeddings", False)):
            self.head_name = self.emb_name
        else:
            self.head_name = head_cand
        self.vocab_size = int(reader.tensor_info(self.head_name)["shape"][0])

        # Tokenizer
        if tok_meta and "vocab" in tok_meta:
            self.tokenizer = SubwordTokenizer(
                vocab=tok_meta["vocab"],
                merges=tok_meta.get("merges"),
                byte_level=tok_meta.get("byte_level", False),
                bos_id=tok_meta.get("bos_id"),
                eos_id=tok_meta.get("eos_id"),
                scores=tok_meta.get("scores"),
                special_tokens=tok_meta.get("special_tokens"),
                add_bos=tok_meta.get("add_bos"),
                add_dummy_prefix=tok_meta.get("add_dummy_prefix"),
                pre_type=tok_meta.get("pre_type"),
                norm_type=tok_meta.get("norm_type"),
                byte_level_prefix_space=tok_meta.get("byte_level_prefix_space", False),
            )
        else:
            raise ValueError("Model has no tokenizer metadata for ExactFrontierEngine")

        # Per-layer tensor descriptor lookup (no weights loaded upfront!)
        self.layers = [self._discover_layer(L) for L in range(self.n_layers)]
        self.k_cache = [None] * self.n_layers
        self.v_cache = [None] * self.n_layers
        self.pos = 0

    @staticmethod
    def _detect_hybrid_gguf(reader):
        """Return the offending architecture name if the GGUF is a hybrid model
        (MLA + DSA indexer + KDA/SSM linear attention + hyper-connections + MTP)
        whose forward pass is not a plain GQA transformer graph."""
        arch = str(reader.meta.get("general.architecture", ""))
        arch_l = arch.lower()
        if arch_l.startswith("glm5") or arch_l in ("glm5next", "glm5_next", "glm4_moe"):
            return arch or "glm5"
        for key in reader.meta:
            kl = key.lower()
            if any(t in kl for t in ("hyper_connection", "kda.", "ssm.", "nextn")):
                return arch or "hybrid"
        for name in reader.tensors:
            nl = name.lower()
            if any(t in nl for t in ("attn_q_a.", "attn_kv_b.", "attn_k_b.", ".indexer.", "nextn")):
                return arch or "hybrid"
        return None

    @classmethod
    def from_model(cls, model_path, cache_ram_mb=512):
        is_gguf = os.path.isfile(model_path) and model_path.endswith(".gguf")
        if not is_gguf and os.path.isdir(model_path):
            has_st = any(f.endswith(".safetensors") for f in os.listdir(model_path))
            has_gguf = any(f.endswith(".gguf") for f in os.listdir(model_path))
            if has_gguf and not has_st:
                is_gguf = True
        if is_gguf:
            reader = GGUFStreamReader(model_path)
            cfg = reader.arch_config()
            tok_meta = reader.tokenizer_data()
        else:
            with open(os.path.join(model_path, "config.json"), "r", encoding="utf-8") as fh:
                cfg = json.load(fh)
            reader = SafetensorsStreamReader(model_path)
            tok_meta = LLMToBrainConverter.load_hf_tokenizer_meta(model_path, cfg)
        return cls(reader, cfg, tok_meta, cache_ram_mb=cache_ram_mb)

    @staticmethod
    def _build_inv_freq(rope_dim, rope_theta, rope_scaling, max_pos=8192):
        if rope_dim <= 0:
            return np.empty(0, dtype=np.float32), 1.0
        inv_freq = 1.0 / (rope_theta ** (np.arange(0, rope_dim, 2, dtype=np.float64) / rope_dim))
        mscale = 1.0
        if isinstance(rope_scaling, dict):
            rtype = str(rope_scaling.get("rope_type", rope_scaling.get("type", ""))).lower()
            factor = float(rope_scaling.get("factor", 1.0) or 1.0)
            if rtype == "linear" and factor > 1.0:
                inv_freq = inv_freq / factor
            elif rtype == "llama3" and factor > 1.0:
                low_f = float(rope_scaling.get("low_freq_factor", 1.0))
                high_f = float(rope_scaling.get("high_freq_factor", 4.0))
                orig_ctx = float(rope_scaling.get("original_max_position_embeddings", 8192))
                low_wl = orig_ctx / low_f
                high_wl = orig_ctx / high_f
                wls = (2.0 * math.pi) / inv_freq
                new_f = np.where(wls > low_wl, inv_freq / factor, inv_freq)
                smooth = (orig_ctx / wls - low_f) / max(high_f - low_f, 1e-6)
                sm_f = (1.0 - smooth) * (inv_freq / factor) + smooth * inv_freq
                inv_freq = np.where((wls >= high_wl) & (wls <= low_wl), sm_f, new_f)
            elif rtype == "yarn" and factor > 1.0:
                orig_ctx = float(rope_scaling.get("original_max_position_embeddings", 4096))
                beta_fast = float(rope_scaling.get("beta_fast", 32.0))
                beta_slow = float(rope_scaling.get("beta_slow", 1.0))
                low = max(math.floor(rope_dim * math.log(orig_ctx / (beta_fast * 2.0 * math.pi)) / (2.0 * math.log(rope_theta))), 0)
                high = min(math.ceil(rope_dim * math.log(orig_ctx / (beta_slow * 2.0 * math.pi)) / (2.0 * math.log(rope_theta))), rope_dim - 1)
                idx_d = np.arange(0, rope_dim // 2, dtype=np.float64)
                ramp = np.clip((idx_d - low) / max(high - low, 1e-3), 0.0, 1.0)
                inv_freq = (inv_freq / factor) * ramp + inv_freq * (1.0 - ramp)
                if "attention_factor" in rope_scaling:
                    mscale = float(rope_scaling["attention_factor"])
                else:
                    mscale = float(0.1 * float(rope_scaling.get("mscale", 1.0)) * math.log(factor) + 1.0)
            elif rtype in ("longrope", "su"):
                sf = rope_scaling.get("short_factor")
                lf = rope_scaling.get("long_factor")
                orig_ctx = float(rope_scaling.get("original_max_position_embeddings", 4096))
                ext = lf if (lf and max_pos > orig_ctx) else sf
                if ext and len(ext) == len(inv_freq):
                    inv_freq = inv_freq / np.asarray(ext, dtype=np.float64)
                    if factor > 1.0:
                        mscale = math.sqrt(1.0 + math.log(factor) / max(math.log(orig_ctx), 1.0))
        return inv_freq.astype(np.float32), float(mscale)

    def _discover_layer(self, L):
        r = self.reader
        ff = r.find_first
        hf_pre_ffn = ff([f"model.layers.{L}.pre_feedforward_layernorm.weight"])
        gguf_post_attn = ff([f"blk.{L}.post_attention_norm.weight"])
        gguf_post_ffn = ff([f"blk.{L}.post_ffw_norm.weight", f"blk.{L}.ffn_post_norm.weight"])
        is_4norm = (hf_pre_ffn is not None) or (gguf_post_attn is not None) or (gguf_post_ffn is not None)

        spec = {
            "in_norm_w": ff([f"model.layers.{L}.input_layernorm.weight", f"transformer.h.{L}.ln_1.weight", f"blk.{L}.attn_norm.weight"]),
            "in_norm_b": ff([f"model.layers.{L}.input_layernorm.bias", f"transformer.h.{L}.ln_1.bias", f"blk.{L}.attn_norm.bias"]),
            "q_w": ff([f"model.layers.{L}.self_attn.q_proj.weight", f"blk.{L}.attn_q.weight"]),
            "q_b": ff([f"model.layers.{L}.self_attn.q_proj.bias", f"blk.{L}.attn_q.bias"]),
            "k_w": ff([f"model.layers.{L}.self_attn.k_proj.weight", f"blk.{L}.attn_k.weight"]),
            "k_b": ff([f"model.layers.{L}.self_attn.k_proj.bias", f"blk.{L}.attn_k.bias"]),
            "v_w": ff([f"model.layers.{L}.self_attn.v_proj.weight", f"blk.{L}.attn_v.weight"]),
            "v_b": ff([f"model.layers.{L}.self_attn.v_proj.bias", f"blk.{L}.attn_v.bias"]),
            "qkv_w": ff([f"model.layers.{L}.self_attn.qkv_proj.weight", f"transformer.h.{L}.attn.c_attn.weight", f"blk.{L}.attn_qkv.weight"]),
            "qkv_b": ff([f"model.layers.{L}.self_attn.qkv_proj.bias", f"transformer.h.{L}.attn.c_attn.bias", f"blk.{L}.attn_qkv.bias"]),
            "q_norm_w": ff([f"model.layers.{L}.self_attn.q_norm.weight", f"blk.{L}.attn_q_norm.weight"]),
            "k_norm_w": ff([f"model.layers.{L}.self_attn.k_norm.weight", f"blk.{L}.attn_k_norm.weight"]),
            "o_w": ff([f"model.layers.{L}.self_attn.o_proj.weight", f"transformer.h.{L}.attn.c_proj.weight", f"model.layers.{L}.self_attn.dense.weight", f"blk.{L}.attn_output.weight"]),
            "o_b": ff([f"model.layers.{L}.self_attn.o_proj.bias", f"transformer.h.{L}.attn.c_proj.bias", f"blk.{L}.attn_output.bias"]),
            "is_4norm": is_4norm,
            "post_attn_norm_w": ff([f"model.layers.{L}.post_attention_layernorm.weight", f"blk.{L}.post_attention_norm.weight"]) if is_4norm else None,
            "pre_ffn_w": ff([f"model.layers.{L}.pre_feedforward_layernorm.weight", f"blk.{L}.ffn_norm.weight"]) if is_4norm else None,
            "post_ffn_w": ff([f"model.layers.{L}.post_feedforward_layernorm.weight", f"blk.{L}.post_ffw_norm.weight", f"blk.{L}.ffn_post_norm.weight"]) if is_4norm else None,
            "post_norm_w": None if is_4norm else ff([f"model.layers.{L}.post_attention_layernorm.weight", f"transformer.h.{L}.ln_2.weight", f"blk.{L}.ffn_norm.weight"]),
            "post_norm_b": None if is_4norm else ff([f"model.layers.{L}.post_attention_layernorm.bias", f"transformer.h.{L}.ln_2.bias", f"blk.{L}.ffn_norm.bias"]),
            "gate_up_w": ff([f"model.layers.{L}.mlp.gate_up_proj.weight"]),
            "gate_w": ff([f"model.layers.{L}.mlp.gate_proj.weight", f"blk.{L}.ffn_gate.weight"]),
            "gate_b": ff([f"model.layers.{L}.mlp.gate_proj.bias", f"blk.{L}.ffn_gate.bias"]),
            "up_w": ff([f"model.layers.{L}.mlp.up_proj.weight", f"transformer.h.{L}.mlp.c_fc.weight", f"blk.{L}.ffn_up.weight"]),
            "up_b": ff([f"model.layers.{L}.mlp.up_proj.bias", f"transformer.h.{L}.mlp.c_fc.bias", f"blk.{L}.ffn_up.bias"]),
            "down_w": ff([f"model.layers.{L}.mlp.down_proj.weight", f"transformer.h.{L}.mlp.c_proj.weight", f"blk.{L}.ffn_down.weight"]),
            "down_b": ff([f"model.layers.{L}.mlp.down_proj.bias", f"transformer.h.{L}.mlp.c_proj.bias", f"blk.{L}.ffn_down.bias"]),
            "router_w": ff([f"model.layers.{L}.mlp.gate.weight", f"model.layers.{L}.block_sparse_moe.gate.weight", f"blk.{L}.ffn_gate_inp.weight"]),
            "router_b": ff([f"model.layers.{L}.mlp.gate.bias", f"blk.{L}.ffn_gate_inp.bias"]),
            "e_score_bias": ff([f"model.layers.{L}.mlp.gate.e_score_correction_bias", f"blk.{L}.exp_probs_b.bias"]),
            "sh_gate_w": ff([f"model.layers.{L}.mlp.shared_experts.gate_proj.weight", f"model.layers.{L}.mlp.shared_expert.gate_proj.weight", f"blk.{L}.ffn_gate_shexp.weight"]),
            "sh_up_w": ff([f"model.layers.{L}.mlp.shared_experts.up_proj.weight", f"model.layers.{L}.mlp.shared_expert.up_proj.weight", f"blk.{L}.ffn_up_shexp.weight"]),
            "sh_down_w": ff([f"model.layers.{L}.mlp.shared_experts.down_proj.weight", f"model.layers.{L}.mlp.shared_expert.down_proj.weight", f"blk.{L}.ffn_down_shexp.weight"]),
            "sh_router_w": ff([f"model.layers.{L}.mlp.shared_expert_gate.weight", f"blk.{L}.ffn_gate_inp_shexp.weight"]),
            "gguf_exp_g": ff([f"blk.{L}.ffn_gate_exps.weight"]),
            "gguf_exp_u": ff([f"blk.{L}.ffn_up_exps.weight"]),
            "gguf_exp_d": ff([f"blk.{L}.ffn_down_exps.weight"]),
        }
        # Detect Phi-3/4 GGUF fused gate_up in ffn_up.weight (2 * down_cols rows, no gate_w)
        if spec["gate_up_w"] is None and spec["gate_w"] is None and spec["up_w"] is not None and spec["down_w"] is not None:
            up_sh = r.tensor_info(spec["up_w"])["shape"]
            dn_sh = r.tensor_info(spec["down_w"])["shape"]
            if len(up_sh) == 2 and len(dn_sh) == 2 and up_sh[0] == 2 * dn_sh[1]:
                spec["gate_up_w"] = spec["up_w"]

        # Detect Conv1D transposition (GPT-2 HF safetensors)
        qkv_w = spec["qkv_w"]
        spec["qkv_T"] = bool(qkv_w and "c_attn" in qkv_w and r.tensor_info(qkv_w)["shape"][0] == self.d_model)
        o_w = spec["o_w"]
        spec["o_T"] = bool(o_w and "attn.c_proj" in o_w and r.tensor_info(o_w)["shape"][0] == self.d_model)
        up_w = spec["up_w"]
        spec["up_T"] = bool(up_w and "c_fc" in up_w and r.tensor_info(up_w)["shape"][0] == self.d_model)
        down_w = spec["down_w"]
        spec["down_T"] = bool(down_w and "mlp.c_proj" in down_w and r.tensor_info(down_w)["shape"][1] == self.d_model)

        # Discover HF per-expert MoE tensors
        hf_exps = {}
        for pfx in (f"model.layers.{L}.mlp.experts.", f"model.layers.{L}.block_sparse_moe.experts."):
            keys = r.list_tensors(pfx)
            if keys:
                eids = sorted({int(k[len(pfx):].split(".")[0]) for k in keys if k[len(pfx):].split(".")[0].isdigit()})
                for eid in eids:
                    hf_exps[eid] = (
                        ff([f"{pfx}{eid}.gate_proj.weight", f"{pfx}{eid}.w1.weight"]),
                        ff([f"{pfx}{eid}.up_proj.weight", f"{pfx}{eid}.w3.weight"]),
                        ff([f"{pfx}{eid}.down_proj.weight", f"{pfx}{eid}.w2.weight"]),
                    )
                break
        spec["hf_exps"] = hf_exps
        return spec

    def reset_kv_cache(self):
        self.k_cache = [None] * self.n_layers
        self.v_cache = [None] * self.n_layers
        self.pos = 0

    def _get_1d(self, name):
        if name is None:
            return None
        if name in self._cache:
            return self._cache[name]
        vec = self.reader.read_1d(name)
        if vec is not None:
            vec = vec.astype(np.float32)
            if self._cache_bytes + vec.nbytes <= self.cache_ram_bytes:
                self._cache[name] = vec
                self._cache_bytes += vec.nbytes
        return vec

    def _embed(self, tok_ids):
        key = (self.emb_name, None)
        if key in self._cache:
            return self._cache[key][tok_ids].astype(np.float32)
        out = np.empty((len(tok_ids), self.d_model), dtype=np.float32)
        row_cache = {}
        for i, tid in enumerate(tok_ids):
            tid_i = int(tid)
            if tid_i not in row_cache:
                for _, chunk in self.reader.iter_row_chunks(self.emb_name, chunk_rows=1, row_range=(tid_i, tid_i + 1)):
                    row_cache[tid_i] = chunk[0]
                    break
            out[i] = row_cache[tid_i]
        return out

    def _linear(self, name, x, transpose=False, bias_name=None, row_range=None, chunk_rows=512, allow_cache=True):
        was_1d = (x.ndim == 1)
        x2 = np.atleast_2d(x).astype(np.float32)
        T = x2.shape[0]
        key = (name, row_range)

        if key in self._cache:
            w_f32 = self._cache[key].astype(np.float32, copy=False)
            out = (x2 @ w_f32) if transpose else (x2 @ w_f32.T)
        else:
            tinfo = self.reader.tensor_info(name)
            shape = tinfo["shape"]
            cols = shape[-1]
            tot_rows = shape[0] if len(shape) <= 2 else int(np.prod(shape[:-1]))
            r_lo, r_hi = (0, tot_rows) if row_range is None else row_range
            rows = r_hi - r_lo

            is_native_f16 = (tinfo.get("dtype") == "F16") or (tinfo.get("gtype") == 1)
            cache_dt = np.float16 if is_native_f16 else np.float32
            need_bytes = rows * cols * (2 if is_native_f16 else 4)
            if allow_cache and (self._cache_bytes + need_bytes <= self.cache_ram_bytes):
                w_mat = np.empty((rows, cols), dtype=cache_dt)
                for r0, chunk in self.reader.iter_row_chunks(name, chunk_rows=chunk_rows, row_range=row_range):
                    w_mat[r0 : r0 + chunk.shape[0]] = chunk.astype(cache_dt, copy=False)
                self._cache[key] = w_mat
                self._cache_bytes += need_bytes
                w_f32 = w_mat.astype(np.float32, copy=False)
                out = (x2 @ w_f32) if transpose else (x2 @ w_f32.T)
            else:
                if transpose:
                    out = np.zeros((T, cols), dtype=np.float32)
                    for r0, chunk in self.reader.iter_row_chunks(name, chunk_rows=chunk_rows, row_range=row_range):
                        out += x2[:, r0 : r0 + chunk.shape[0]] @ chunk
                else:
                    out = np.empty((T, rows), dtype=np.float32)
                    for r0, chunk in self.reader.iter_row_chunks(name, chunk_rows=chunk_rows, row_range=row_range):
                        out[:, r0 : r0 + chunk.shape[0]] = x2 @ chunk.T

        if bias_name is not None:
            b = self._get_1d(bias_name)
            if b is not None:
                out = out + b[None, :]
        return out[0] if was_1d else out

    def _norm(self, x, w_name, b_name=None, force_gemma=None):
        w = self._get_1d(w_name)
        b = self._get_1d(b_name) if b_name is not None else None
        x_f = x.astype(np.float32)
        if b is not None:
            mean = np.mean(x_f, axis=-1, keepdims=True)
            var = np.mean((x_f - mean) ** 2, axis=-1, keepdims=True)
            out = (x_f - mean) / np.sqrt(var + self.eps)
            if w is not None:
                out = out * w
            return out + b
        inv_rms = 1.0 / np.sqrt(np.mean(x_f * x_f, axis=-1, keepdims=True) + self.eps)
        out = x_f * inv_rms
        if w is not None:
            use_gemma = self.gemma_norm if force_gemma is None else force_gemma
            scale = (1.0 + w) if use_gemma else w
            out = out * scale
        return out

    def _apply_rope(self, x, positions, inv_freq=None, mscale=1.0):
        if self.rope_dim <= 0:
            return x
        if inv_freq is None:
            inv_freq = self.inv_freq
            mscale = self.rope_mscale
        freqs = positions[:, None].astype(np.float32) * inv_freq[None, :]
        cos = (np.cos(freqs) * np.float32(mscale))[:, None, :]
        sin = (np.sin(freqs) * np.float32(mscale))[:, None, :]
        out = x.copy()
        if self.rope_interleaved:
            x0 = x[..., :self.rope_dim:2]
            x1 = x[..., 1:self.rope_dim:2]
            out[..., :self.rope_dim:2] = x0 * cos - x1 * sin
            out[..., 1:self.rope_dim:2] = x1 * cos + x0 * sin
        else:
            half = self.rope_dim // 2
            x0 = x[..., :half]
            x1 = x[..., half:self.rope_dim]
            out[..., :half] = x0 * cos - x1 * sin
            out[..., half:self.rope_dim] = x1 * cos + x0 * sin
        return out

    def _act(self, z):
        if "gelu_pytorch_tanh" in self.hidden_act or "gelu_new" in self.hidden_act or self.hidden_act == "gelu_fast":
            return 0.5 * z * (1.0 + np.tanh(math.sqrt(2.0 / math.pi) * (z + 0.044715 * (z * z * z))))
        if self.hidden_act == "gelu":
            if _scipy_erf is not None:
                return 0.5 * z * (1.0 + _scipy_erf(z / math.sqrt(2.0)))
            return 0.5 * z * (1.0 + np.tanh(math.sqrt(2.0 / math.pi) * (z + 0.044715 * (z * z * z))))
        return z / (1.0 + np.exp(-np.clip(z, -80.0, 80.0)))

    def _run_mlp(self, sp, h2):
        T = h2.shape[0]
        out_tot = np.zeros((T, self.d_model), dtype=np.float32)
        has_dense = (sp["gate_up_w"] is not None) or (sp["up_w"] is not None and sp["down_w"] is not None)

        if sp["router_w"] is None and has_dense:
            if sp["gate_up_w"] is not None:
                gu = self._linear(sp["gate_up_w"], h2)
                mid = gu.shape[-1] // 2
                act = self._act(gu[:, :mid]) * gu[:, mid:]
                return self._linear(sp["down_w"], act, transpose=sp["down_T"], bias_name=sp["down_b"])
            if sp["gate_w"] is not None:
                g = self._linear(sp["gate_w"], h2, bias_name=sp["gate_b"])
                u = self._linear(sp["up_w"], h2, transpose=sp["up_T"], bias_name=sp["up_b"])
                act = self._act(g) * u
                return self._linear(sp["down_w"], act, transpose=sp["down_T"], bias_name=sp["down_b"])
            u = self._linear(sp["up_w"], h2, transpose=sp["up_T"], bias_name=sp["up_b"])
            return self._linear(sp["down_w"], self._act(u), transpose=sp["down_T"], bias_name=sp["down_b"])

        # MoE Routing (supports softmax + sigmoid + e_score_correction_bias + routed_scaling_factor)
        if sp["router_w"] is not None:
            r_logits = self._linear(sp["router_w"], h2, bias_name=sp["router_b"])
            if self.scoring_func == "sigmoid":
                probs = 1.0 / (1.0 + np.exp(-np.clip(r_logits, -80.0, 80.0)))
            else:
                r_logits = r_logits - np.max(r_logits, axis=-1, keepdims=True)
                probs = np.exp(r_logits)
                probs /= np.sum(probs, axis=-1, keepdims=True)

            sel_scores = probs
            if sp["e_score_bias"] is not None:
                eb = self._get_1d(sp["e_score_bias"])
                if eb is not None:
                    sel_scores = probs + eb[None, :]

            k = min(self.n_experts_per_tok, probs.shape[-1])
            topk_idx = np.argpartition(sel_scores, -k, axis=-1)[:, -k:]
            topk_w = np.take_along_axis(probs, topk_idx, axis=-1)
            if self.norm_topk_prob:
                topk_w /= np.maximum(np.sum(topk_w, axis=-1, keepdims=True), 1e-12)
            if self.routed_scaling_factor != 1.0:
                topk_w = topk_w * np.float32(self.routed_scaling_factor)

            hf_exps = sp["hf_exps"]
            if hf_exps:
                for eid in np.unique(topk_idx):
                    eid_i = int(eid)
                    eg, eu, ed = hf_exps[eid_i]
                    t_idx, slot_idx = np.where(topk_idx == eid_i)
                    hx = h2[t_idx]
                    u_v = self._linear(eu, hx)
                    if eg is not None:
                        u_v = self._act(self._linear(eg, hx)) * u_v
                    else:
                        u_v = self._act(u_v)
                    e_out = self._linear(ed, u_v)
                    np.add.at(out_tot, t_idx, e_out * topk_w[t_idx, slot_idx, None])
            elif sp["gguf_exp_u"] and sp["gguf_exp_d"]:
                r_u = int(self.reader.tensor_info(sp["gguf_exp_u"])["shape"][1])
                r_d = int(self.reader.tensor_info(sp["gguf_exp_d"])["shape"][1])
                r_g = int(self.reader.tensor_info(sp["gguf_exp_g"])["shape"][1]) if sp["gguf_exp_g"] else 0
                for eid in np.unique(topk_idx):
                    eid_i = int(eid)
                    t_idx, slot_idx = np.where(topk_idx == eid_i)
                    hx = h2[t_idx]
                    u_v = self._linear(sp["gguf_exp_u"], hx, row_range=(eid_i * r_u, (eid_i + 1) * r_u))
                    if sp["gguf_exp_g"]:
                        g_v = self._linear(sp["gguf_exp_g"], hx, row_range=(eid_i * r_g, (eid_i + 1) * r_g))
                        u_v = self._act(g_v) * u_v
                    else:
                        u_v = self._act(u_v)
                    e_out = self._linear(sp["gguf_exp_d"], u_v, row_range=(eid_i * r_d, (eid_i + 1) * r_d))
                    np.add.at(out_tot, t_idx, e_out * topk_w[t_idx, slot_idx, None])

        # Shared Experts (Qwen2-MoE / DeepSeek)
        if sp["sh_up_w"] is not None and sp["sh_down_w"] is not None:
            su = self._linear(sp["sh_up_w"], h2)
            if sp["sh_gate_w"] is not None:
                su = self._act(self._linear(sp["sh_gate_w"], h2)) * su
            else:
                su = self._act(su)
            sh_out = self._linear(sp["sh_down_w"], su)
            if sp["sh_router_w"] is not None:
                sg = self._linear(sp["sh_router_w"], h2)
                sh_out = sh_out * (1.0 / (1.0 + np.exp(-np.clip(sg, -80.0, 80.0))))
            out_tot += sh_out
        return out_tot

    def forward_tokens(self, tok_ids):
        """Exact forward pass for token sequence tok_ids -> updates KV cache -> returns last-token logits."""
        tok_ids = [int(t) for t in tok_ids]
        T = len(tok_ids)
        positions = np.arange(self.pos, self.pos + T, dtype=np.int64)
        X = self._embed(tok_ids)
        if self.scale_embeddings:
            X = X * np.float32(math.sqrt(self.d_model))
        if self.wpe_name is not None:
            wpe_rows = np.empty((T, self.d_model), dtype=np.float32)
            for i, p in enumerate(positions):
                for _, chunk in self.reader.iter_row_chunks(self.wpe_name, chunk_rows=1, row_range=(int(p), int(p) + 1)):
                    wpe_rows[i] = chunk[0]
                    break
            X = X + wpe_rows

        q_dim = self.n_heads * self.head_dim
        kv_dim = self.n_kv_heads * self.head_dim
        n_rep = self.n_heads // self.n_kv_heads
        inv_sqrt_d = self.attn_scale

        for L in range(self.n_layers):
            sp = self.layers[L]
            h = self._norm(X, sp["in_norm_w"], sp["in_norm_b"])

            if sp["q_w"] is not None:
                q = self._linear(sp["q_w"], h, bias_name=sp["q_b"])
                k = self._linear(sp["k_w"], h, bias_name=sp["k_b"])
                v = self._linear(sp["v_w"], h, bias_name=sp["v_b"])
            else:
                qkv = self._linear(sp["qkv_w"], h, transpose=sp["qkv_T"], bias_name=sp["qkv_b"])
                q = qkv[:, :q_dim]
                k = qkv[:, q_dim : q_dim + kv_dim]
                v = qkv[:, q_dim + kv_dim : q_dim + 2 * kv_dim]

            q = q.reshape(T, self.n_heads, self.head_dim)
            k = k.reshape(T, self.n_kv_heads, self.head_dim)
            v = v.reshape(T, self.n_kv_heads, self.head_dim)

            if sp["q_norm_w"] is not None:
                q = self._norm(q, sp["q_norm_w"])
            if sp["k_norm_w"] is not None:
                k = self._norm(k, sp["k_norm_w"])

            if self.has_rope:
                use_local = False
                if self.inv_freq_local is not None:
                    use_local = ((L + 1) % self.sliding_window_pattern != 0)
                if use_local:
                    q = self._apply_rope(q, positions, inv_freq=self.inv_freq_local, mscale=1.0)
                    k = self._apply_rope(k, positions, inv_freq=self.inv_freq_local, mscale=1.0)
                else:
                    q = self._apply_rope(q, positions)
                    k = self._apply_rope(k, positions)

            if self.k_cache[L] is None:
                self.k_cache[L] = k
                self.v_cache[L] = v
            else:
                self.k_cache[L] = np.concatenate([self.k_cache[L], k], axis=0)
                self.v_cache[L] = np.concatenate([self.v_cache[L], v], axis=0)

            k_all = self.k_cache[L]
            v_all = self.v_cache[L]
            if n_rep > 1:
                k_all = np.repeat(k_all, n_rep, axis=1)
                v_all = np.repeat(v_all, n_rep, axis=1)

            q_t = q.transpose(1, 0, 2)        # (H, T, D)
            k_t = k_all.transpose(1, 2, 0)    # (H, D, T_tot)
            v_t = v_all.transpose(1, 0, 2)    # (H, T_tot, D)
            scores = (q_t @ k_t) * inv_sqrt_d
            if self.attn_softcap is not None:
                cap = np.float32(self.attn_softcap)
                scores = cap * np.tanh(scores / cap)

            T_tot = k_all.shape[0]
            use_sw = (self.sliding_window is not None) and (
                (self.model_type == "gemma2" and L % 2 == 0)
                or (self.model_type in ("gemma3", "gemma3_text") and (L + 1) % self.sliding_window_pattern != 0)
                or (self.model_type not in ("gemma2", "gemma3", "gemma3_text"))
            )
            if T > 1 or (use_sw and T_tot > self.sliding_window):
                q_pos = positions[:, None]
                k_pos = np.arange(T_tot, dtype=np.int64)[None, :]
                mask = (k_pos > q_pos)
                if use_sw:
                    mask = mask | (k_pos <= q_pos - int(self.sliding_window))
                scores = np.where(mask[None, :, :], np.float32(-1e9), scores)

            scores = scores - np.max(scores, axis=-1, keepdims=True)
            probs = np.exp(scores)
            probs /= np.sum(probs, axis=-1, keepdims=True)
            attn_out = (probs @ v_t).transpose(1, 0, 2).reshape(T, q_dim)
            attn_proj = self._linear(sp["o_w"], attn_out, transpose=sp["o_T"], bias_name=sp["o_b"])

            if sp["is_4norm"]:
                # Gemma2 / Gemma3 4-norm block
                if sp["post_attn_norm_w"] is not None:
                    attn_proj = self._norm(attn_proj, sp["post_attn_norm_w"])
                X = X + attn_proj
                h2 = self._norm(X, sp["pre_ffn_w"]) if sp["pre_ffn_w"] is not None else X
                mlp_out = self._run_mlp(sp, h2)
                if sp["post_ffn_w"] is not None:
                    mlp_out = self._norm(mlp_out, sp["post_ffn_w"])
                X = X + mlp_out
            else:
                X = X + attn_proj
                h2 = self._norm(X, sp["post_norm_w"], sp["post_norm_b"])
                X = X + self._run_mlp(sp, h2)

        self.pos += T
        h_last = self._norm(X[-1], self.final_norm_w, self.final_norm_b)
        logits = self._linear(
            self.head_name, h_last, chunk_rows=2048,
            allow_cache=(self.vocab_size * self.d_model * 4 <= self.cache_ram_bytes // 2),
        )
        if self.final_softcap is not None:
            cap = np.float32(self.final_softcap)
            logits = cap * np.tanh(logits / cap)
        return logits

    def generate_tokens(self, prompt, max_tokens=64, temperature=0.0, top_k=40,
                        top_p=0.95, rep_penalty=1.0, seed=7, return_stats=False,
                        reset=True):
        if reset:
            self.reset_kv_cache()
        tok_ids = self.tokenizer.encode(prompt)
        if not tok_ids:
            tok_ids = [self.tokenizer.bos_id if self.tokenizer.bos_id is not None else 0]

        t0 = time.time()
        logits = self.forward_tokens(tok_ids)
        gen_ids = []
        rng = np.random.default_rng(seed)
        eos_ids = self.tokenizer.eos_ids

        for _ in range(max_tokens):
            nxt = VocabTokenBridge._sample_next(
                logits, tok_ids + gen_ids, temperature=temperature,
                top_k=top_k, top_p=top_p, rep_penalty=rep_penalty, rng=rng,
            )
            if nxt in eos_ids:
                break
            gen_ids.append(nxt)
            logits = self.forward_tokens([nxt])

        dt = max(time.time() - t0, 1e-6)
        text_out = self.tokenizer.decode(tok_ids + gen_ids)
        if return_stats:
            return text_out, {
                "prompt_tokens": len(tok_ids),
                "generated_tokens": len(gen_ids),
                "elapsed_s": dt,
                "tokens_per_s": (len(tok_ids) + len(gen_ids)) / dt,
                "cache_mb": self._cache_bytes / 1e6,
            }
        return text_out


# =====================================================================
# 7. Self-Tests (BF16 Safetensors + GGUF Q4_0/Q4_K/Q8_0 + MoE + CLI)
# =====================================================================
def _write_mock_hf_safetensors(tmp_dir, n_layers=4, d_model=128, d_ff=256,
                               dtype="F16", include_vocab=False, include_gate=True,
                               n_experts=0):
    rng = np.random.default_rng(7)
    cfg = {"num_hidden_layers": n_layers, "hidden_size": d_model, "intermediate_size": d_ff}
    with open(os.path.join(tmp_dir, "config.json"), "w") as fh:
        json.dump(cfg, fh)

    tensors = {}
    if include_vocab:
        vocab_tokens = ["<unk>", "<s>", "</s>", " ", "Ġ", "Sparse", "cortical", "neurons",
                        "spike", "efficiently", "frontier"] + [chr(c) for c in range(33, 127)]
        vocab_map = {t: i for i, t in enumerate(vocab_tokens)}
        v_size = len(vocab_tokens)
        tensors["model.embed_tokens.weight"] = rng.normal(0, 0.08, (v_size, d_model)).astype(np.float32)
        tensors["lm_head.weight"] = rng.normal(0, 0.08, (v_size, d_model)).astype(np.float32)
        with open(os.path.join(tmp_dir, "tokenizer.json"), "w") as fh:
            json.dump({"model": {"vocab": vocab_map, "merges": ["S p", "Sp a", "Spa r", "Spar s", "Spars e"]}}, fh)

    for L in range(n_layers):
        tensors[f"model.layers.{L}.input_layernorm.weight"] = np.ones(d_model, dtype=np.float32)
        tensors[f"model.layers.{L}.post_attention_layernorm.weight"] = np.ones(d_model, dtype=np.float32)
        tensors[f"model.layers.{L}.self_attn.q_proj.weight"] = rng.normal(0, 0.05, (d_model, d_model)).astype(np.float32)
        tensors[f"model.layers.{L}.self_attn.k_proj.weight"] = rng.normal(0, 0.05, (d_model // 2, d_model)).astype(np.float32)
        tensors[f"model.layers.{L}.self_attn.v_proj.weight"] = rng.normal(0, 0.05, (d_model // 2, d_model)).astype(np.float32)
        tensors[f"model.layers.{L}.self_attn.o_proj.weight"] = rng.normal(0, 0.05, (d_model, d_model)).astype(np.float32)
        if n_experts > 0:
            for e in range(n_experts):
                tensors[f"model.layers.{L}.mlp.experts.{e}.up_proj.weight"] = rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32)
                tensors[f"model.layers.{L}.mlp.experts.{e}.gate_proj.weight"] = rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32)
                tensors[f"model.layers.{L}.mlp.experts.{e}.down_proj.weight"] = rng.normal(0, 0.05, (d_model, d_ff)).astype(np.float32)
        else:
            tensors[f"model.layers.{L}.mlp.up_proj.weight"] = rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32)
            if include_gate:
                tensors[f"model.layers.{L}.mlp.gate_proj.weight"] = rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32)
            tensors[f"model.layers.{L}.mlp.down_proj.weight"] = rng.normal(0, 0.05, (d_model, d_ff)).astype(np.float32)

    header = {}
    body = bytearray()
    for name, arr in tensors.items():
        if dtype == "BF16":
            u32 = arr.view(np.uint32)
            raw = (u32 >> 16).astype(np.uint16).tobytes()
        else:
            raw = arr.astype(np.float16).tobytes()
        header[name] = {"dtype": dtype, "shape": list(arr.shape), "data_offsets": [len(body), len(body) + len(raw)]}
        body.extend(raw)
    h_bytes = json.dumps(header).encode("utf-8")
    with open(os.path.join(tmp_dir, "model.safetensors"), "wb") as fh:
        fh.write(struct.pack("<Q", len(h_bytes)))
        fh.write(h_bytes)
        fh.write(body)


def _pack_q8_0(mat_f32):
    rows, cols = mat_f32.shape
    n_blk = cols // 32
    m = mat_f32.reshape(rows, n_blk, 32)
    amax = np.max(np.abs(m), axis=2, keepdims=True)
    d = np.maximum(amax / 127.0, 1e-6).astype(np.float16)
    qs = np.clip(np.round(m / d.astype(np.float32)), -127, 127).astype(np.int8)
    out = np.empty((rows, n_blk, 34), dtype=np.uint8)
    out[:, :, :2] = d.view(np.uint8)
    out[:, :, 2:] = qs.view(np.uint8)
    return out.tobytes()


def _write_mock_gguf(gguf_path, n_layers=2, d_model=128, d_ff=256):
    rng = np.random.default_rng(11)
    tokens = ["<unk>", "<s>", "</s>", "▁Sparse", "▁cortical", "▁neurons", "▁run"] + [chr(c) for c in range(33, 127)]
    kv = [
        ("general.architecture", 8, "llama"),
        ("llama.block_count", 4, n_layers),
        ("llama.embedding_length", 4, d_model),
        ("llama.feed_forward_length", 4, d_ff),
        ("llama.attention.head_count", 4, 4),
        ("llama.attention.head_count_kv", 4, 2),
        ("tokenizer.ggml.model", 8, "llama"),
        ("tokenizer.ggml.bos_token_id", 4, 1),
        ("tokenizer.ggml.eos_token_id", 4, 2),
        ("tokenizer.ggml.tokens", 9, (8, tokens)),
    ]

    def _enc_str(s):
        b = s.encode("utf-8")
        return struct.pack("<Q", len(b)) + b

    tensors = [
        ("token_embd.weight", (len(tokens), d_model), 8, _pack_q8_0(rng.normal(0, 0.08, (len(tokens), d_model)).astype(np.float32))),
        ("output.weight", (len(tokens), d_model), 8, _pack_q8_0(rng.normal(0, 0.08, (len(tokens), d_model)).astype(np.float32))),
    ]
    for L in range(n_layers):
        tensors.append((f"blk.{L}.attn_norm.weight", (d_model,), 0, np.ones(d_model, dtype=np.float32).tobytes()))
        tensors.append((f"blk.{L}.ffn_norm.weight", (d_model,), 0, np.ones(d_model, dtype=np.float32).tobytes()))
        tensors.append((f"blk.{L}.attn_q.weight", (d_model, d_model), 8, _pack_q8_0(rng.normal(0, 0.05, (d_model, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.attn_k.weight", (d_model // 2, d_model), 8, _pack_q8_0(rng.normal(0, 0.05, (d_model // 2, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.attn_v.weight", (d_model // 2, d_model), 8, _pack_q8_0(rng.normal(0, 0.05, (d_model // 2, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.attn_output.weight", (d_model, d_model), 8, _pack_q8_0(rng.normal(0, 0.05, (d_model, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.ffn_up.weight", (d_ff, d_model), 8, _pack_q8_0(rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.ffn_gate.weight", (d_ff, d_model), 8, _pack_q8_0(rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.ffn_down.weight", (d_model, d_ff), 8, _pack_q8_0(rng.normal(0, 0.05, (d_model, d_ff)).astype(np.float32))))

    hdr = bytearray(b"GGUF")
    hdr.extend(struct.pack("<IQQ", 3, len(tensors), len(kv)))
    for k, vt, val in kv:
        hdr.extend(_enc_str(k))
        hdr.extend(struct.pack("<I", vt))
        if vt == 8:
            hdr.extend(_enc_str(val))
        elif vt == 4:
            hdr.extend(struct.pack("<I", val))
        elif vt == 9:
            et, arr = val
            hdr.extend(struct.pack("<IQ", et, len(arr)))
            for s in arr:
                hdr.extend(_enc_str(s))

    data_buf = bytearray()
    for name, shape, gtype, raw in tensors:
        hdr.extend(_enc_str(name))
        ggml_dims = list(reversed(shape))
        hdr.extend(struct.pack("<I", len(ggml_dims)))
        for d in ggml_dims:
            hdr.extend(struct.pack("<Q", d))
        off = len(data_buf)
        hdr.extend(struct.pack("<IQ", gtype, off))
        data_buf.extend(raw)
        pad = (32 - (len(data_buf) % 32)) % 32
        data_buf.extend(b"\x00" * pad)

    pad_hdr = (32 - (len(hdr) % 32)) % 32
    hdr.extend(b"\x00" * pad_hdr)
    with open(gguf_path, "wb") as fh:
        fh.write(hdr)
        fh.write(data_buf)


def _write_mock_gguf_sharded(out_dir, base_name="mock-llm-UD-IQ1_S", n_shards=3, n_layers=4,
                             d_model=256, d_ff=512, n_experts=4, arch="glm5-mock", with_mmproj=True):
    """GLM-5.3-Flash-style mock: N shards + mmproj-F16.gguf decoy, mixed quants,
    dense layers + MoE layers (3D exps, router, exp_probs_b, shared experts)."""

    def _enc_str(s):
        b = s.encode("utf-8")
        return struct.pack("<Q", len(b)) + b

    rng = np.random.default_rng(21)
    tokens = ["<unk>", "<s>", "</s>", "ĠSparse", "Ġcortical", "Ġneurons", "Ġrun"] + [chr(c) for c in range(33, 127)]
    kv = [
        ("general.architecture", 8, arch),
        (f"{arch}.block_count", 4, n_layers),
        (f"{arch}.embedding_length", 4, d_model),
        (f"{arch}.feed_forward_length", 4, d_ff),
        (f"{arch}.attention.head_count", 4, 4),
        (f"{arch}.attention.head_count_kv", 4, 2),
        (f"{arch}.expert_count", 4, n_experts),
        (f"{arch}.expert_used_count", 4, 2),
        (f"{arch}.expert_gating_func", 4, 2),
        (f"{arch}.expert_weights_scale", 6, 2.5),
        (f"{arch}.expert_weights_norm", 7, True),
        ("tokenizer.ggml.model", 8, "gpt2"),
        ("tokenizer.ggml.pre", 8, "glm4"),
        ("tokenizer.ggml.bos_token_id", 4, 1),
        ("tokenizer.ggml.eos_token_id", 4, 2),
        ("tokenizer.ggml.tokens", 9, (8, tokens)),
    ]

    def _rand_iq_raw(shape, gtype, rng):
        _, qk, bsz = GGUFStreamReader.GGML_QUANT[gtype]
        n_rows = 1
        for d in shape:
            n_rows *= d
        total_blocks = n_rows * (shape[-1] // qk)
        raw = bytearray(rng.integers(0, 256, total_blocks * bsz, dtype=np.uint8).tobytes())
        if gtype in (16, 18, 19, 23, 20):
            for off in range(0, len(raw), bsz):
                raw[off:off + 2] = np.array([rng.uniform(0.01, 0.4)], dtype="<f2").tobytes()
        return bytes(raw)

    tensors = [
        ("token_embd.weight", [len(tokens), d_model], 8,
         _pack_q8_0(rng.normal(0, 0.08, (len(tokens), d_model)).astype(np.float32))),
        ("output.weight", [len(tokens), d_model], 8,
         _pack_q8_0(rng.normal(0, 0.08, (len(tokens), d_model)).astype(np.float32))),
        ("output_norm.weight", [d_model], 0, np.ones(d_model, dtype=np.float32).tobytes()),
    ]
    for L in range(n_layers):
        tensors.append((f"blk.{L}.attn_norm", [d_model], 0, np.ones(d_model, dtype=np.float32).tobytes()))
        tensors.append((f"blk.{L}.ffn_norm", [d_model], 0, np.ones(d_model, dtype=np.float32).tobytes()))
        tensors.append((f"blk.{L}.attn_q.weight", [d_model, d_model], 8,
                        _pack_q8_0(rng.normal(0, 0.05, (d_model, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.attn_k.weight", [d_model // 2, d_model], 8,
                        _pack_q8_0(rng.normal(0, 0.05, (d_model // 2, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.attn_v.weight", [d_model // 2, d_model], 8,
                        _pack_q8_0(rng.normal(0, 0.05, (d_model // 2, d_model)).astype(np.float32))))
        tensors.append((f"blk.{L}.attn_output.weight", [d_model, d_model], 23,
                        _rand_iq_raw([d_model, d_model], 23, rng)))
        if L % 2 == 1:
            tensors.append((f"blk.{L}.ffn_gate_inp.weight", [n_experts, d_model], 0,
                            rng.normal(0, 0.05, (n_experts, d_model)).astype(np.float32).tobytes()))
            tensors.append((f"blk.{L}.exp_probs_b.bias", [n_experts], 0,
                            rng.normal(0, 0.01, n_experts).astype(np.float32).tobytes()))
            tensors.append((f"blk.{L}.ffn_gate_exps.weight", [n_experts, d_ff, d_model], 19,
                            _rand_iq_raw([n_experts, d_ff, d_model], 19, rng)))
            tensors.append((f"blk.{L}.ffn_up_exps.weight", [n_experts, d_ff, d_model], 16,
                            _rand_iq_raw([n_experts, d_ff, d_model], 16, rng)))
            tensors.append((f"blk.{L}.ffn_down_exps.weight", [n_experts, d_model, d_ff], 18,
                            _rand_iq_raw([n_experts, d_model, d_ff], 18, rng)))
            tensors.append((f"blk.{L}.ffn_gate_shexp.weight", [d_ff, d_model], 8,
                            _pack_q8_0(rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32))))
            tensors.append((f"blk.{L}.ffn_up_shexp.weight", [d_ff, d_model], 8,
                            _pack_q8_0(rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32))))
            tensors.append((f"blk.{L}.ffn_down_shexp.weight", [d_model, d_ff], 8,
                            _pack_q8_0(rng.normal(0, 0.05, (d_model, d_ff)).astype(np.float32))))
        else:
            tensors.append((f"blk.{L}.ffn_up.weight", [d_ff, d_model], 8,
                            _pack_q8_0(rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32))))
            tensors.append((f"blk.{L}.ffn_gate.weight", [d_ff, d_model], 8,
                            _pack_q8_0(rng.normal(0, 0.05, (d_ff, d_model)).astype(np.float32))))
            tensors.append((f"blk.{L}.ffn_down.weight", [d_model, d_ff], 8,
                            _pack_q8_0(rng.normal(0, 0.05, (d_model, d_ff)).astype(np.float32))))

    # distribute tensors round-robin across shards (mirrors Unsloth sharding style)
    shard_tensors = [[] for _ in range(n_shards)]
    for i, t in enumerate(tensors):
        shard_tensors[i % n_shards].append(t)

    def _write_one(path, t_list):
        hdr = bytearray(b"GGUF")
        hdr.extend(struct.pack("<IQQ", 3, len(t_list), len(kv)))
        for k, vt, val in kv:
            hdr.extend(_enc_str(k))
            hdr.extend(struct.pack("<I", vt))
            if vt == 8:
                hdr.extend(_enc_str(val))
            elif vt == 4:
                hdr.extend(struct.pack("<I", val))
            elif vt == 6:
                hdr.extend(struct.pack("<f", val))
            elif vt == 7:
                hdr.extend(struct.pack("<?", 1 if val else 0))
            elif vt == 9:
                et, arr = val
                hdr.extend(struct.pack("<IQ", et, len(arr)))
                for s in arr:
                    hdr.extend(_enc_str(s))
        data_buf = bytearray()
        for name, shape, gtype, raw in t_list:
            hdr.extend(_enc_str(name))
            ggml_dims = list(reversed(shape))
            hdr.extend(struct.pack("<I", len(ggml_dims)))
            for d in ggml_dims:
                hdr.extend(struct.pack("<Q", d))
            off = len(data_buf)
            hdr.extend(struct.pack("<IQ", gtype, off))
            data_buf.extend(raw)
            data_buf.extend(b"\x00" * ((32 - (len(data_buf) % 32)) % 32))
        pad_hdr = (32 - (len(hdr) % 32)) % 32
        hdr.extend(b"\x00" * pad_hdr)
        with open(path, "wb") as fh:
            fh.write(hdr)
            fh.write(data_buf)

    for i in range(n_shards):
        _write_one(os.path.join(out_dir, f"{base_name}-{i + 1:05d}-of-{n_shards:05d}.gguf"), shard_tensors[i])

    if with_mmproj:
        mm_kv = [("general.architecture", 8, "clip"), ("clip.has_vision_encoder", 7, True)]
        mm_tensors = [("mm.patch_embd.weight", [32, 16], 0, b"\x00" * (32 * 16 * 4))]
        hdr = bytearray(b"GGUF")
        hdr.extend(struct.pack("<IQQ", 3, len(mm_tensors), len(mm_kv)))
        for k, vt, val in mm_kv:
            hdr.extend(_enc_str(k))
            hdr.extend(struct.pack("<I", vt))
            if vt == 8:
                hdr.extend(_enc_str(val))
            elif vt == 7:
                hdr.extend(struct.pack("<?", 1 if val else 0))
        data_buf = bytearray()
        for name, shape, gtype, raw in mm_tensors:
            hdr.extend(_enc_str(name))
            ggml_dims = list(reversed(shape))
            hdr.extend(struct.pack("<I", len(ggml_dims)))
            for d in ggml_dims:
                hdr.extend(struct.pack("<Q", d))
            hdr.extend(struct.pack("<IQ", gtype, len(data_buf)))
            data_buf.extend(raw)
        hdr.extend(b"\x00" * ((32 - (len(hdr) % 32)) % 32))
        with open(os.path.join(out_dir, "mmproj-F16.gguf"), "wb") as fh:
            fh.write(hdr)
            fh.write(data_buf)


def _ref_llama_forward(tensors, cfg, tok_ids):
    """Independent reference Llama/GQA/RoPE/SwiGLU forward pass for parity testing."""
    n_L = cfg["num_hidden_layers"]
    d = cfg["hidden_size"]
    nh = cfg["num_attention_heads"]
    nkv = cfg["num_key_value_heads"]
    hd = d // nh
    eps = cfg.get("rms_norm_eps", 1e-5)
    theta = cfg.get("rope_theta", 10000.0)
    T = len(tok_ids)

    def rms(x, w):
        return (x / np.sqrt(np.mean(x * x, axis=-1, keepdims=True) + eps)) * w

    def rope(x, pos):
        inv = 1.0 / (theta ** (np.arange(0, hd, 2, dtype=np.float32) / hd))
        fr = pos[:, None] * inv[None, :]
        c, s = np.cos(fr)[:, None, :], np.sin(fr)[:, None, :]
        o = x.copy()
        o[..., :hd // 2] = x[..., :hd // 2] * c - x[..., hd // 2:] * s
        o[..., hd // 2:] = x[..., hd // 2:] * c + x[..., :hd // 2] * s
        return o

    X = tensors["model.embed_tokens.weight"][tok_ids].astype(np.float32)
    pos = np.arange(T, dtype=np.float32)
    for L in range(n_L):
        h = rms(X, tensors[f"model.layers.{L}.input_layernorm.weight"])
        q = (h @ tensors[f"model.layers.{L}.self_attn.q_proj.weight"].T).reshape(T, nh, hd)
        k = (h @ tensors[f"model.layers.{L}.self_attn.k_proj.weight"].T).reshape(T, nkv, hd)
        v = (h @ tensors[f"model.layers.{L}.self_attn.v_proj.weight"].T).reshape(T, nkv, hd)
        q, k = rope(q, pos), rope(k, pos)
        kr = np.repeat(k, nh // nkv, axis=1)
        vr = np.repeat(v, nh // nkv, axis=1)
        sc = (q.transpose(1, 0, 2) @ kr.transpose(1, 2, 0)) / math.sqrt(hd)
        mask = np.triu(np.ones((T, T), dtype=bool), k=1)
        sc = np.where(mask[None, :, :], -1e9, sc)
        pr = np.exp(sc - np.max(sc, axis=-1, keepdims=True))
        pr /= np.sum(pr, axis=-1, keepdims=True)
        ao = (pr @ vr.transpose(1, 0, 2)).transpose(1, 0, 2).reshape(T, d)
        X = X + ao @ tensors[f"model.layers.{L}.self_attn.o_proj.weight"].T
        h2 = rms(X, tensors[f"model.layers.{L}.post_attention_layernorm.weight"])
        g = h2 @ tensors[f"model.layers.{L}.mlp.gate_proj.weight"].T
        u = h2 @ tensors[f"model.layers.{L}.mlp.up_proj.weight"].T
        silu = g / (1.0 + np.exp(-g))
        X = X + (silu * u) @ tensors[f"model.layers.{L}.mlp.down_proj.weight"].T
    hf = rms(X[-1], tensors["model.norm.weight"])
    return hf @ tensors["lm_head.weight"].T


