_IQ_TEST_VECTORS = None  # populated lazily by _iq_test_vectors() to keep module import light


def _iq_test_vectors():
    """Bit-exact IQ dequantization reference vectors (blocks -> expected f32),
    generated from the reference gguf-py implementations."""
    global _IQ_TEST_VECTORS
    if _IQ_TEST_VECTORS is None:
        _IQ_TEST_VECTORS = json.loads(base64.b64decode(_IQ_TEST_VECTORS_B64).decode("ascii"))
    return _IQ_TEST_VECTORS


def run_self_test():
    print("=== APEIRON-BRAIN v4.0 — Frontier 2014-CPU Self-Test ===")
    tmp_hf = tempfile.mkdtemp(prefix="mock_hf_")
    tmp_moe = tempfile.mkdtemp(prefix="mock_moe_")
    tmp_mem = tempfile.mkdtemp(prefix="brain_mem_")
    tmp_gguf_dir = tempfile.mkdtemp(prefix="mock_gguf_")
    tmp_gguf_mem = tempfile.mkdtemp(prefix="brain_gguf_")
    tmp_exact = tempfile.mkdtemp(prefix="mock_exact_")
    try:
        # 1. BF16 Safetensors + GQA + SwiGLU + Non-divisible d_ff + Memmap Vocab
        _write_mock_hf_safetensors(tmp_hf, n_layers=6, d_model=192, d_ff=350,
                                   dtype="BF16", include_vocab=True, include_gate=True)
        brain = LLMToBrainConverter.convert_model(
            tmp_hf, out_dir=tmp_mem, col_neurons=128, k_synapses=20
        )
        ok, rep = BrainIntegrityKernel.verify(brain, check_liveness=True)
        print(f"  [Kernel BF16+GQA] passed={ok} | {rep}")
        assert ok, rep["reason"]

        cal = brain.calibrate(n_probes=6, ticks_per_probe=8)
        print(f"  [Calibration] avg_fire_rate={cal['avg_fire_rate']*100:.2f}%, "
              f"motor_norm={cal['avg_motor_norm']:.2f}, mean_theta={cal['mean_theta']:.2f}")

        # 2. Subword VocabTokenBridge (memmap vocab + BPE + ridge alignment + AdamW subword training)
        vbridge = VocabTokenBridge(brain)
        align_sim = vbridge.align_cortex(n_probes=32)
        vlosses = vbridge.train_sequence("Sparse cortical neurons spike efficiently on frontier CPUs.", epochs=35, lr=0.06)
        vbridge.save(tmp_mem)
        v_gen, v_st = vbridge.generate_tokens("Sparse cortical ", max_tokens=30, return_stats=True)
        print(f"  [VocabTokenBridge] align={align_sim:.3f}, loss: {vlosses[0]:.2f}->{vlosses[-1]:.2f}, "
              f"speed={v_st['tokens_per_s']:.1f} tok/s, out='{v_gen}'")
        assert vlosses[-1] < 0.5, f"VocabTokenBridge loss did not converge: {vlosses[-1]}"
        assert "neurons" in v_gen and "efficiently" in v_gen, f"Subword recall failed: {v_gen!r}"

        # 2b. Autonomous LanguageQualitySolver (proof-engine certificate, strict non-settlement)
        lm_corpus = "Sparse cortical neurons spike efficiently on frontier CPUs. " * 40
        solver = LanguageQualitySolver(vbridge)
        ids_c = vbridge.tokenizer.encode(lm_corpus, add_bos=True)
        sc = max(96, int(len(ids_c) * 0.9))
        cert = solver.solve(ids_c[:sc], ids_c[sc:], max_positions=60, orders=(2, 3))
        assert cert["pinned"] is not None, f"solver left parameters unpinned: {cert}"
        assert cert["status"] in ("PROVEN_CLASSIFICATION", "CERTIFIED_BOUNDARY"), cert["status"]
        res = cert["residuals"]
        assert res["F3_best_ngram"] < res["F2_trained_cortical"], \
            f"ngram should dominate raw cortical readout: {res}"
        assert res["F4_pinned_mixture"] <= min(res["F2_trained_cortical"],
                                               res["F3_best_ngram"]) + 0.25, \
            f"mixture should not be far worse than best pure branch: {res}"
        vbridge.attach_ngram(cert["ngram"], influence=cert["pinned"]["lam"])
        v_gen2, v_st2 = vbridge.generate_tokens("Sparse cortical ", max_tokens=10, return_stats=True)
        assert v_st2["ngram"] and 0.0 <= v_st2["brain_influence"] <= 1.0
        print(f"  [LanguageQualitySolver] status={cert['status']} pinned={cert['pinned']} "
              f"CE: cortical={res['F2_trained_cortical']:.3f} ngram={res['F3_best_ngram']:.3f} "
              f"mixture={res['F4_pinned_mixture']:.3f} | gen='{v_gen2[:60]}'")

        # 3. Byte-level CorticalLanguageBridge + Disk Reload
        bridge = CorticalLanguageBridge(brain)
        sample = "Sparse cortical neurons spike efficiently on a 2014 CPU. "
        losses = bridge.train_sequence(sample, lr=0.025, epochs=30)
        bridge.save(tmp_mem)
        brain.save(tmp_mem)
        brain.close()

        brain2 = BiologicalBrain.load(tmp_mem)
        assert isinstance(brain2.vocab_data["embed_q8"], np.memmap)
        bridge2 = CorticalLanguageBridge.load_or_create(brain2, tmp_mem)
        gen = bridge2.generate("Sparse cortical ", max_bytes=40)
        print(f"  [Byte Bridge + Memmap Reload] loss: {losses[0]:.2f} -> {losses[-1]:.2f} | '{gen}'")
        assert "neurons spike efficiently" in gen, f"Exact recall failed: {gen!r}"

        # 4. GGUF Q8_0 Frontier Streamer + MoE Safetensors Verification
        gguf_p = os.path.join(tmp_gguf_dir, "tiny_frontier.gguf")
        _write_mock_gguf(gguf_p, n_layers=2, d_model=128, d_ff=256)
        brain_g = LLMToBrainConverter.convert_model(gguf_p, out_dir=tmp_gguf_mem, col_neurons=96, k_synapses=16)
        ok_g, rep_g = BrainIntegrityKernel.verify(brain_g, check_liveness=True)
        assert ok_g, rep_g["reason"]
        vg = VocabTokenBridge(brain_g)
        vg_out, vg_st = vg.generate_tokens("Sparse cortical", max_tokens=4, return_stats=True)
        print(f"  [GGUF Q8_0 Streamer] passed={ok_g} | {vg_st['tokens_per_s']:.1f} tok/s | '{vg_out}'")
        brain_g.close()

        _write_mock_hf_safetensors(tmp_moe, n_layers=2, d_model=128, d_ff=160,
                                   dtype="F16", include_vocab=False, n_experts=4)
        brain_m = LLMToBrainConverter.convert_model(tmp_moe, col_neurons=96, k_synapses=16)
        ok_m, rep_m = BrainIntegrityKernel.verify(brain_m, check_liveness=True)
        assert ok_m, rep_m["reason"]
        print(f"  [MoE 4-Expert Streamer] passed={ok_m} | {rep_m['checks']}")
        brain_m.close()

        # 4b. GGUF IQ-quant dequantization vs embedded bit-exact reference vectors
        for tname, v in _iq_test_vectors().items():
            raw = base64.b64decode(v["blocks"])
            exp = np.frombuffer(base64.b64decode(v["expected"]), np.float32).reshape(v["n_rows"], v["n_cols"])
            got = GGUFStreamReader._dequant_rows(raw, v["gtype"], v["n_rows"], v["n_cols"])
            assert got.shape == exp.shape and np.array_equal(got, exp), f"IQ dequant mismatch: {tname}"
        print(f"  [GGUF IQ Dequant] {len(_iq_test_vectors())} IQ types bit-exact vs reference")

        # 4c. GLM-5.3-Flash-style sharded GGUF: 3 shards + mmproj decoy + IQ/MoE conversion
        tmp_shards = tempfile.mkdtemp(prefix="mock_gguf_shards_")
        _write_mock_gguf_sharded(tmp_shards, n_shards=3, n_layers=4, d_model=256, d_ff=512, n_experts=4)
        r_ms = GGUFStreamReader(tmp_shards)
        assert len(r_ms.files) == 3, f"expected 3 shards, got {len(r_ms.files)}"
        assert r_ms.meta.get("general.architecture") == "glm5-mock"
        assert "mm.patch_embd.weight" not in r_ms.tensors, "mmproj was not skipped"
        assert "token_embd.weight" in r_ms.tensors
        cfg_ms = r_ms.arch_config()
        assert cfg_ms["num_local_experts"] == 4 and cfg_ms["scoring_func"] == "sigmoid"
        assert cfg_ms["routed_scaling_factor"] == 2.5 and cfg_ms["norm_topk_prob"] is True
        assert cfg_ms["num_key_value_heads"] == 2
        for tname in ("token_embd.weight", "output.weight", "blk.1.ffn_gate_exps.weight",
                      "blk.1.ffn_up_exps.weight", "blk.1.ffn_down_exps.weight",
                      "blk.0.attn_output.weight"):
            a = np.concatenate([c for _, c in r_ms.iter_row_chunks(tname, chunk_rows=1)], axis=0)
            b = np.concatenate([c for _, c in r_ms.iter_row_chunks(tname, chunk_rows=512)], axis=0)
            c2 = np.concatenate([c for _, c in r_ms.iter_row_chunks(tname, chunk_rows=3, row_range=(1, 5))], axis=0)
            assert np.array_equal(a, b) and np.array_equal(c2, b[1:5]), f"chunk consistency failed: {tname}"
            assert np.isfinite(b).all(), f"non-finite dequant: {tname}"
        r_direct = GGUFStreamReader(os.path.join(tmp_shards, "mock-llm-UD-IQ1_S-00003-of-00003.gguf"))
        assert len(r_direct.files) == 3, "shard expansion from a single shard file failed"
        tmp_single = tempfile.mkdtemp(prefix="mock_gguf_single_")
        _write_mock_gguf(os.path.join(tmp_single, "model.gguf"), n_layers=1, d_model=64, d_ff=128)
        shutil.copy(os.path.join(tmp_shards, "mmproj-F16.gguf"), tmp_single)
        r_single = GGUFStreamReader(tmp_single)
        assert len(r_single.files) == 1 and r_single.files[0].endswith("model.gguf"), "mmproj probe fallback failed"
        brain_q = LLMToBrainConverter.convert_model(tmp_shards, col_neurons=128, k_synapses=16)
        ok_q, rep_q = BrainIntegrityKernel.verify(brain_q, check_liveness=True)
        assert ok_q, rep_q["reason"]
        vq = VocabTokenBridge(brain_q)
        out_q, st_q = vq.generate_tokens("Sparse cortical", max_tokens=4, return_stats=True)
        print(f"  [GGUF IQ+MoE 3-Shards, mmproj skip] passed={ok_q} | {st_q['tokens_per_s']:.1f} tok/s | '{out_q}'")
        brain_q.close()
        try:
            ExactFrontierEngine.from_model(tmp_shards)
            raise AssertionError("ExactFrontierEngine should reject glm5-mock hybrid GGUF")
        except NotImplementedError:
            pass
        print("  [Hybrid-arch Fail-Fast] ExactFrontierEngine rejects glm5-style GGUF with clear error")

        # 5. ExactFrontierEngine Parity Test (F32 Safetensors vs independent reference + out-of-core streaming)
        rng_ex = np.random.default_rng(123)
        ex_cfg = {
            "model_type": "llama", "num_hidden_layers": 3, "hidden_size": 64,
            "intermediate_size": 128, "num_attention_heads": 4, "num_key_value_heads": 2,
            "rms_norm_eps": 1e-5, "rope_theta": 10000.0, "bos_token_id": 1, "eos_token_id": [2, 3],
        }
        with open(os.path.join(tmp_exact, "config.json"), "w") as fh:
            json.dump(ex_cfg, fh)
        v_toks = ["<unk>", "<s>", "</s>", "<|eot|>", "The", "Ġcapital", "Ġof", "ĠFrance", "Ġis", "ĠParis", "."]
        v_map = {t: i for i, t in enumerate(v_toks)}
        with open(os.path.join(tmp_exact, "tokenizer.json"), "w") as fh:
            json.dump({
                "model": {"vocab": v_map, "merges": []},
                "pre_tokenizer": {"type": "ByteLevel"},
                "added_tokens": [{"id": 1, "content": "<s>"}, {"id": 2, "content": "</s>"}, {"id": 3, "content": "<|eot|>"}],
            }, fh)
        ex_tensors = {
            "model.embed_tokens.weight": rng_ex.normal(0, 0.2, (len(v_toks), 64)).astype(np.float32),
            "model.norm.weight": rng_ex.uniform(0.8, 1.2, 64).astype(np.float32),
            "lm_head.weight": rng_ex.normal(0, 0.2, (len(v_toks), 64)).astype(np.float32),
        }
        for L in range(3):
            ex_tensors[f"model.layers.{L}.input_layernorm.weight"] = rng_ex.uniform(0.8, 1.2, 64).astype(np.float32)
            ex_tensors[f"model.layers.{L}.post_attention_layernorm.weight"] = rng_ex.uniform(0.8, 1.2, 64).astype(np.float32)
            ex_tensors[f"model.layers.{L}.self_attn.q_proj.weight"] = rng_ex.normal(0, 0.1, (64, 64)).astype(np.float32)
            ex_tensors[f"model.layers.{L}.self_attn.k_proj.weight"] = rng_ex.normal(0, 0.1, (32, 64)).astype(np.float32)
            ex_tensors[f"model.layers.{L}.self_attn.v_proj.weight"] = rng_ex.normal(0, 0.1, (32, 64)).astype(np.float32)
            ex_tensors[f"model.layers.{L}.self_attn.o_proj.weight"] = rng_ex.normal(0, 0.1, (64, 64)).astype(np.float32)
            ex_tensors[f"model.layers.{L}.mlp.gate_proj.weight"] = rng_ex.normal(0, 0.1, (128, 64)).astype(np.float32)
            ex_tensors[f"model.layers.{L}.mlp.up_proj.weight"] = rng_ex.normal(0, 0.1, (128, 64)).astype(np.float32)
            ex_tensors[f"model.layers.{L}.mlp.down_proj.weight"] = rng_ex.normal(0, 0.1, (64, 128)).astype(np.float32)
        hdr_ex = {}
        body_ex = bytearray()
        for nm, arr in ex_tensors.items():
            raw = arr.tobytes()
            hdr_ex[nm] = {"dtype": "F32", "shape": list(arr.shape), "data_offsets": [len(body_ex), len(body_ex) + len(raw)]}
            body_ex.extend(raw)
        hb = json.dumps(hdr_ex).encode("utf-8")
        with open(os.path.join(tmp_exact, "model.safetensors"), "wb") as fh:
            fh.write(struct.pack("<Q", len(hb)))
            fh.write(hb)
            fh.write(body_ex)

        # Verify exact logits & text parity (batched prefill, token-by-token, and zero-cache streaming)
        eng_stream = ExactFrontierEngine.from_model(tmp_exact, cache_ram_mb=0)
        eng_cache = ExactFrontierEngine.from_model(tmp_exact, cache_ram_mb=64)
        prompt_ex = "The capital of France is"
        p_ids = eng_stream.tokenizer.encode(prompt_ex)
        ref_logits_0 = _ref_llama_forward(ex_tensors, ex_cfg, p_ids)
        stream_logits_0 = eng_stream.forward_tokens(p_ids)
        max_diff = float(np.max(np.abs(ref_logits_0 - stream_logits_0)))
        assert max_diff < 1e-5, f"Exact logit mismatch: {max_diff}"

        # Compare multi-step autoregressive text between reference, out-of-core stream, and cached engine
        ref_ids = list(p_ids)
        for _ in range(8):
            rl = _ref_llama_forward(ex_tensors, ex_cfg, ref_ids)
            nxt = int(np.argmax(rl))
            if nxt in eng_stream.tokenizer.eos_ids:
                break
            ref_ids.append(nxt)
        ref_text = eng_stream.tokenizer.decode(ref_ids)
        stream_text, _ = eng_stream.generate_tokens(prompt_ex, max_tokens=8, return_stats=True)
        cache_text, _ = eng_cache.generate_tokens(prompt_ex, max_tokens=8, return_stats=True)
        assert stream_text == ref_text and cache_text == ref_text, f"{stream_text!r} vs {ref_text!r}"
        print(f"  [ExactFrontierEngine Parity] max_logit_diff={max_diff:.2e} | exact_text='{stream_text}'")

        # 6. Zero-allocation 2014 CPU Tick Benchmark
        t0 = time.time()
        n_ticks = 200
        total_sp = 0
        for _ in range(n_ticks):
            st = brain2.step(bridge2.byte_to_sdr[ord("S")], reward_signal=0.1, plasticity=True)
            total_sp += st["n_spiked"]
        dt = time.time() - t0
        print(f"  [2014 CPU Throughput] {n_ticks} ticks in {dt:.3f}s ({n_ticks/dt:.1f} ticks/s, "
              f"avg fire_rate={total_sp/(n_ticks*brain2.N)*100:.2f}%)")
        brain2.close()
    finally:
        for d in (tmp_hf, tmp_moe, tmp_mem, tmp_gguf_dir, tmp_gguf_mem, tmp_exact):
            shutil.rmtree(d, ignore_errors=True)
    print("=== Self-Test PASSED ===")


def _interactive_chat(brain=None, vbridge=None, bridge=None, exact_engine=None, args=None):
    print("\n=== APEIRON-BRAIN v4.0 Interactive Frontier Session (type 'exit' or Ctrl-D) ===")
    if exact_engine is not None:
        print(f"Mode=exact (Frontier Parity) | Layers={exact_engine.n_layers} | d_model={exact_engine.d_model} | "
              f"Vocab={exact_engine.vocab_size:,} | CacheLimit={exact_engine.cache_ram_bytes/1e6:.0f} MB")
    else:
        mode = "vocab" if vbridge is not None else "byte"
        print(f"Mode=brain ({mode}) | Neurons={brain.N:,} | Synapses={brain.storage.nnz:,} | "
              f"RAM={brain.storage.ram_bytes()/1e6:.2f} MB")
    max_toks = args.max_tokens if getattr(args, "max_tokens", None) else max(8, args.max_bytes // 2)
    while True:
        try:
            line = input("\nYou> ").strip()
        except EOFError:
            break
        if not line or line.lower() in ("exit", "quit"):
            break
        if exact_engine is not None:
            out, st = exact_engine.generate_tokens(
                line,
                max_tokens=max_toks,
                temperature=args.temperature,
                top_k=args.top_k,
                top_p=args.top_p,
                rep_penalty=args.rep_penalty,
                return_stats=True,
            )
            print(f"Frontier> {out}")
            print(f"  [{st['tokens_per_s']:.2f} tok/s | {st['elapsed_s']:.2f}s | cache={st['cache_mb']:.1f} MB]")
        elif vbridge is not None:
            out, st = vbridge.generate_tokens(
                line,
                max_tokens=max_toks,
                ticks_per_token=args.ticks_per_token,
                temperature=args.temperature,
                top_k=args.top_k,
                top_p=args.top_p,
                rep_penalty=args.rep_penalty,
                return_stats=True,
            )
            print(f"Brain> {out}")
            print(f"  [{st['tokens_per_s']:.1f} tok/s | {st['elapsed_s']:.2f}s | "
                  f"DA={st['drives']['homomorphism']:.2f} ACh={st['drives']['flow_bifurcation']:.2f}]")
        else:
            out = bridge.generate(
                line, max_bytes=args.max_bytes, ticks_per_token=args.ticks_per_token,
                temperature=args.temperature, top_k=args.top_k,
            )
            print(f"Brain> {out}")


def main():
    parser = argparse.ArgumentParser(description="APEIRON-BRAIN v4.0 — Frontier Biological Connectome + Exact Streamer")
    parser.add_argument("--self-test", action="store_true", help="Run BF16, GGUF, MoE, exact parity & throughput tests")
    parser.add_argument("--benchmark-frontier", action="store_true",
                        help="Benchmark streaming 405B-scale frontier LLM architecture on laptop CPU")
    parser.add_argument("--convert-model", type=str, default=None, help="Auto-convert HF safetensors dir OR .gguf file")
    parser.add_argument("--convert-hf", type=str, default=None, help="Path to HuggingFace safetensors directory")
    parser.add_argument("--convert-gguf", type=str, default=None, help="Path to .gguf model file or directory")
    parser.add_argument("--exact-model", type=str, default=None, help="Run exact out-of-core frontier inference directly on HF/GGUF model")
    parser.add_argument("--load-brain", type=str, default=None, help="Load an existing saved brain directory")
    parser.add_argument("--out-dir", type=str, default=None, help="Output directory for memmap connectome")
    parser.add_argument("--mode", type=str, default="auto", choices=["auto", "exact", "brain"],
                        help="Generation mode: 'exact' (exact frontier parity), 'brain' (spiking connectome), or 'auto'")
    parser.add_argument("--cache-ram-mb", type=int, default=512, help="RAM cache budget (MB) for ExactFrontierEngine")
    parser.add_argument("--col-neurons", type=int, default=256, help="Pyramidal neurons per layer column")
    parser.add_argument("--k-synapses", type=int, default=24, help="Max outgoing synapses per neuron")
    parser.add_argument("--calibrate", action="store_true", help="Run homeostatic cortical calibration + ridge alignment")
    parser.add_argument("--train-text", type=str, default=None, help="Train byte/vocab bridge with online STDP on text")
    parser.add_argument("--train-file", type=str, default=None, help="Train byte/vocab bridge from a UTF-8 text file")
    parser.add_argument("--epochs", type=int, default=30, help="Training epochs for --train-text / --train-file")
    parser.add_argument("--prompt", type=str, default=None, help="Generate continuation using byte CorticalLanguageBridge")
    parser.add_argument("--vocab-prompt", type=str, default=None, help="Generate using frontier subword tokenizer/engine")
    parser.add_argument("--chat", action="store_true", help="Start interactive frontier CPU chat loop")
    parser.add_argument("--max-bytes", type=int, default=48, help="Max bytes (or ~2x tokens) to generate")
    parser.add_argument("--max-tokens", type=int, default=None, help="Explicit max tokens to generate for subword/exact mode")
    parser.add_argument("--ticks-per-token", type=int, default=None, help="Cortical ticks per token")
    parser.add_argument("--temperature", type=float, default=0.0, help="Sampling temperature (0=greedy)")
    parser.add_argument("--top-k", type=int, default=40, help="Top-k sampling cutoff")
    parser.add_argument("--top-p", type=float, default=0.95, help="Nucleus top-p sampling cutoff")
    parser.add_argument("--rep-penalty", type=float, default=1.0, help="Repetition penalty")
    parser.add_argument("--ngram-order", type=int, default=4, help="N-gram order for the corpus language model (vocab bridge)")
    parser.add_argument("--brain-influence", type=float, default=None, help="Cortical-logit weight lam in the mixture; default: auto-pinned by LanguageQualitySolver on held-out text")
    parser.add_argument("--lm-positions", type=int, default=800, help="Held-out positions used by the LanguageQualitySolver certificate")
    args = parser.parse_args()

    brain = None
    brain_dir = args.load_brain or args.out_dir
    src_model = args.convert_model or args.convert_hf or args.convert_gguf

    if args.exact_model and not src_model and not args.load_brain:
        exact_eng = ExactFrontierEngine.from_model(args.exact_model, cache_ram_mb=args.cache_ram_mb)
        max_toks = args.max_tokens if args.max_tokens is not None else max(4, args.max_bytes // 2)
        if args.vocab_prompt or args.prompt:
            pr = args.vocab_prompt or args.prompt
            out_t, st = exact_eng.generate_tokens(
                pr, max_tokens=max_toks, temperature=args.temperature,
                top_k=args.top_k, top_p=args.top_p, rep_penalty=args.rep_penalty,
                return_stats=True,
            )
            print(out_t)
            print(f"[ExactFrontier] {st['tokens_per_s']:.2f} tok/s | {st['elapsed_s']:.2f}s | cache={st['cache_mb']:.1f} MB")
        if args.chat:
            _interactive_chat(exact_engine=exact_eng, args=args)
        return

    if src_model:
        if args.convert_gguf:
            brain = LLMToBrainConverter.convert_gguf(
                args.convert_gguf, out_dir=args.out_dir,
                col_neurons=args.col_neurons, k_synapses=args.k_synapses,
            )
        else:
            brain = LLMToBrainConverter.convert_model(
                src_model, out_dir=args.out_dir,
                col_neurons=args.col_neurons, k_synapses=args.k_synapses,
            )
        ok, rep = BrainIntegrityKernel.verify(brain, check_liveness=True)
        print(f"Integrity Kernel: passed={ok} -> {rep}")
    elif args.load_brain:
        writable = bool(args.calibrate or args.train_text or args.train_file or args.out_dir)
        brain = BiologicalBrain.load(args.load_brain, writable=writable)
        ok, rep = BrainIntegrityKernel.verify(brain, check_liveness=True)
        print(f"Loaded Brain ({brain.N:,} neurons, {brain.storage.nnz:,} synapses) | Kernel={ok} {rep['checks']}")
    elif args.benchmark_frontier:
        tmp_f = args.out_dir or tempfile.mkdtemp(prefix="frontier_brain_")
        try:
            brain = LLMToBrainConverter.stream_virtual_frontier(
                n_layers=126, d_model=16384, d_ff=53248,
                col_neurons=args.col_neurons, k_synapses=args.k_synapses, out_dir=tmp_f,
            )
            ok, rep = BrainIntegrityKernel.verify(brain, check_liveness=True)
            print(f"Integrity Kernel: passed={ok} -> {rep}")
            t0 = time.time()
            s0, s1 = brain.sensory_slice
            stim = np.zeros(s1 - s0, dtype=np.float32)
            stim[: max(12, (s1 - s0) // 12)] = 1.40
            mot, stats = brain.think(stim, n_ticks=20, plasticity=True)
            dt = time.time() - t0
            avg_fr = np.mean([s["fire_rate"] for s in stats]) * 100.0
            print(f"20 Cognitive Ticks on 126-layer Frontier Brain: {dt:.3f}s "
                  f"({20/dt:.1f} ticks/s, avg sparse firing={avg_fr:.2f}%, motor_norm={np.linalg.norm(mot):.2f})")
            brain.close()
        finally:
            if not args.out_dir:
                shutil.rmtree(tmp_f, ignore_errors=True)
        return

    if brain is not None:
        try:
            has_vocab = bool(brain.vocab_data and "vocab" in brain.vocab_data)
            vbridge = (VocabTokenBridge.load_or_create(brain, brain_dir)
                       if (has_vocab and brain_dir) else (VocabTokenBridge(brain) if has_vocab else None))
            bridge = (CorticalLanguageBridge.load_or_create(brain, brain_dir)
                      if brain_dir else CorticalLanguageBridge(brain))

            if args.calibrate:
                cal = brain.calibrate()
                print(f"Calibration: {cal}")
                if vbridge is not None:
                    asim = vbridge.align_cortex()
                    print(f"Cortex-to-Head Alignment cosine={asim:.3f}")

            train_corpus = args.train_text
            if args.train_file and os.path.exists(args.train_file):
                with open(args.train_file, "r", encoding="utf-8", errors="ignore") as fh:
                    train_corpus = fh.read()

            if train_corpus:
                if args.vocab_prompt or (vbridge is not None and not args.prompt):
                    solver = LanguageQualitySolver(vbridge)
                    tok_all = vbridge.tokenizer.encode(train_corpus, add_bos=True)
                    split = max(96, int(len(tok_all) * 0.9))
                    tok_train, tok_meas = tok_all[:split], tok_all[split:]
                    pre = solver.solve(tok_train, tok_meas[:min(240, len(tok_meas))],
                                       max_positions=240, orders=(args.ngram_order,))
                    f1_ce = pre["residuals"]["F2_trained_cortical"]
                    stdp_text = train_corpus if len(train_corpus) <= 20000 else train_corpus[:20000]
                    ep = args.epochs if len(stdp_text) <= 20000 else min(args.epochs, 2)
                    losses = vbridge.train_sequence(
                        stdp_text, epochs=ep, ticks_per_token=args.ticks_per_token
                    )
                    print(f"Trained Subword VocabBridge+STDP: loss {losses[0]:.3f} -> {losses[-1]:.3f}")
                    cert = solver.solve(tok_train, tok_meas,
                                        max_positions=args.lm_positions, f1_ce=f1_ce)
                    lam = args.brain_influence if args.brain_influence is not None else cert["pinned"]["lam"]
                    vbridge.attach_ngram(cert["ngram"], influence=lam if lam is not None else 0.35)
                    res = cert["residuals"]
                    print(f"[LanguageQualitySolver] status={cert['status']} | "
                          f"pinned order={cert['pinned']['order']} lam*={lam} | CE nats/tok: "
                          f"F1={res['F1_untrained_cortical']} F2={res['F2_trained_cortical']} "
                          f"F3*={res['F3_best_ngram']} F4*={res['F4_pinned_mixture']}")
                    for e in cert["eliminated"]:
                        print(f"  [eliminated] {e['family']}: {e['reason'][:110]}")
                    for g in cert["gaps"]:
                        print(f"  [gap] {g['tag']}: {g['detail'][:110]}")
                    if brain_dir:
                        cert.pop("ngram", None)
                        with open(os.path.join(brain_dir, "language_certificate.json"), "w", encoding="utf-8") as fh:
                            json.dump(cert, fh, indent=2)
                else:
                    losses = bridge.train_sequence(
                        train_corpus, epochs=args.epochs, ticks_per_token=args.ticks_per_token
                    )
                    print(f"Trained Byte Bridge+STDP: loss {losses[0]:.3f} -> {losses[-1]:.3f}")

            # Resolve exact frontier engine if source model is available and exact parity is requested/auto
            model_src = args.exact_model or src_model or brain.source_model_path
            if args.mode == "exact" and not (model_src and os.path.exists(model_src)):
                raise FileNotFoundError(f"--mode exact requires a valid source model path, got: {model_src!r}")
            use_exact = (
                (args.mode == "exact")
                or (args.mode == "auto" and not train_corpus and model_src and os.path.exists(model_src))
            )
            exact_eng = None
            if use_exact and (args.vocab_prompt or args.prompt or args.chat):
                try:
                    exact_eng = ExactFrontierEngine.from_model(model_src, cache_ram_mb=args.cache_ram_mb)
                except NotImplementedError as e:
                    if args.mode == "exact":
                        raise
                    print(f"[ExactFrontier] unavailable for this model: {e}")
                    print("[Fallback] using brain (VocabTokenBridge) generation instead")

            max_toks = args.max_tokens if args.max_tokens is not None else max(4, args.max_bytes // 2)
            if args.prompt:
                if exact_eng is not None and not args.vocab_prompt:
                    out_t, st = exact_eng.generate_tokens(
                        args.prompt,
                        max_tokens=max_toks,
                        temperature=args.temperature,
                        top_k=args.top_k,
                        top_p=args.top_p,
                        rep_penalty=args.rep_penalty,
                        return_stats=True,
                    )
                    print(out_t)
                    print(f"[ExactFrontier] {st['tokens_per_s']:.2f} tok/s | {st['elapsed_s']:.2f}s | cache={st['cache_mb']:.1f} MB")
                else:
                    print(bridge.generate(
                        args.prompt, max_bytes=args.max_bytes,
                        ticks_per_token=args.ticks_per_token,
                        temperature=args.temperature, top_k=args.top_k,
                    ))
            if args.vocab_prompt:
                if exact_eng is not None:
                    out_t, st = exact_eng.generate_tokens(
                        args.vocab_prompt,
                        max_tokens=max_toks,
                        temperature=args.temperature,
                        top_k=args.top_k,
                        top_p=args.top_p,
                        rep_penalty=args.rep_penalty,
                        return_stats=True,
                    )
                    print(out_t)
                    print(f"[ExactFrontier] {st['tokens_per_s']:.2f} tok/s | {st['elapsed_s']:.2f}s | cache={st['cache_mb']:.1f} MB")
                else:
                    if vbridge is None:
                        raise ValueError("Loaded brain has no HF/GGUF vocab_data for --vocab-prompt")
                    out_t, st = vbridge.generate_tokens(
                        args.vocab_prompt,
                        max_tokens=max_toks,
                        ticks_per_token=args.ticks_per_token,
                        temperature=args.temperature,
                        top_k=args.top_k,
                        top_p=args.top_p,
                        rep_penalty=args.rep_penalty,
                        return_stats=True,
                    )
                    print(out_t)
                    print(f"[VocabBridge] {st['tokens_per_s']:.1f} tok/s | {st['elapsed_s']:.2f}s | drives={st['drives']}")
            if args.chat:
                _interactive_chat(brain=brain, vbridge=vbridge, bridge=bridge, exact_engine=exact_eng, args=args)

            if args.out_dir:
                brain.save(args.out_dir)
                bridge.save(args.out_dir)
                if vbridge is not None:
                    vbridge.save(args.out_dir)
        finally:
            brain.close()
        return

    run_self_test()


if __name__ == "__main__":
    main()
